@app.route("/static/img/<path:fname>")
def serve_static_img(fname):
    """Sirve logos de marca aunque el cwd de Railway no sea el ideal."""
    from flask import send_from_directory
    bases = [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "static", "img"),
        os.path.join("static", "img"),
        os.path.abspath("static/img"),
    ]
    for base in bases:
        path = os.path.join(base, fname)
        if os.path.isfile(path):
            return send_from_directory(base, fname)
    # fallback SVG response
    from flask import Response
    # Si piden logo-procsis o logo corporativo → texto PROCSIS; resto EduTrack solo producto
    label = "PROCSIS"
    low = (fname or "").lower()
    if "edutrack" in low and "procsis" not in low:
        label = "EduTrack"
    svg = """<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 240 80'>
      <rect width='240' height='80' rx='8' fill='#0B2D57'/>
      <text x='120' y='48' text-anchor='middle' fill='white' font-family='Arial,sans-serif' font-size='22' font-weight='bold'>""" + label + """</text>
    </svg>"""
    return Response(svg, mimetype="image/svg+xml")



# ── Seguridad: cabeceras + rate limit login ─────────────────────────────────
_login_attempts = {}  # ip -> [timestamps]


def _client_ip():
    fwd = request.headers.get("X-Forwarded-For") or ""
    if fwd:
        return fwd.split(",")[0].strip()[:60]
    return (request.remote_addr or "0.0.0.0")[:60]


def _password_ok(pw):
    """Política mínima de contraseña."""
    pw = pw or ""
    if len(pw) < 8:
        return False, "La contraseña debe tener al menos 8 caracteres."
    if pw.isdigit() or pw.lower() in ("12345678", "password", "contraseña", "edutrack1"):
        return False, "Contraseña demasiado débil."
    return True, ""


def _rate_limit_login(max_attempts=8, window_sec=120, portal="general"):
    """Límite de login POR PORTAL e IP (no comparte bloqueo entre gerencia/ventas/soporte/cobranza).
    Gerencia: sin bloqueo (portal='gerencia' → siempre OK).
    Otros: ventana corta (2 min) y más intentos para no trabar operación."""
    import time
    if (portal or "").lower() in ("gerencia", "gerente", "hq", "admin"):
        return True, 0
    ip = _client_ip()
    key = f"{ip}:{portal or 'general'}"
    now = time.time()
    arr = [t for t in _login_attempts.get(key, []) if now - t < window_sec]
    _login_attempts[key] = arr
    if len(arr) >= max_attempts:
        return False, max(1, int(window_sec - (now - arr[0])))
    return True, 0


def _rate_limit_fail(portal="general"):
    import time
    if (portal or "").lower() in ("gerencia", "gerente", "hq", "admin"):
        return
    ip = _client_ip()
    key = f"{ip}:{portal or 'general'}"
    _login_attempts.setdefault(key, []).append(time.time())


def _rate_limit_ok(portal="general"):
    ip = _client_ip()
    key = f"{ip}:{portal or 'general'}"
    _login_attempts.pop(key, None)
    # compat: limpiar clave vieja solo-IP
    _login_attempts.pop(ip, None)


def _rate_limit_clear_all(ip=None):
    """Soporte/Gerencia: limpia bloqueos de login (reinicio de acceso)."""
    if ip:
        keys = [k for k in list(_login_attempts.keys()) if str(k).startswith(str(ip))]
        for k in keys:
            _login_attempts.pop(k, None)
        _login_attempts.pop(ip, None)
        return len(keys)
    n = len(_login_attempts)
    _login_attempts.clear()
    return n


# ── Rate limiting genérico (no solo login): protege PDFs, formularios públicos, etc. ──
_endpoint_hits = {}  # "ip:endpoint" -> [timestamps]


def _rate_limit(nombre, max_veces=20, ventana_seg=60):
    """Límite genérico por IP+endpoint. Uso: ok, espera = _rate_limit('contrato-digital', 5, 60)."""
    import time
    ip = _client_ip()
    key = f"{ip}:{nombre}"
    now = time.time()
    arr = [t for t in _endpoint_hits.get(key, []) if now - t < ventana_seg]
    if len(arr) >= max_veces:
        _endpoint_hits[key] = arr
        return False, max(1, int(ventana_seg - (now - arr[0])))
    arr.append(now)
    _endpoint_hits[key] = arr
    return True, 0


def _rate_limit_response(espera_seg):
    # espera_seg ya viene en segundos
    try:
        espera_seg = max(1, int(espera_seg))
    except Exception:
        espera_seg = 30
    resp = page(
        "Demasiadas solicitudes",
        f"""<div style="font-family:Tahoma,Segoe UI,Arial;max-width:480px;margin:60px auto;text-align:center;padding:20px;background:#f0f0f0;border:2px solid #808080">
        <h1 style="color:#b91c1c;font-size:18px">Demasiadas solicitudes</h1>
        <p style="font-size:13px">Espere aproximadamente <b>{espera_seg}</b> segundos e intente de nuevo.<br>
        Si es Gerencia/Soporte, use <b>Reinicio de acceso</b> en el panel de Soporte.</p>
        <a href="javascript:history.back()">← Volver</a></div>""",
    )
    return resp, 429


# ── Escape HTML: evita inyección de scripts (XSS) al mostrar texto ingresado por usuarios ──
import html as _html_mod


def _esc(valor):
    """Escapa <, >, &, comillas. Usar SIEMPRE al insertar texto de formularios dentro de HTML."""
    if valor is None:
        return ""
    return _html_mod.escape(str(valor), quote=True)


@app.after_request
def _security_headers(resp):
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["X-Frame-Options"] = "SAMEORIGIN"
    resp.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    resp.headers["Permissions-Policy"] = "camera=(self), microphone=(), geolocation=()"
    resp.headers["X-XSS-Protection"] = "1; mode=block"
    # No filtrar CSP agresivo en planilla (inline JS); baseline:
    if not request.path.startswith("/static"):
        resp.headers.setdefault(
            "Content-Security-Policy",
            "default-src 'self'; img-src 'self' data: blob: https:; style-src 'self' 'unsafe-inline'; "
            "script-src 'self' 'unsafe-inline'; connect-src 'self'; frame-ancestors 'self'",
        )
    return resp



