# Driver Postgres: preferir psycopg2 (comun en Railway). NUNCA dejar postgresql://
# ni postgresql+psycopg:// sin el paquete "psycopg" instalado (rompe el deploy).
def _pick_pg_driver(url):
    if not url or "postgres" not in url:
        return url
    # quitar driver previo
    for prefix in (
        "postgresql+psycopg2://",
        "postgresql+psycopg://",
        "postgresql+pg8000://",
        "postgresql://",
        "postgres://",
    ):
        if url.startswith(prefix):
            rest = url[len(prefix):]
            break
    else:
        return url
    # detectar paquete disponible
    driver = "psycopg2"
    try:
        import psycopg2  # noqa: F401
        driver = "psycopg2"
    except Exception:
        try:
            import psycopg  # noqa: F401
            driver = "psycopg"
        except Exception:
            # Ultimo recurso: psycopg2 (mensaje claro si falta en requirements)
            driver = "psycopg2"
            print("ADVERTENCIA: ni psycopg2 ni psycopg instalados. Agregue psycopg2-binary a requirements.txt")
    return "postgresql+" + driver + "://" + rest

DATABASE_URL = _pick_pg_driver(DATABASE_URL)

