    # PENDIENTE (padre solicitó) | APROBADA (coord) | RECHAZADA | ACTIVA (=aprobada lista portería) | USADA
    estado = db.Column(db.String(40), default="PENDIENTE")
    usado_en = db.Column(db.String(40), default="")
