class Institucion(db.Model):
    """Multi-inquilino: cada colegio/institución es un tenant independiente."""
    __tablename__ = "instituciones"
    id = db.Column(db.Integer, primary_key=True)
    codigo = db.Column(db.String(40), unique=True, nullable=False)
    nombre = db.Column(db.String(220), nullable=False)
    sede = db.Column(db.String(120), default="PRINCIPAL")
    dane = db.Column(db.String(40), default="")
    nit = db.Column(db.String(40), default="")
    direccion = db.Column(db.String(255), default="")
    resolucion = db.Column(db.String(160), default="")
    municipio = db.Column(db.String(120), default="")
    departamento = db.Column(db.String(120), default="")
    logo = db.Column(db.Text, default="/static/img/logo-edutrack.png")
    estado = db.Column(db.String(30), default="ACTIVA")  # ACTIVA, SUSPENDIDA, MANTENIMIENTO, CANCELACION_PENDIENTE, ARCHIVADA
    plan = db.Column(db.String(40), default="Basico")  # Basico | Institucional | Premium

    promo_id = db.Column(db.Integer, default=0)
    valor_mensual_con_descuento = db.Column(db.Integer, default=0)
    valor_mensual_pleno = db.Column(db.Integer, default=0)
    fecha_activacion_tarifa = db.Column(db.String(40), default="")
    fecha_caducidad_descuento = db.Column(db.String(40), default="")
    flag_tarifa_plena_aplicada = db.Column(db.Boolean, default=False)
    nombre_promo_aplicada = db.Column(db.String(100), default="")
    porcentaje_promo_aplicada = db.Column(db.Float, default=0.0)
    fecha_creacion = db.Column(db.String(20), default="")
    notas = db.Column(db.Text, default="")
    # Licencia / facturación comercial
    fecha_inicio_licencia = db.Column(db.String(20), default="")
    fecha_vencimiento = db.Column(db.String(20), default="")  # fecha de pago / fin de periodo
    dias_aviso = db.Column(db.Integer, default=7)  # avisos desde N días antes
    dias_conservacion = db.Column(db.Integer, default=30)  # retención tras suspensión
    fecha_suspension = db.Column(db.String(20), default="")
    motivo_bloqueo = db.Column(db.String(255), default="")
    fecha_solicitud_cancelacion = db.Column(db.String(20), default="")
    motivo_cancelacion = db.Column(db.Text, default="")
    contacto_facturacion = db.Column(db.String(160), default="")
    # Cambio de plan programado a fecha de corte
    plan_pendiente = db.Column(db.String(40), default="")  # nuevo plan a aplicar
    fecha_corte_plan = db.Column(db.String(20), default="")  # YYYY-MM-DD cuando se aplica
    # Cancelación de servicio + facturación
    fecha_fin_servicio = db.Column(db.String(20), default="")  # fecha efectiva fin (cuenta regresiva)
    no_generar_facturas = db.Column(db.Boolean, default=False)  # True = ciclo no genera más facturas nuevas
    factura_final_generada = db.Column(db.Boolean, default=False)  # prorrateo del mes en curso ya emitido
    # Info institucional (consulta de datos del titular) y bloqueo/seguridad
    rector = db.Column(db.String(160), default="")
    tipo_bloqueo = db.Column(db.String(30), default="")  # "" | SEGURIDAD | MORA (persistido por Bloqueo y Seguridad)
    ultima_sincronizacion = db.Column(db.String(30), default="")  # sello del módulo de Aprovisionamiento Escolar


