class PersonalLogix(db.Model):
    """Equipo Procsis: credenciales internas y carné corporativo."""
    __tablename__ = "personal_logix"
    id = db.Column(db.Integer, primary_key=True)
    codigo = db.Column(db.String(40), unique=True, nullable=False, index=True)
    nombre = db.Column(db.String(160), nullable=False)
    documento = db.Column(db.String(40), default="")
    cargo = db.Column(db.String(120), default="")
    area = db.Column(db.String(80), default="Soporte")  # Soporte, Comercial, Gerencia, Marketing
    correo = db.Column(db.String(160), default="")
    telefono = db.Column(db.String(40), default="")
    usuario_sistema = db.Column(db.String(120), default="")  # link opcional a Usuario.usuario
    activo = db.Column(db.Boolean, default=True)
    fecha_alta = db.Column(db.String(20), default="")


class FeatureFlag(db.Model):

    """Flags por institución o globales (institucion_id NULL = global)."""
    __tablename__ = "feature_flags"
    id = db.Column(db.Integer, primary_key=True)
    institucion_id = db.Column(db.Integer, db.ForeignKey("instituciones.id"), nullable=True, index=True)
    clave = db.Column(db.String(80), nullable=False)  # eduaura, reportes_padres, portal_movil, etc.
    activo = db.Column(db.Boolean, default=False)
    descripcion = db.Column(db.String(255), default="")
    plan_minimo = db.Column(db.String(40), default="Basico")  # Basico / Institucional / Premium



class Asignatura(db.Model):
    __tablename__ = "asignaturas"
    id = db.Column(db.Integer, primary_key=True)
    institucion_id = db.Column(db.Integer, db.ForeignKey("instituciones.id"), nullable=True, index=True)
    nombre = db.Column(db.String(120), nullable=False)
    codigo = db.Column(db.String(40), default="")
    area = db.Column(db.String(80), default="")  # Ciencias, Humanidades, etc.


class DirectorGrupo(db.Model):
    __tablename__ = "directores_grupo"
    id = db.Column(db.Integer, primary_key=True)
    institucion_id = db.Column(db.Integer, db.ForeignKey("instituciones.id"), nullable=True, index=True)
    grado = db.Column(db.String(30), nullable=False)
    nombre_docente = db.Column(db.String(160), nullable=False)
    usuario_id = db.Column(db.Integer, db.ForeignKey("usuarios.id"), nullable=True)


class HorarioBloque(db.Model):
    """Bloque de horario escolar: día + hora + grado + asignatura + docente."""
    __tablename__ = "horarios_bloques"
    id = db.Column(db.Integer, primary_key=True)
    institucion_id = db.Column(db.Integer, db.ForeignKey("instituciones.id"), nullable=True, index=True)
    grado = db.Column(db.String(30), nullable=False)
    dia = db.Column(db.String(20), nullable=False)  # Lunes..Viernes
    hora_inicio = db.Column(db.String(10), nullable=False)  # 07:00
    hora_fin = db.Column(db.String(10), nullable=False)
    asignatura = db.Column(db.String(120), nullable=False)
    docente = db.Column(db.String(160), default="")
    aula = db.Column(db.String(60), default="")


class Plataforma(db.Model):
    """Marca Procsis / soporte (no es un colegio)."""
    __tablename__ = "plataforma"
    id = db.Column(db.Integer, primary_key=True)
    empresa = db.Column(db.String(160), default="Procsis")
    nombre_producto = db.Column(db.String(160), default="EduTrack")  # nombre global del producto
    slogan = db.Column(db.String(255), default="Tecnología para una educación moderna y responsable")
    logo_path = db.Column(db.Text, default="/static/img/logo-procsis.png")
    desarrollador = db.Column(db.String(120), default="Sebastián López")
    telefono_soporte = db.Column(db.String(40), default="3105615621")
    email_soporte = db.Column(db.String(160), default="soporte@procsis.com")
    telefono_cartera = db.Column(db.String(40), default="3126285480")
    email_cartera = db.Column(db.String(160), default="carteraedutrackqr@gmail.com")
    web = db.Column(db.String(160), default="")
    notas = db.Column(db.Text, default="")
    # Datos legales de la empresa (Procsis), para documentos oficiales (admisión, contratos, etc.)
    nit = db.Column(db.String(40), default="")
    codigo_dane = db.Column(db.String(40), default="")
    direccion = db.Column(db.String(255), default="")
    ciudad = db.Column(db.String(120), default="")
    representante_legal = db.Column(db.String(160), default="")
    bootstrap_usado = db.Column(db.Boolean, default=False)  # candado: reinicio de emergencia de staff, un solo uso
    # Textos editables del centro de ayuda (/pqr-info) y kit legal de ventas
    pqr_presentacion = db.Column(db.Text, default="")
    pqr_radicado = db.Column(db.Text, default="")
    pqr_facturacion = db.Column(db.Text, default="")
    pqr_plazo = db.Column(db.Text, default="")
    kit_habeas_data = db.Column(db.Text, default="")
    kit_confirmacion_contrato = db.Column(db.Text, default="")
    # Centro de actualizaciones (visible en login)
    version_sistema = db.Column(db.String(40), default="2.5.0")
    novedades = db.Column(db.Text, default="")
    faq = db.Column(db.Text, default="")
    mantenimiento_programado = db.Column(db.Text, default="")
    habeas_data = db.Column(db.Text, default="")
    reinicio_aviso = db.Column(db.String(255), default="")
    novedad_img1 = db.Column(db.String(255), default="")
    novedad_img2 = db.Column(db.String(255), default="")
    novedad_img3 = db.Column(db.String(255), default="")
    novedad_img1_cap = db.Column(db.String(120), default="")
    novedad_img2_cap = db.Column(db.String(120), default="")
    novedad_img3_cap = db.Column(db.String(120), default="")
    novedad_img4 = db.Column(db.String(255), default="")
    novedad_img5 = db.Column(db.String(255), default="")
    novedad_img4_cap = db.Column(db.String(120), default="")
    novedad_img5_cap = db.Column(db.String(120), default="")
    hero_chip = db.Column(db.String(120), default="Plataforma institucional · Acceso seguro")
    hero_titulo = db.Column(db.String(220), default="Tecnología educativa con control y transparencia")
    hero_texto = db.Column(db.Text, default="")
    # Landing pública /ventas (editable desde Gerencia)
    ventas_landing_titulo = db.Column(db.String(255), default="")
    ventas_landing_subtitulo = db.Column(db.Text, default="")
    ventas_landing_precio_desde = db.Column(db.Float, default=149000.0)
    ventas_landing_cta_demo = db.Column(db.String(160), default="")
    ventas_landing_cta_sub = db.Column(db.String(255), default="")
    ventas_landing_nota_planes = db.Column(db.String(255), default="")
    ventas_landing_h2_planes = db.Column(db.String(160), default="")
    ventas_landing_img = db.Column(db.String(255), default="")  # imagen hero / banner
    actividad_ciiu = db.Column(db.String(20), default="6201")
    regimen_dian = db.Column(db.String(80), default="No responsable de IVA")
    email_empresa = db.Column(db.String(160), default="")
    telefono_empresa = db.Column(db.String(40), default="")
    logo_es_custom = db.Column(db.Boolean, default=False)  # True solo si subieron logo PROCSIS en Datos empresa
    css_inyectado = db.Column(db.Text, default="")  # CSS custom desde Consola Desarrollo
    # Personalización de logins (colores / diseño)
    login_color_primario = db.Column(db.String(20), default="#0B2D57")
    login_color_acento = db.Column(db.String(20), default="#f59e0b")
    login_color_fondo = db.Column(db.String(20), default="#f8fafc")
    login_titulo = db.Column(db.String(160), default="")
    login_subtitulo = db.Column(db.Text, default="")
    # Pie legal del login de colegios (estilo Apple, editable desde Gerencia)
    login_pie_p1 = db.Column(db.Text, default="")
    login_pie_p2 = db.Column(db.Text, default="")
    login_pie_extra = db.Column(db.Text, default="")
    sitio_oficial_url = db.Column(db.String(255), default="/procsis")
    login_logo_path = db.Column(db.String(255), default="")
    login_mostrar_marca = db.Column(db.Boolean, default=True)
    anuncio_activo = db.Column(db.Boolean, default=False)
    anuncio_titulo = db.Column(db.String(220), default="")
    anuncio_cuerpo = db.Column(db.Text, default="")
    anuncio_cuenta = db.Column(db.String(255), default="")
    anuncio_version = db.Column(db.String(40), default="1")
    anuncio_img1 = db.Column(db.Text, default="")
    anuncio_img2 = db.Column(db.Text, default="")
    tema_fuente = db.Column(db.String(80), default="Segoe UI")
    tema_color_secundario = db.Column(db.String(20), default="#F2C12E")
    tema_color_primario = db.Column(db.String(20), default="#0B2D57")
    tema_color_acento = db.Column(db.String(20), default="#1e40af")
    tema_color_fondo = db.Column(db.String(20), default="#f1f5f9")
    contacto_publico_tel = db.Column(db.String(40), default="")
    contacto_publico_email = db.Column(db.String(120), default="")
    contacto_whatsapp_ventas = db.Column(db.String(40), default="")
    contacto_whatsapp_soporte = db.Column(db.String(40), default="")
    # Conexión de correo saliente (Gmail con contraseña de aplicación) — reemplaza a
    # las variables de entorno SOPORTE_EMAIL/SOPORTE_PASSWORD para poder conectarla
    # desde el panel sin tocar Railway, igual que la conexión de Wompi/tesorería.
    smtp_correo = db.Column(db.String(160), default="")
    smtp_password = db.Column(db.String(255), default="")  # contraseña de aplicación de Gmail
    smtp_conectado_por = db.Column(db.String(120), default="")
    smtp_conectado_en = db.Column(db.String(20), default="")
    # Segunda cuenta, exclusiva para el envío masivo/automático de notificaciones de
    # PQR (separada de la cuenta general de soporte para no saturarla ni arriesgar
    # que Gmail la marque como spam por volumen).
    smtp_notif_correo = db.Column(db.String(160), default="")
    smtp_notif_password = db.Column(db.String(255), default="")
    smtp_notif_conectado_por = db.Column(db.String(120), default="")
    smtp_notif_conectado_en = db.Column(db.String(20), default="")
    horario_lunes = db.Column(db.String(80), default="8:00 a.m. - 12:30 p.m. y 2:00 p.m. - 5:00 p.m.")
    horario_semana = db.Column(db.String(80), default="7:00 a.m. - 12:30 p.m. y 2:00 p.m. - 5:00 p.m.")
    soporte_mensaje = db.Column(db.Text, default="")
    # Página corporativa /procsis (editable desde Gerencia)
    corp_tag = db.Column(db.String(120), default="SOLUCIONES DIGITALES · COLOMBIA")
    corp_hero_titulo = db.Column(db.String(255), default="Software y solución digital para instituciones educativas")
    corp_hero_texto = db.Column(db.Text, default="Diseñamos y operamos plataformas serias para colegios: gestión académica, reportes de coordinación, boletines y acompañamiento a directivos y docentes.")
    corp_top_derecha = db.Column(db.String(160), default="Software para instituciones educativas · Colombia")
    corp_barra_extra = db.Column(db.String(255), default="Facturación / Cartera / Ventas")
    corp_brand_nombre = db.Column(db.String(80), default="PROCSIS")
    corp_brand_sub = db.Column(db.String(80), default="Innovación que gestiona")
    corp_nosotros_titulo = db.Column(db.String(120), default="Quiénes somos")
    corp_nosotros_texto = db.Column(db.Text, default="Equipo enfocado en software educativo confiable, claro y listo para operar en colegios reales.")
    corp_cta_titulo = db.Column(db.String(160), default="¿Listo para ver EduTrack en su colegio?")
    corp_cta_texto = db.Column(db.Text, default="Solicite una demostración o hable con un asesor comercial.")
    corp_footer_texto = db.Column(db.Text, default="Soluciones digitales para el sector educativo. Plataforma académica multi-institucional.")
    corp_portafolio_titulo = db.Column(db.String(160), default="Portafolio de soluciones")
    corp_portafolio_texto = db.Column(db.Text, default="Productos y servicios para la gestión académica y administrativa de instituciones educativas.")
    corp_hero_fondo = db.Column(db.Text, default="")  # data URI o URL — persiste en BD (Railway no borra)
    corp_caracteristicas = db.Column(db.Text, default="")  # lineas: titulo|descripcion por fila
    corp_empresa_puntos = db.Column(db.Text, default="")  # puntos de la empresa
    corp_btn1_texto = db.Column(db.String(80), default="Conocer PROCSIS")
    corp_btn1_url = db.Column(db.String(160), default="#nosotros")
    corp_btn2_texto = db.Column(db.String(80), default="Hablar con un asesor")
    corp_btn2_url = db.Column(db.String(160), default="")
    corp_btn3_texto = db.Column(db.String(80), default="Entrar al sistema")
    corp_btn3_url = db.Column(db.String(160), default="/login")
    # Backoffice login (panel visual derecho — editable desde Gerencia)
    bo_login_titulo = db.Column(db.String(200), default="EduTrack · Operación interna PROCSIS")
    bo_login_texto = db.Column(db.String(300), default="Gestión académica, soporte y control para instituciones educativas.")
    bo_login_img = db.Column(db.Text, default="")  # data URI o URL
    bo_login_img2 = db.Column(db.Text, default="")  # imagen secundaria opcional
    salida_segura_activa = db.Column(db.Boolean, default=True)  # cierra sesión al cerrar pestaña


