class SolicitudCancelacion(db.Model):
    """Cancelación de servicio: portal colegio, PQR, soporte o gerencia. Cuenta regresiva + corte de facturación."""
    __tablename__ = "solicitudes_cancelacion"
    id = db.Column(db.Integer, primary_key=True)
    institucion_id = db.Column(db.Integer, db.ForeignKey("instituciones.id"), nullable=False, index=True)
    fecha = db.Column(db.String(20), default="")
    hora = db.Column(db.String(20), default="")
    solicitado_por = db.Column(db.String(120), default="")
    motivo = db.Column(db.Text, default="")
    dias_anticipacion = db.Column(db.Integer, default=5)
    estado = db.Column(db.String(40), default="PENDIENTE")  # PENDIENTE, APROBADA, RECHAZADA, EJECUTADA, EN_CUENTA_REGRESIVA
    respuesta_soporte = db.Column(db.Text, default="")
    fecha_efectiva = db.Column(db.String(20), default="")  # fin de servicio / fin cuenta regresiva
    canal = db.Column(db.String(40), default="PORTAL")  # PORTAL | PQR | SOPORTE | GERENCIA | RETENCION
    factura_final_id = db.Column(db.Integer, default=0)  # id FacturaCobro prorrateada
    valor_prorrateo = db.Column(db.Float, default=0.0)


class TicketPQR(db.Model):
    """PQR general: cancelación, pagos, seguimiento, quejas, etc."""
    __tablename__ = "tickets_pqr"
    id = db.Column(db.Integer, primary_key=True)
    radicado = db.Column(db.String(40), unique=True, nullable=False, index=True)
    ticket = db.Column(db.String(12), unique=True, nullable=False, index=True)
