def plan_institucion(inst=None):
    if inst is None:
        iid = institucion_id_actual()
        inst = Institucion.query.get(iid) if iid else None
    plan = (inst.plan if inst else None) or (getattr(inst, "plan_codigo", None) if inst else None) or "Basico"
    if plan not in PLANES_EDUTRACK:
        mapa = {
            "basico": "Basico", "básico": "Basico", "demo": "Basico", "piloto": "Basico",
            "institucional": "Institucional", "pro": "Premium", "premium": "Premium",
            "qr_basico": "qr_basico", "qr_plus": "qr_plus", "qr_institucional": "qr_institucional",
        }
        plan = mapa.get(str(plan).strip().lower(), plan)
    if plan not in PLANES_EDUTRACK:
        plan = "Basico"
    return plan


def modulo_en_plan(clave, inst=None):
    """¿El plan del colegio incluye este módulo? (PlanComercial + diccionario)."""
    if not clave:
        return True
    # export siempre
    if clave in ("reportes_basicos", "reportes_excel"):
        return True
    try:
        return clave in set(modulos_plan_actual(inst))
    except Exception:
        plan = plan_institucion(inst)
        mods = PLANES_EDUTRACK.get(plan, {}).get("modulos", [])
        return clave in mods


def parse_fecha_iso(s):
    s = (s or "").strip()
    if not s:
        return None
    try:
        return datetime.strptime(s[:10], "%Y-%m-%d").date()
    except Exception:
        return None


def estado_licencia(inst):
    """
    Devuelve dict: estado, dias_restantes, mensaje, bloqueado, popup_mora.
    estados: ok | aviso | vencida | suspendida | cancelacion | archivada | mora_aviso
    """
    if not inst:
        return {"estado": "ok", "dias_restantes": None, "mensaje": "", "bloqueado": False, "popup_mora": False}
    est = (inst.estado or "ACTIVA").upper()
    if est == "SUSPENDIDA":
        # Si no hay deuda real, no bloquear el acceso (queda inconsistente en BD → auto-corregir)
        try:
            pend = FacturaCobro.query.filter_by(institucion_id=inst.id, estado="PENDIENTE").all()
            saldo = sum(float(x.valor or 0) for x in pend)
        except Exception:
            saldo = 0.0
        if saldo <= 0:
            try:
                inst.estado = "ACTIVA"
                inst.motivo_bloqueo = ""
                from datetime import timedelta
                hoy = ahora().date() if hasattr(ahora(), "date") else __import__("datetime").date.today()
                venc = parse_fecha_iso(getattr(inst, "fecha_vencimiento", None) or "")
                if not venc or venc < hoy:
                    inst.fecha_vencimiento = (hoy + timedelta(days=30)).isoformat()
                db.session.commit()
            except Exception:
                try:
                    db.session.rollback()
                except Exception:
                    pass
            return {"estado": "ok", "dias_restantes": None, "mensaje": "", "bloqueado": False, "popup_mora": False}
        return {
            "estado": "suspendida",
            "dias_restantes": 0,
            "mensaje": inst.motivo_bloqueo or "Servicio suspendido por mora de cartera.",
            "bloqueado": True,
            "popup_mora": False,
        }
    if est == "ARCHIVADA":
        return {
            "estado": "archivada",
            "dias_restantes": 0,
            "mensaje": inst.motivo_bloqueo or "Institución archivada.",
            "bloqueado": True,
            "popup_mora": False,
        }
    if est == "CANCELACION_PENDIENTE":
        fin = (getattr(inst, "fecha_fin_servicio", None) or "")[:10]
        msg = (
            f"Cancelación programada. El colegio sigue operando hasta el {fin or 'fin de ciclo pagado'}. "
            "No se generarán nuevas facturas. Profesores y notas siguen activos."
        )
        return {
            "estado": "cancelacion",
            "dias_restantes": None,
            "mensaje": msg,
            "bloqueado": False,  # sin corte hasta fecha_fin
            "popup_mora": False,
        }
    try:
        hoy = ahora().date()
    except Exception:
        hoy = datetime.now().date()
    # Mora días 6–10: popup recordatorio (factura PENDIENTE del ciclo)
    try:
        ciclo = hoy.strftime("%Y-%m")
        tiene_pend = (
            FacturaCobro.query.filter_by(
                institucion_id=inst.id, tipo="recurring", ciclo=ciclo, estado="PENDIENTE"
            ).count()
            > 0
        )
        if tiene_pend and 6 <= hoy.day <= 10 and est == "ACTIVA":
            return {
                "estado": "mora_aviso",
                "dias_restantes": 11 - hoy.day,
                "mensaje": (
                    "Recuerde realizar el pago de su mensualidad para evitar la suspensión del servicio. "
                    f"A partir del día 11 del mes el acceso se suspende automáticamente."
                ),
                "bloqueado": False,
                "popup_mora": True,
            }
    except Exception:
        pass
    venc = parse_fecha_iso(getattr(inst, "fecha_vencimiento", None))
    if not venc:
        return {"estado": "ok", "dias_restantes": None, "mensaje": "", "bloqueado": False, "popup_mora": False}
    dias = (venc - hoy).days
    aviso_desde = int(getattr(inst, "dias_aviso", None) or 7)
    if dias < 0:
        return {
            "estado": "vencida",
            "dias_restantes": dias,
            "mensaje": f"Licencia vencida hace {abs(dias)} día(s). El acceso puede bloquearse.",
            "bloqueado": False,
            "popup_mora": False,
        }
    if dias == 0:
        return {
            "estado": "aviso",
            "dias_restantes": 0,
            "mensaje": "Tu licencia vence hoy. Regulariza el pago para evitar el bloqueo.",
            "bloqueado": False,
            "popup_mora": False,
        }
    if dias <= aviso_desde:
        return {
            "estado": "aviso",
            "dias_restantes": dias,
            "mensaje": f"Tu licencia vence en {dias} día(s). Fecha de pago: {inst.fecha_vencimiento}.",
            "bloqueado": False,
            "popup_mora": False,
        }
    return {"estado": "ok", "dias_restantes": dias, "mensaje": "", "bloqueado": False, "popup_mora": False}


def sincronizar_licencias():
    """Auto-suspende SOLO con deuda real Y licencia vencida.

    Reglas:
    - Si saldo pendiente (facturas PENDIENTE valor>0) es 0 → NUNCA suspende ni por fecha.
    - Si el colegio tiene auto_suspender=False → no lo toca el job automático.
    - Si hay saldo > 0 y fecha_vencimiento ya pasó → suspende por mora.
    - Si hay saldo > 0 pero la fecha de vencimiento es futura → NO suspende (aún en plazo).
    """
    try:
        hoy = ahora().date()
        # 1) Reparar suspendidos sin deuda
        for inst in Institucion.query.filter(Institucion.estado == "SUSPENDIDA").all():
            try:
                if getattr(inst, "auto_suspender", None) is False:
                    continue
            except Exception:
                pass
            try:
                pend = FacturaCobro.query.filter_by(institucion_id=inst.id, estado="PENDIENTE").all()
                saldo = sum(float(x.valor or 0) for x in pend if float(x.valor or 0) > 0)
            except Exception:
                saldo = 0.0
            if saldo <= 0:
                inst.estado = "ACTIVA"
                inst.motivo_bloqueo = ""
                try:
                    venc = parse_fecha_iso(getattr(inst, "fecha_vencimiento", None) or "")
                    if not venc or venc < hoy:
                        from datetime import timedelta
                        inst.fecha_vencimiento = (hoy + timedelta(days=30)).isoformat()
                except Exception:
                    pass
        # 2) Suspender activos solo con deuda + vencimiento pasado
        for inst in Institucion.query.filter(Institucion.estado == "ACTIVA").all():
            try:
                if getattr(inst, "auto_suspender", None) is False:
                    continue
            except Exception:
                pass
            try:
                pend = FacturaCobro.query.filter_by(institucion_id=inst.id, estado="PENDIENTE").all()
                saldo = sum(float(x.valor or 0) for x in pend if float(x.valor or 0) > 0)
            except Exception:
                saldo = 0.0
            if saldo <= 0:
                continue
            venc = parse_fecha_iso(getattr(inst, "fecha_vencimiento", None))
            if venc and venc >= hoy:
                continue  # aún dentro del plazo pagado / acordado
            # deuda y (sin fecha o fecha vencida)
            inst.estado = "SUSPENDIDA"
            try:
                inst.fecha_suspension = fecha_hoy()
            except Exception:
                pass
            inst.motivo_bloqueo = (
                "Mora de cartera: saldo pendiente $ %.0f. Regularice el pago." % saldo
            )
        db.session.commit()
    except Exception as e:
        print("sincronizar_licencias:", e)
        try:
            db.session.rollback()
        except Exception:
            pass


def aplicar_cambios_plan_pendientes():
    """Aplica plan_pendiente cuando llega la fecha de corte (o ya pasó)."""
    try:
        hoy = ahora().date()
        cambiados = 0
        for inst in Institucion.query.filter(
            Institucion.plan_pendiente.isnot(None),
            Institucion.plan_pendiente != "",
        ).all():
            corte = parse_fecha_iso(getattr(inst, "fecha_corte_plan", None) or "")
            if not corte:
                continue
            if corte <= hoy:
                viejo = inst.plan or "Basico"
                nuevo = (inst.plan_pendiente or "").strip()
                if nuevo and nuevo in PLANES_EDUTRACK:
                    inst.plan = nuevo
                    inst.plan_pendiente = ""
                    inst.fecha_corte_plan = ""
                    cambiados += 1
                    try:
                        registrar_auditoria(
                            "Cambio de plan (fecha de corte)",
                            f"{inst.codigo}: {viejo} → {nuevo} (corte {corte.isoformat()})",
                        )
                    except Exception:
                        pass
        if cambiados:
            db.session.commit()
    except Exception as e:
        print("aplicar_cambios_plan_pendientes:", e)
        try:
            db.session.rollback()
        except Exception:
            pass


