def filtro_tenant(query, model):
    """Aplica filtro de institución. Soporte SIN tenant en sesión ve todo; con tenant, solo ese."""
    iid = institucion_id_actual()
    if iid is None:
        # Si es usuario de colegio sin sesión de inst, no devolver todo
        if requiere_login() and rol_actual() != "Soporte":
            return query.filter(False)  # vacío seguro
        return query
    if hasattr(model, "institucion_id"):
        return query.filter(model.institucion_id == iid)
    return query


def q_estudiantes():
    return filtro_tenant(Estudiante.query, Estudiante)


def paginar_query(query, page=1, per_page=None):
    """Paginación segura para listados grandes (1.500+ estudiantes sin cargar todo en RAM)."""
    try:
        page = max(1, int(page or 1))
    except Exception:
        page = 1
    if per_page is None:
        per_page = app.config.get("EDUTRACK_PAGE_SIZE", 50)
    try:
        per_page = min(200, max(10, int(per_page)))
    except Exception:
        per_page = 50
    total = query.count()
    items = query.limit(per_page).offset((page - 1) * per_page).all()
    pages = max(1, (total + per_page - 1) // per_page)
    return {
        "items": items,
        "page": page,
        "per_page": per_page,
        "total": total,
        "pages": pages,
        "has_prev": page > 1,
        "has_next": page < pages,
    }


def capacidad_estudiantes_ok(institucion_id=None):
    """True si el colegio aún puede matricular (tope por defecto 5.000)."""
    max_e = app.config.get("EDUTRACK_MAX_ESTUDIANTES", 5000)
    q = Estudiante.query
    if institucion_id:
        q = q.filter_by(institucion_id=institucion_id)
    else:
        q = q_estudiantes()
    return q.count() < max_e, q.count(), max_e


