def grados_disponibles():
    base = {"6", "7", "8", "9", "10", "11"}
    de_bd = {str(e.grado).strip() for e in q_estudiantes().all() if e.grado}
    todos = base | de_bd
    def key_g(x):
        n = str(x).replace("°", "").split("-")[0].strip()
        return int(n) if n.isdigit() else 999
    return sorted(todos, key=key_g)


def normalizar_lista_grados(texto):
    partes = re.split(r"[,;\s]+", texto or "")
    return [p.strip().replace("°", "") for p in partes if p.strip()]


def grados_docente_autorizados():
    if rol_actual() != "Docente":
        return grados_disponibles()
    u = Usuario.query.filter_by(usuario=session.get("usuario")).first()
    permitidos = []
    if u:
        if u.grupo_docente:
            permitidos.append(str(u.grupo_docente).strip())
        permitidos += normalizar_lista_grados(getattr(u, "grados_clase", ""))
    permitidos = sorted(set([g for g in permitidos if g]), key=lambda x: int(str(x).split("-")[0]) if str(x).split("-")[0].isdigit() else 999)
    existentes = set(grados_disponibles())
    return [g for g in permitidos if g in existentes] or permitidos



def _aplicar_nombres_estudiante(e, form):
    """Rellena nombre1/2, apellido1/2 y calcula nombre/apellido legibles desde el formulario SIMAT."""
    a1 = (form.get("apellido1") or form.get("apellido") or "").strip()
    a2 = (form.get("apellido2") or "").strip()
    n1 = (form.get("nombre1") or form.get("nombre") or "").strip()
    n2 = (form.get("nombre2") or "").strip()
    # Si vienen campos compuestos viejos, partirlos
    if not a1 and form.get("apellido"):
        parts = (form.get("apellido") or "").strip().split()
        a1 = parts[0] if parts else ""
        a2 = " ".join(parts[1:]) if len(parts) > 1 else a2
    if not n1 and form.get("nombre"):
        parts = (form.get("nombre") or "").strip().split()
        n1 = parts[0] if parts else ""
        n2 = " ".join(parts[1:]) if len(parts) > 1 else n2
    if hasattr(e, "apellido1"):
        e.apellido1 = (a1 or "")[:80]
    if hasattr(e, "apellido2"):
        e.apellido2 = (a2 or "")[:80]
    if hasattr(e, "nombre1"):
        e.nombre1 = (n1 or "")[:80]
    if hasattr(e, "nombre2"):
        e.nombre2 = (n2 or "")[:80]
    apellido = f"{a1} {a2}".strip()
    nombre = f"{n1} {n2}".strip()
    e.apellido = (apellido or "Sin apellido")[:120]
    e.nombre = (nombre or "Sin nombre")[:120]
    return e

def estudiante_nombre(e):
    """Nombre legible del estudiante (nombre/apellido o desglose SIMAT)."""
    if e is None:
        return ""
    ap = (getattr(e, "apellido", None) or "").strip()
    no = (getattr(e, "nombre", None) or "").strip()
    if (not ap or ap.lower() in ("sin apellido", "sin apellidos")) and getattr(e, "apellido1", None):
        ap = f"{(e.apellido1 or '').strip()} {(getattr(e, 'apellido2', None) or '').strip()}".strip()
    if (not no or no.lower() in ("sin nombre", "sin nombres")) and getattr(e, "nombre1", None):
        no = f"{(e.nombre1 or '').strip()} {(getattr(e, 'nombre2', None) or '').strip()}".strip()
    if not ap:
        ap = "SIN APELLIDO"
    if not no:
        no = "SIN NOMBRE"
    return f"{ap} {no}".strip()


def nombre_completo_estudiante(e):
    """Alias usado en planilla y reportes."""
    return estudiante_nombre(e)


