def registrar_sesion_empleado(u):
    try:
        token = _generar_token_sesion()
        u.session_token = token
        u.ultimo_acceso = ahora().strftime("%Y-%m-%d %H:%M:%S") if hasattr(ahora(), "strftime") else ""
        # desactivar otras sesiones del mismo usuario (una sesión activa)
        try:
            SesionEmpleado.query.filter_by(usuario_id=u.id, activa=True).update({"activa": False})
        except Exception:
            pass
        s = SesionEmpleado(
            usuario_id=u.id,
            token=token,
            ip=(request.headers.get("X-Forwarded-For") or request.remote_addr or "").split(",")[0].strip(),
            user_agent=(request.headers.get("User-Agent") or "")[:300],
            creada=u.ultimo_acceso,
            ultimo_ping=u.ultimo_acceso,
            activa=True,
        )
        db.session.add(s)
        db.session.commit()
        session["session_token"] = token
        session["uid"] = u.id
        return token
    except Exception as ex:
        print("sesion empleado:", ex)
        try:
            db.session.rollback()
        except Exception:
            pass
        return ""


