def _recaptcha_site_key():
    return (os.environ.get("RECAPTCHA_SITE_KEY") or "").strip()

def _recaptcha_secret():
    return (os.environ.get("RECAPTCHA_SECRET_KEY") or "").strip()

def _recaptcha_enabled():
    return bool(_recaptcha_site_key() and _recaptcha_secret())

def _recaptcha_ok():
    if _recaptcha_enabled():
        token = request.form.get("g-recaptcha-response") or ""
        if not token:
            return False
        try:
            import urllib.request
            import urllib.parse
            import json as _json
            data = urllib.parse.urlencode({
                "secret": _recaptcha_secret(),
                "response": token,
                "remoteip": (request.headers.get("X-Forwarded-For") or request.remote_addr or ""),
            }).encode()
            req = urllib.request.Request(
                "https://www.google.com/recaptcha/api/siteverify",
                data=data,
                method="POST",
            )
            with urllib.request.urlopen(req, timeout=8) as resp:
                out = _json.loads(resp.read().decode())
            return bool(out.get("success"))
        except Exception as ex:
            print("recaptcha error", ex)
            return False
    expected = str(session.get("captcha_result") or "")
    got = (request.form.get("captcha_respuesta") or "").strip()
    return expected != "" and got == expected

def _captcha_challenge_html():
    if _recaptcha_enabled():
        sk = _recaptcha_site_key()
        return (
            '<div style="margin:12px 0">'
            f'<div class="g-recaptcha" data-sitekey="{sk}"></div>'
            '<script src="https://www.google.com/recaptcha/api.js" async defer></script>'
            "</div>"
        )
    import random
    a, b = random.randint(2, 9), random.randint(1, 8)
    session["captcha_result"] = str(a + b)
    return (
        '<div style="margin:12px 0">'
        f'<label style="font-size:13px;color:#334155">Verificacion de seguridad: cuanto es <b>{a} + {b}</b>?</label>'
        '<input name="captcha_respuesta" inputmode="numeric" placeholder="Resultado" required '
        'style="width:100%;padding:10px;border:1px solid #e2e8f0;border-radius:8px;margin-top:6px">'
        "</div>"
    )


