def _ensure_login_challenge_cols():
    try:
        from sqlalchemy import text, inspect
        insp = inspect(db.engine)
        if "login_challenges" not in insp.get_table_names():
            return
        cols = {c["name"] for c in insp.get_columns("login_challenges")}
        with db.engine.begin() as conn:
            if "foto_validacion" not in cols:
                conn.execute(text("ALTER TABLE login_challenges ADD COLUMN foto_validacion VARCHAR(300) DEFAULT ''"))
            if "mensaje_enviado" not in cols:
                conn.execute(text("ALTER TABLE login_challenges ADD COLUMN mensaje_enviado TEXT DEFAULT ''"))
    except Exception as ex:
        print("ensure login_challenges:", ex)

def _crear_reto_biometrico(usuario_id):
    _ensure_login_challenge_cols()
    import secrets
    from datetime import datetime, timedelta
    pin = f"{secrets.randbelow(1000000):06d}"
    token = secrets.token_hex(24)
    now = ahora()
    if hasattr(now, "strftime"):
        creado = now.strftime("%Y-%m-%d %H:%M:%S")
        expira = (now + timedelta(minutes=3)).strftime("%Y-%m-%d %H:%M:%S") if hasattr(now, "__add__") else creado
    else:
        creado = expira = ""
    ch = LoginChallenge(
        usuario_id=usuario_id,
        pin=pin,
        token=token,
        estado="pendiente",
        ip_pc=(request.headers.get("X-Forwarded-For") or request.remote_addr or "")[:80],
        creado=creado,
        expira=expira,
    )
    db.session.add(ch)
    db.session.commit()
    return ch


def _crear_reto_pin(usuario_id):
    """Reto de login SOLO con PIN (sin validación biométrica/selfie). El PIN se envía
    al correo registrado del usuario de Soporte y se valida en la misma pantalla del PC."""
    _ensure_login_challenge_cols()
    import secrets
    from datetime import timedelta
    pin = f"{secrets.randbelow(1000000):06d}"
    token = secrets.token_hex(24)
    now = ahora()
    creado = now.strftime("%Y-%m-%d %H:%M:%S") if hasattr(now, "strftime") else ""
    expira = (now + timedelta(minutes=5)).strftime("%Y-%m-%d %H:%M:%S") if hasattr(now, "strftime") else ""
    ch = LoginChallenge(
        usuario_id=usuario_id,
        pin=pin,
        token=token,
        estado="pendiente",
        ip_pc=(request.headers.get("X-Forwarded-For") or request.remote_addr or "")[:80],
        creado=creado,
        expira=expira,
    )
    db.session.add(ch)
    db.session.commit()
    return ch


def _reto_vigente(ch):
    if not ch or ch.estado != "pendiente":
        return False
    try:
        from datetime import datetime
        now = ahora()
        if hasattr(now, "strftime") and ch.expira:
            # compare string YYYY-MM-DD HH:MM:SS
            return now.strftime("%Y-%m-%d %H:%M:%S") <= ch.expira
    except Exception:
        return True
    return True



