def _asegurar_token_pqr(t):
    """Genera (una sola vez) un token seguro para el link público de notificación,
    para no exponer el radicado interno en la URL que recibe el cliente."""
    if not (t.token_notificacion or "").strip():
        import secrets
        t.token_notificacion = secrets.token_urlsafe(24)
        db.session.commit()
    return t.token_notificacion



def _fecha_limite_pqr_habiles(fecha_inicio=None, dias_habiles=15):
    """Suma N días hábiles (lun–vie) desde fecha_inicio (YYYY-MM-DD).
    Aproxima el plazo de respuesta del CPACA / Ley 1755 (sin festivos locales)."""
    from datetime import datetime as _dt, timedelta as _td
    try:
        base = _dt.strptime((fecha_inicio or fecha_hoy())[:10], "%Y-%m-%d")
    except Exception:
        base = _dt.utcnow()
    agregados = 0
    cur = base
    while agregados < int(dias_habiles):
        cur = cur + _td(days=1)
        if cur.weekday() < 5:  # 0=lun … 4=vie
            agregados += 1
    return cur.strftime("%Y-%m-%d")



def _cargar_hero_pqr():
    """Devuelve (bytes, mime_subtype, filename) de la foto hero PROCSIS, o (None, None, None)."""
    candidates = []
    base = os.path.dirname(os.path.abspath(__file__))
    for name in (
        "pqr-respuesta-hero.png",
        "pqr-respuesta-hero.jpg",
        "pqr-respuesta-hero.jpeg",
        "pqr-respuesta-hero.png.jpeg",
        "pqr-respuesta-hero.PNG",
        "pqr-respuesta-hero.JPG",
    ):
        candidates.append(os.path.join(base, "static", "img", name))
        candidates.append(os.path.join("static", "img", name))
    for p in candidates:
        try:
            if not (p and os.path.isfile(p) and os.path.getsize(p) > 500):
                continue
            with open(p, "rb") as fh:
                raw = fh.read()
            # magic bytes
            if raw[:3] == b"\xff\xd8\xff":
                return raw, "jpeg", "pqr-respuesta-hero.jpg"
            if raw[:8] == b"\x89PNG\r\n\x1a\n":
                return raw, "png", "pqr-respuesta-hero.png"
            # fallback por extensión
            ext = os.path.splitext(p)[1].lower()
            if "jpg" in ext or "jpeg" in ext:
                return raw, "jpeg", "pqr-respuesta-hero.jpg"
            return raw, "png", "pqr-respuesta-hero.png"
        except Exception as e:
            print("hero load skip", p, e)
    return None, None, None


def _nombre_destinatario_pqr(t):
    """Nombre para saludar en correos/landing: razón social del ticket o usuario en sesión."""
    nom = (getattr(t, "razon_social", None) or "").strip()
    if nom:
        return nom
    try:
        if session.get("nombre_completo"):
            return str(session.get("nombre_completo")).strip()
        if session.get("usuario"):
            return str(session.get("usuario")).strip()
    except Exception:
        pass
    return "Usuario"



def _asegurar_token_csat(t):
    """Token único para encuesta de satisfacción del caso."""
    import secrets as _sec
    if not (getattr(t, "token_csat", None) or "").strip():
        t.token_csat = _sec.token_urlsafe(24)
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
    return (t.token_csat or "").strip()


def _url_encuesta_csat(t):
    base = (os.environ.get("APP_BASE_URL") or "").rstrip("/")
    try:
        if not base and request:
            base = (request.url_root or "").rstrip("/")
    except Exception:
        pass
    tok = _asegurar_token_csat(t)
    if not base:
        base = ""
    return f"{base}/encuesta/{tok}"


def _crear_encuesta_csat_para_ticket(t):
    """Crea registro pendiente de encuesta al resolver el caso."""
    tok = _asegurar_token_csat(t)
    try:
        existente = EncuestaCSAT.query.filter_by(token=tok).first()
        if existente:
            return existente, _url_encuesta_csat(t)
        enc = EncuestaCSAT(
            ticket_id=t.id,
            token=tok,
            institucion_id=getattr(t, "institucion_id", None),
            radicado=(t.radicado or "")[:40],
            email=(t.email or "")[:160],
            nombre=(t.razon_social or "")[:220],
            creada_en=f"{fecha_hoy()} {hora_actual()}",
            respondida=False,
        )
        db.session.add(enc)
        t.csat_enviada_en = f"{fecha_hoy()} {hora_actual()}"
        db.session.commit()
        return enc, _url_encuesta_csat(t)
    except Exception as e:
        db.session.rollback()
        print("crear encuesta csat:", e)
        return None, _url_encuesta_csat(t)


def _cargar_divipola():
    """Carga departamentos/municipios de Colombia (archivo junto a app.py)."""
    try:
        from colombia_divipola import COLOMBIA_DEPARTAMENTOS
        if COLOMBIA_DEPARTAMENTOS:
            return COLOMBIA_DEPARTAMENTOS
    except Exception:
        pass
    try:
        import importlib.util
        try:
            base = Path(__file__).resolve().parent
        except Exception:
            base = Path(".")
        for candidate in (
            base / "colombia_divipola.py",
            Path("/home/workdir/artifacts/colombia_divipola.py"),
            Path("colombia_divipola.py"),
        ):
            if candidate.is_file():
                spec = importlib.util.spec_from_file_location("colombia_divipola", str(candidate))
                mod = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(mod)
                return getattr(mod, "COLOMBIA_DEPARTAMENTOS", {}) or {}
    except Exception as e:
        print("divipola load:", e)
    return {}


def _divipola_json():
    try:
        return json.dumps(_cargar_divipola(), ensure_ascii=False)
    except Exception as e:
        print("divipola json:", e)
        return "{}"


def _opts_departamentos_html(selected=""):
    data = _cargar_divipola()
    opts = ['<option value="">— Departamento —</option>']
    for d in sorted(data.keys()):
        sel = " selected" if d == (selected or "") else ""
        opts.append(f'<option value="{_esc(d)}"{sel}>{_esc(d)}</option>')
    return "\n".join(opts)


def _html_campos_dep_mun(dep_name="departamento", mun_name="municipio", dep_val="", mun_val="", required=True, label_mun="Municipio / Ciudad"):
    """Selects Departamento + Municipio (DIVIPOLA). Nunca debe tumbar la página."""
    try:
        import secrets as _sec
        uid = _sec.token_hex(3)
    except Exception:
        uid = str(abs(hash(str(dep_name) + str(mun_name))) % 10**8)
    dep_id = "dep_" + str(uid)
    mun_id = "mun_" + str(uid)
    req = " required" if required else ""
    try:
        opts = _opts_departamentos_html(dep_val or "")
    except Exception as e:
        print("opts dep:", e)
        opts = '<option value="">— Departamento —</option>'
    try:
        script = _script_divipola_subtipos()
    except Exception as e:
        print("script divipola:", e)
        script = "<script>window.DIVIPOLA=window.DIVIPOLA||{};function fillMun(a,b){}</script>"
    try:
        mun_esc = _esc(mun_val or "")
        dep_name_s = _esc(dep_name)
        mun_name_s = _esc(mun_name)
        label_s = _esc(label_mun)
    except Exception:
        mun_esc = ""
        dep_name_s = str(dep_name)
        mun_name_s = str(mun_name)
        label_s = str(label_mun)
    star = " *" if required else ""
    html = []
    html.append(script)
    html.append("<label>Departamento" + star + "</label>")
    html.append(
        '<select name="' + dep_name_s + '" id="' + dep_id + '"' + req
        + ' onchange="fillMun(\'' + dep_id + '\',\'' + mun_id + '\')">'
    )
    html.append(opts)
    html.append("</select>")
    html.append("<label>" + label_s + star + "</label>")
    html.append(
        '<select name="' + mun_name_s + '" id="' + mun_id + '"' + req
        + ' data-sel="' + mun_esc + '">'
    )
    html.append('<option value="">— Elija departamento primero —</option></select>')
    html.append(
        "<script>(function(){var m=document.getElementById('" + mun_id + "');"
        "if(m)m.setAttribute('data-sel','" + mun_esc + "');"
        "function run(){if(typeof fillMun==='function')fillMun('" + dep_id + "','" + mun_id + "');}"
        "if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();"
        "})();</script>"
    )
    return "".join(html)



