def _norm_txt(s):
    import unicodedata
    s = (s or "").strip().upper()
    s = "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")
    return " ".join(s.split())


def preguntas_validacion_institucion(inst):
    """Preguntas anti-fraude prácticas (solo campos que el colegio suele recordar)."""
    if not inst:
        return []
    qs = []
    # 1) Código EduTrack (siempre si existe)
    if (inst.codigo or "").strip():
        qs.append(("codigo", "Código del colegio en EduTrack", _norm_txt(inst.codigo)))
    # 2) Últimos dígitos NIT (sin guiones ni espacios)
    nit_clean = "".join(c for c in (inst.nit or "") if c.isdigit())
    if len(nit_clean) >= 3:
        qs.append(("nit", "Últimos 3 dígitos del NIT (solo números)", nit_clean[-3:]))
    # 3) Municipio (flexible)
    if (inst.municipio or "").strip():
        qs.append(("muni", "Municipio de la institución", _norm_txt(inst.municipio)))
    # 4) DANE solo si tiene 4+ dígitos
    dane_clean = "".join(c for c in (inst.dane or "") if c.isdigit())
    if len(dane_clean) >= 4:
        qs.append(("dane", "Últimos 4 dígitos del DANE", dane_clean[-4:]))
    return qs[:3]


def validar_respuestas_institucion(inst, form):
    """
    Valida anti-fraude de forma práctica:
    - Solo exige preguntas con dato real en el colegio.
    - Coincide flexible (mayúsculas, tildes, espacios).
    - Basta con acertar 2 de 3 (o todas si hay menos de 3).
    Devuelve (ok: bool, detalle: str).
    """
    qs = preguntas_validacion_institucion(inst)
    if not qs:
        return True, "Sin datos de validación configurados; se permite consulta."
    aciertos = 0
    fallos = []
    for key, pregunta, esperado in qs:
        resp = _norm_txt(form.get(f"val_{key}") or form.get(key) or "")
        # solo dígitos para nit/dane
        if key in ("nit", "dane"):
            resp = "".join(c for c in resp if c.isdigit())
            esperado = "".join(c for c in str(esperado) if c.isdigit())
        if not resp:
            fallos.append(f"{pregunta}: vacío")
            continue
        if key == "muni":
            # municipio: acepta si uno contiene al otro
            if resp == esperado or resp in esperado or esperado in resp:
                aciertos += 1
            else:
                fallos.append(pregunta)
        elif resp == esperado:
            aciertos += 1
        else:
            fallos.append(pregunta)
    need = 2 if len(qs) >= 3 else len(qs)
    if aciertos >= need:
        return True, f"Validación OK ({aciertos}/{len(qs)})"
    return False, f"Incorrectas o vacías: {', '.join(fallos) if fallos else 'datos'}. Debe acertar al menos {need} de {len(qs)}."



