def _ahora_str_ms():
    try:
        return ahora().strftime("%Y-%m-%d %H:%M:%S.") + f"{ahora().microsecond // 1000:03d}"
    except Exception:
        from datetime import datetime as _dt
        n = _dt.now()
        return n.strftime("%Y-%m-%d %H:%M:%S.") + f"{n.microsecond // 1000:03d}"


