def periodo_esta_cerrado(periodo=None, iid=None):
    """
    True si la fecha/hora de cierre del periodo ya pasó y no hay apertura extraordinaria vigente.
    """
    periodo = periodo or periodo_actual()
    iid = iid if iid is not None else institucion_id_actual()
    if not iid:
        return False
    try:
        c = CierrePeriodo.query.filter_by(institucion_id=iid, periodo=periodo).first()
    except Exception:
        return False
    if not c or not c.fecha_cierre:
        return False
    # Apertura extraordinaria vigente
    if c.apertura_extra_hasta:
        try:
            from datetime import datetime as _dt
            hasta = _dt.strptime(c.apertura_extra_hasta[:19], "%Y-%m-%d %H:%M:%S")
            if ahora().replace(tzinfo=None) <= hasta:
                return False  # ventana abierta 2h
        except Exception:
            pass
    try:
        from datetime import datetime as _dt
        hc = (c.hora_cierre or "23:59").strip()
        if len(hc) == 5:
            hc = hc + ":00"
        cierre_dt = _dt.strptime(f"{c.fecha_cierre} {hc}", "%Y-%m-%d %H:%M:%S")
        return ahora().replace(tzinfo=None) >= cierre_dt
    except Exception:
        return bool(c.cerrado)


def generar_observacion_por_nota(nota):
    """Plantillas de observación según nota final (0–5)."""
    try:
        n = float(nota)
    except Exception:
        return "Se recomienda acompañamiento académico continuo y cumplimiento de actividades."
    if n >= 4.6:
        return "Excelente desempeño académico; demuestra gran compromiso, responsabilidad y dominio de los temas trabajados en el periodo."
    if n >= 4.0:
        return "Muy buen desempeño académico; muestra interés y constancia. Se invita a mantener el ritmo de trabajo."
    if n >= 3.5:
        return "Desempeño satisfactorio; cumple con las actividades. Puede fortalecer la profundización de algunos temas."
    if n >= 3.0:
        return "Desempeño básico; se sugiere reforzar los temas vistos en clase y cumplir oportunamente con las actividades."
    if n >= 2.0:
        return "Desempeño insuficiente; requiere mayor compromiso, refuerzo escolar y acompañamiento familiar para superar las dificultades."
    return "Desempeño crítico; se recomienda plan de mejoramiento, refuerzo pedagógico y seguimiento cercano del acudiente."
