def periodos_del_colegio(institucion_id=None):
    """Lista de periodos según config del colegio (3 o 4)."""
    try:
        iid = institucion_id if institucion_id is not None else institucion_id_actual()
        cfg = Configuracion.query.filter_by(institucion_id=iid).first() if iid else config()
        n = int(getattr(cfg, "num_periodos", None) or 3) if cfg else 3
        if n not in (3, 4):
            n = 3
        return [f"Periodo {i}" for i in range(1, n + 1)]
    except Exception:
        return ["Periodo 1", "Periodo 2", "Periodo 3"]

