def registrar_ingreso(codigo, estado, registrado_por=None):
    codigo = limpiar_codigo(codigo)
    e = q_estudiantes().filter_by(codigo=codigo).first()
    if not e:
        e = Estudiante.query.filter_by(codigo=codigo).first()
    if not e:
        return "Estudiante no registrado", "No registrado"
    if not registrado_por:
        registrado_por = f"{session.get('usuario', 'Portería')} ({session.get('rol', 'Portal móvil')})" if requiere_login() else "Portería / Portal móvil"
    alerta_med = (getattr(e, "alerta_medica", None) or "").strip()
    if not alerta_med:
        parts = []
        if (getattr(e, "alergias", None) or "").strip():
            parts.append("ALERGICO: " + (e.alergias or "")[:60])
        if (getattr(e, "enfermedades", None) or "").strip():
            parts.append((e.enfermedades or "")[:60])
        alerta_med = " · ".join(parts)
    try:
        auth = (
            AutorizacionSalida.query.filter(
                AutorizacionSalida.estudiante_id == e.id,
                AutorizacionSalida.fecha == fecha_hoy(),
                AutorizacionSalida.estado.in_(["ACTIVA", "APROBADA"]),
            )
            .order_by(AutorizacionSalida.id.desc())
            .first()
        )
    except Exception:
        auth = None
    if auth:
        msg_out = "SALIDA AUTORIZADA: Entregar a %s - C.C. %s" % (auth.nombre_recoge, auth.documento_recoge)
        if alerta_med:
            msg_out = "ATENCION MEDICA: %s | %s" % (alerta_med, msg_out)
        try:
            auth.estado = "USADA"
            auth.usado_en = hora_actual()
            db.session.add(IngresoPorteria(
                estudiante_id=e.id, fecha=fecha_hoy(), hora=hora_actual(),
                dia=ahora().strftime("%A"), estado="Salida autorizada",
                periodo=periodo_actual(), registrado_por=registrado_por or "Porteria",
            ))
            db.session.commit()
        except Exception:
            try:
                db.session.rollback()
            except Exception:
                pass
        return msg_out, "Salida autorizada"
    # Anti-suplantación: mismo QR en menos de 15 min
    try:
        ok_qr, wait_s = _qr_anti_suplantacion_ok(codigo, segundos=900)
        if not ok_qr:
            return (
                "ALERTA: CARNÉ YA REGISTRADO EN EL PLANTEL - POSIBLE SUPLANTACIÓN. "
                "Espere %s s y verifique la foto del estudiante." % wait_s,
                "Suplantacion",
            )
    except Exception:
        pass
    ultimo = IngresoPorteria.query.filter_by(estudiante_id=e.id, fecha=fecha_hoy()).order_by(IngresoPorteria.id.desc()).first()
    if ultimo:
        return f"Entrada bloqueada: {e.nombre} {e.apellido} ya fue registrado hoy a las {ultimo.hora} por {ultimo.registrado_por}.", "Duplicado"
    # Estado automático por hora de corte (07:00)
    hora = hora_actual()
    try:
        st_auto, mins = _estado_ingreso_por_hora(hora, _hora_corte_tarde())
        if st_auto == "RETARDO":
            estado = "Tarde"
        elif (estado or "").strip() in ("", "Temprano", "A tiempo", "A_TIEMPO"):
            estado = "Temprano"
    except Exception:
        mins = 0
    db.session.add(IngresoPorteria(
        estudiante_id=e.id, fecha=fecha_hoy(), hora=hora,
        dia=ahora().strftime("%A"), estado=estado, periodo=periodo_actual(),
        registrado_por=registrado_por,
    ))
    db.session.commit()
    registrar_auditoria("Registro de ingreso", f"{e.codigo} - {e.nombre} {e.apellido} - {estado} - {registrado_por}")
    extra = ""
    if (estado or "").lower() in ("tarde", "retardo"):
        extra = " (%s min tarde)" % mins if mins else " (retardo)"
    msg_ok = f"Registro guardado: {e.nombre} {e.apellido} - {estado}{extra}"
    try:
        if alerta_med:
            msg_ok = "ATENCION: %s | %s" % (alerta_med, msg_ok)
    except Exception:
        pass
    return msg_ok, estado

def enviar_pin(correo_destino, pin):
    if not SOPORTE_EMAIL or not SOPORTE_PASSWORD: return False
    msg = EmailMessage(); msg["Subject"] = "PIN de recuperación - EduTrack"; msg["From"] = SOPORTE_EMAIL; msg["To"] = correo_destino
    msg.set_content(f"Tu PIN de recuperación es: {pin}\nEste PIN vence en 2 minutos.\n{APP_NAME}")
    try:
        _smtp_enviar(msg, SOPORTE_EMAIL, SOPORTE_PASSWORD)
        return True
    except Exception as e:
        print("ERROR PIN:", e); return False


