def _calcular_promo_valores(valor_pleno, promo=None):
    """Retorna dict con descuento, valor neto, fechas y textos para contrato."""
    from datetime import datetime, timedelta
    try:
        from dateutil.relativedelta import relativedelta
        has_rd = True
    except Exception:
        has_rd = False
    valor_pleno = float(valor_pleno or 0)
    out = {
        "promo_id": 0,
        "nombre_promo": "",
        "porcentaje": 0.0,
        "duracion_valor": 0,
        "duracion_unidad": "",
        "valor_pleno": int(round(valor_pleno)),
        "valor_descuento": int(round(valor_pleno)),
        "ahorro": 0,
        "fecha_activacion": "",
        "fecha_caducidad": "",
        "fecha_caducidad_texto": "",
        "tiempo_promo": "",
    }
    if not promo or float(getattr(promo, "porcentaje_descuento", 0) or 0) <= 0:
        return out
    pct = float(promo.porcentaje_descuento or 0)
    if pct > 1:
        pct = pct / 100.0  # aceptar 15 o 0.15
    descuento = valor_pleno * pct
    neto = max(0, valor_pleno - descuento)
    unidad = (promo.duracion_unidad or "MESES").upper()
    if unidad in ("AÑOS", "ANOS", "YEAR", "YEARS"):
        unidad = "ANOS"
    elif unidad in ("DIA", "DIAS", "DAY", "DAYS"):
        unidad = "DIAS"
    else:
        unidad = "MESES"
    valor = int(promo.duracion_valor or 1)
    try:
        ahora_dt = ahora() if callable(ahora) else datetime.utcnow()
        if not hasattr(ahora_dt, "year"):
            ahora_dt = datetime.utcnow()
    except Exception:
        ahora_dt = datetime.utcnow()
    cad = ahora_dt
    try:
        if unidad == "DIAS":
            cad = ahora_dt + timedelta(days=valor)
        elif unidad == "ANOS":
            if has_rd:
                cad = ahora_dt + relativedelta(years=valor)
            else:
                cad = ahora_dt.replace(year=ahora_dt.year + valor)
        else:
            if has_rd:
                cad = ahora_dt + relativedelta(months=valor)
            else:
                cad = ahora_dt + timedelta(days=30 * valor)
    except Exception:
        cad = ahora_dt + timedelta(days=30 * max(valor, 1))
    meses_es = ["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"]
    try:
        fecha_txt = "%d de %s de %d" % (cad.day, meses_es[cad.month - 1], cad.year)
    except Exception:
        fecha_txt = cad.strftime("%Y-%m-%d") if hasattr(cad, "strftime") else str(cad)
    out.update({
        "promo_id": int(getattr(promo, "id", 0) or 0),
        "nombre_promo": (promo.nombre_promo or "")[:100],
        "porcentaje": round(pct * 100, 2),
        "duracion_valor": valor,
        "duracion_unidad": unidad,
        "valor_pleno": int(round(valor_pleno)),
        "valor_descuento": int(round(neto)),
        "ahorro": int(round(descuento)),
        "fecha_activacion": ahora_dt.strftime("%Y-%m-%d %H:%M:%S") if hasattr(ahora_dt, "strftime") else "",
        "fecha_caducidad": cad.strftime("%Y-%m-%d %H:%M:%S") if hasattr(cad, "strftime") else "",
        "fecha_caducidad_texto": fecha_txt,
        "tiempo_promo": "%s %s" % (valor, unidad.lower()),
    })
    return out


def _aplicar_promo_caducadas():
    """Marca instituciones cuya promo ya vencio (tarifa plena). SQL rapido, sin create_all."""
    try:
        from datetime import datetime
        ahora_s = ahora().strftime("%Y-%m-%d %H:%M:%S") if hasattr(ahora(), "strftime") else datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")
        # Un solo UPDATE; no carga ORM (evita OOM/timeout)
        r = db.session.execute(
            text(
                "UPDATE instituciones SET flag_tarifa_plena_aplicada = TRUE "
                "WHERE COALESCE(fecha_caducidad_descuento, '') <> '' "
                "AND fecha_caducidad_descuento <= :ahora "
                "AND COALESCE(flag_tarifa_plena_aplicada, FALSE) = FALSE"
            ),
            {"ahora": ahora_s[:19]},
        )
        db.session.commit()
        try:
            return int(r.rowcount or 0)
        except Exception:
            return 0
    except Exception:
        try:
            db.session.rollback()
        except Exception:
            pass
        return 0


def _ensure_inst_promo_columns():
    """Columnas de promo en instituciones (Railway). Idempotente y rapido."""
    if getattr(_ensure_inst_promo_columns, "_ok", False):
        return
    cols = [
        ("promo_id", "INTEGER DEFAULT 0"),
        ("valor_mensual_con_descuento", "INTEGER DEFAULT 0"),
        ("valor_mensual_pleno", "INTEGER DEFAULT 0"),
        ("fecha_activacion_tarifa", "VARCHAR(40) DEFAULT ''"),
        ("fecha_caducidad_descuento", "VARCHAR(40) DEFAULT ''"),
        ("flag_tarifa_plena_aplicada", "BOOLEAN DEFAULT FALSE"),
        ("nombre_promo_aplicada", "VARCHAR(100) DEFAULT ''"),
        ("porcentaje_promo_aplicada", "DOUBLE PRECISION DEFAULT 0"),
    ]
    try:
        with db.engine.begin() as conn:
            dialect = (db.engine.dialect.name or "").lower()
            for col, typ in cols:
                try:
                    if dialect == "sqlite":
                        rows = conn.execute(db.text("PRAGMA table_info(instituciones)")).fetchall()
                        names = {r[1] for r in rows}
                        if col not in names:
                            conn.execute(db.text("ALTER TABLE instituciones ADD COLUMN %s %s" % (col, typ)))
                    else:
                        conn.execute(db.text(
                            "ALTER TABLE instituciones ADD COLUMN IF NOT EXISTS %s %s" % (col, typ)
                        ))
                except Exception:
                    pass
            # Tabla maestra de promociones
            try:
                conn.execute(db.text(
                    """CREATE TABLE IF NOT EXISTS promociones_activas (
                        id SERIAL PRIMARY KEY,
                        nombre_promo VARCHAR(100) NOT NULL DEFAULT '',
                        porcentaje_descuento DOUBLE PRECISION DEFAULT 0,
                        duracion_valor INTEGER DEFAULT 1,
                        duracion_unidad VARCHAR(20) DEFAULT 'MESES',
                        estado VARCHAR(20) DEFAULT 'ACTIVO',
                        fecha_creacion VARCHAR(40) DEFAULT '',
                        created_by VARCHAR(80) DEFAULT ''
                    )"""
                ))
            except Exception:
                pass
        _ensure_inst_promo_columns._ok = True
    except Exception as ex:
        try:
            print("ensure_inst_promo_columns:", ex)
        except Exception:
            pass


def _datos_proveedor():
    """Datos legales/comerciales de la empresa (tabla plataforma) para contratos y PDFs.
    Fuente unica: /gerencia/datos-empresa — no hardcodear NIT ni representante en plantillas.
    """
    out = {
        "empresa": "PROCSIS",
        "producto": "EduTrack",
        "nit": "",
        "representante": "",
        "direccion": "",
        "ciudad": "Colombia",
        "ciiu": "6201",
        "regimen": "",
        "email": "",
        "telefono": "",
        "logo_url": "",
        "proveedor_corto": "PROCSIS (EduTrack)",
        "firma_micro": "",
        "division": "PROCSIS · DIVISION DE INFRAESTRUCTURA LEGAL Y CIBERSEGURIDAD",
    }
    try:
        p = plataforma()
        if p:
            out["empresa"] = (getattr(p, "empresa", None) or "PROCSIS").strip() or "PROCSIS"
            out["producto"] = (getattr(p, "nombre_producto", None) or "EduTrack").strip() or "EduTrack"
            out["nit"] = (getattr(p, "nit", None) or "").strip()
            out["representante"] = (getattr(p, "representante_legal", None) or "").strip()
            out["direccion"] = (getattr(p, "direccion", None) or "").strip()
            out["ciudad"] = (getattr(p, "ciudad", None) or "Colombia").strip() or "Colombia"
            out["ciiu"] = (getattr(p, "actividad_ciiu", None) or "6201").strip() or "6201"
            out["regimen"] = (getattr(p, "regimen_dian", None) or "").strip()
            out["email"] = (getattr(p, "email_empresa", None) or getattr(p, "email_soporte", None) or "").strip()
            out["telefono"] = (getattr(p, "telefono_empresa", None) or getattr(p, "telefono_soporte", None) or "").strip()
            logo = (getattr(p, "logo_path", None) or "").strip()
            if logo:
                if logo.startswith("data:image") or logo.startswith("http"):
                    out["logo_url"] = logo
                elif logo.startswith("/"):
                    try:
                        out["logo_url"] = (request.url_root or "").rstrip("/") + logo
                    except Exception:
                        out["logo_url"] = logo
                else:
                    out["logo_url"] = logo
            out["proveedor_corto"] = "%s (%s)" % (out["empresa"].upper() if out["empresa"].lower() == "procsis" else out["empresa"], out["producto"])
            # Bloque micro de firma (solo pie) — se actualiza al cambiar datos de empresa
            lineas = [
                "POR EL PROVEEDOR:",
                "________________________________________",
                "%s · DIVISION LEGAL" % out["empresa"].upper(),
                "Suite Academica y Control Perimetral %s" % out["producto"],
                "",
            ]
            if out["representante"] or out["nit"]:
                lineas.append("Soporte Tributario y Facturacion:")
                if out["representante"]:
                    lineas.append("%s (Representante Legal)" % out["representante"])
                bits = []
                if out["nit"]:
                    bits.append("RUT / NIT: %s" % out["nit"])
                if out["ciiu"]:
                    bits.append("Actividad Economica DIAN: %s" % out["ciiu"])
                if bits:
                    lineas.append(" · ".join(bits))
            if out["direccion"] or out["ciudad"]:
                lineas.append("Sede operativa: %s" % ", ".join(x for x in [out["direccion"], out["ciudad"]] if x))
            out["firma_micro"] = "\n".join(lineas)
    except Exception:
        pass
    return out


def _tokens_proveedor_contrato():
    """Tokens de proveedor para fusion de plantillas (vienen de datos de empresa)."""
    d = _datos_proveedor()
    return {
        "PROVEEDOR": d["proveedor_corto"],
        "EMPRESA": d["empresa"],
        "PRODUCTO": d["producto"],
        "NIT_PROVEEDOR": d["nit"] or "—",
        "REPRESENTANTE_LEGAL": d["representante"] or "—",
        "DIRECCION_PROVEEDOR": d["direccion"] or "—",
        "CIUDAD_PROVEEDOR": d["ciudad"],
        "CIIU": d["ciiu"],
        "FIRMA_PROVEEDOR_MICRO": d["firma_micro"].replace("\n", "<br>"),
        "DIVISION_LEGAL": d["division"],
        "LOGO_PROVEEDOR_URL": d["logo_url"],
    }


def _fusion_consentimiento(canal_tipo, tokens):
    _, cuerpo = _get_consentimiento(canal_tipo)
    tok = dict(_tokens_proveedor_contrato())
    tok.update(tokens or {})
    for k, v in tok.items():
        cuerpo = cuerpo.replace("{{" + k + "}}", str(v if v is not None else "-"))
    import re as _re
    cuerpo = _re.sub(r"\{\{[A-Z0-9_]+\}\}", "-", cuerpo)
    # Pie legal desde datos de empresa (no hardcode)
    firma = tok.get("FIRMA_PROVEEDOR_MICRO") or ""
    if firma and "POR EL PROVEEDOR" not in cuerpo:
        cuerpo += (
            '<div style="margin-top:28px;padding-top:16px;border-top:1px solid #e5e5ea;'
            'font-size:10px;color:#86868b;line-height:1.45">' + firma + "</div>"
        )
    return cuerpo


