@app.route("/validar_pin", methods=["GET", "POST"])
def validar_pin():
    if "recuperar_usuario" not in session: return redirect("/recuperar")
    mensaje = ""
    if request.method == "POST":
        r = Recuperacion.query.filter_by(usuario=session["recuperar_usuario"]).first()
        if r:
            partes = r.pin.split("|"); pin_real = partes[0]; vence = float(partes[1]) if len(partes) > 1 else 0
            if ahora().timestamp() > vence:
                Recuperacion.query.filter_by(usuario=session["recuperar_usuario"]).delete(); db.session.commit(); mensaje = "El PIN venció. Solicita uno nuevo."
            elif request.form.get("pin") == pin_real:
                u = Usuario.query.filter_by(usuario=session["recuperar_usuario"]).first(); u.password = crear_hash(request.form.get("password", "").strip()); u.password_temporal = False
                Recuperacion.query.filter_by(usuario=u.usuario).delete(); db.session.commit(); session.pop("recuperar_usuario", None); return redirect("/login")
            else: mensaje = "PIN incorrecto."
    return page("Validar PIN", f"""<div class="center"><section class="card login-card"><h1>Nueva contraseña</h1><p>{mensaje}</p><form method="POST"><input name="pin" placeholder="PIN recibido" required><input name="password" type="password" placeholder="Nueva contraseña" required><button>Guardar contraseña</button></form></section></div>""")



@app.route("/cambiar_password", methods=["GET", "POST"])
def cambiar_password():
    if not requiere_login(): return redirect("/login")
    mensaje = ""
    rol = rol_actual()
    es_staff = rol in ("Soporte", "Comercial", "Gerente", "Administrador", "Superadmin", "Cobranza")
    if request.method == "POST":
        nueva = request.form.get("password", "").strip()
        confirmar = request.form.get("confirmar", "").strip()
        nombre_completo = (request.form.get("nombre_completo") or "").strip()[:160]
        if len(nueva) < 8:
            mensaje = "La contraseña debe tener mínimo 8 caracteres."
        elif nueva != confirmar:
            mensaje = "Las contraseñas no coinciden."
        elif es_staff and not nombre_completo:
            mensaje = "Escriba su nombre para mostrar."
        else:
            u = Usuario.query.filter_by(usuario=session["usuario"]).first()
            u.password = crear_hash(nueva); u.password_temporal = False
            if es_staff:
                u.nombre_completo = nombre_completo
            db.session.commit(); session["password_temporal"] = False
            registrar_auditoria("Cambio de contraseña", "Usuario cambió su contraseña temporal" + (f" · nombre: {nombre_completo}" if es_staff else ""))
            if es_staff:
                destino = {"Soporte": "/soporte_admin", "Comercial": "/ventas/panel", "Gerente": "/gerencia/hq",
                           "Administrador": "/gerencia/hq", "Superadmin": "/gerencia/hq", "Cobranza": "/cobranza/panel"}.get(rol, "/dashboard")
                return redirect(destino)
            return redirect("/dashboard")
    campo_nombre = (
        '<input name="nombre_completo" placeholder="Su nombre completo (para mostrar)" required>'
        if es_staff else ""
    )
    return page("Cambiar contraseña", f"""
<div class="center"><section class="card login-card"><h1>Cambiar contraseña</h1><p>Ingresó con una clave temporal. Defina una nueva contraseña de su preferencia (mín. 8 caracteres){' y su nombre' if es_staff else ''} antes de continuar.</p>{'<p class="error">'+mensaje+'</p>' if mensaje else ''}<form method="POST">{campo_nombre}<input name="password" type="password" placeholder="Nueva contraseña" required><input name="confirmar" type="password" placeholder="Confirmar contraseña" required><button>Guardar contraseña</button></form><a href="/logout">Salir</a></section></div>
""")


@app.route("/rectoria/tareas")
def rectoria_tareas():
    """Monitoreo de tareas/actividades: vista de lectura para rectoría (no califica)."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Rectoría", "Coordinación", "Administrador", "Soporte"]:
        return acceso_denegado()
    iid = institucion_id_actual()
    periodo = periodo_actual()
    # Proxy: conteo de notas/logros cargados esta semana por docente = "tareas registradas"
    try:
        from datetime import datetime as _dt, timedelta as _td
        hace7 = (_dt.now() - _td(days=7)).strftime("%Y-%m-%d")
    except Exception:
        hace7 = fecha_hoy()
    q = NotaRegistro.query
    if iid is not None:
        q = q.filter(or_(NotaRegistro.institucion_id == iid, NotaRegistro.institucion_id.is_(None)))
    regs = q.filter(NotaRegistro.actualizado >= hace7).limit(5000).all() if hasattr(NotaRegistro, "actualizado") else q.limit(2000).all()
    por_doc = {}
    por_mat = {}
    for r in regs:
        d = r.docente or "Sin docente"
        por_doc[d] = por_doc.get(d, 0) + 1
        m = r.asignatura or "General"
        por_mat[m] = por_mat.get(m, 0) + 1
    total = len(regs)
    est_con_nota = len({r.estudiante_id for r in regs})
    est_total = q_estudiantes().count() or 1
    pct = round(100.0 * est_con_nota / est_total, 1)
    filas_d = "".join(
        f"<tr><td>{k}</td><td style='text-align:right'><b>{v}</b></td></tr>"
        for k, v in sorted(por_doc.items(), key=lambda x: -x[1])[:15]
    )
    filas_m = "".join(
        f"<tr><td>{k}</td><td style='text-align:right'><b>{v}</b></td></tr>"
        for k, v in sorted(por_mat.items(), key=lambda x: -x[1])[:15]
    )
    content = f"""
<div style="max-width:900px;margin:0 auto;font-family:Segoe UI,sans-serif;padding:12px">
  <p><a class="btn" href="/dashboard">← Panel rectoría</a></p>
  <h1 style="color:#0B2D57;margin:0 0 8px">📂 Monitoreo de tareas</h1>
  <p style="color:#64748b;font-size:14px">Vista de lectura: actividad académica de la última semana (registros de planilla / logros). La rectora no califica desde aquí.</p>
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin:14px 0">
    <div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px;text-align:center">
      <div style="font-size:24px;font-weight:800;color:#0B2D57">{total}</div>
      <div style="font-size:12px;color:#64748b">Registros esta semana</div>
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px;text-align:center">
      <div style="font-size:24px;font-weight:800;color:#15803d">{pct}%</div>
      <div style="font-size:12px;color:#64748b">Estudiantes con actividad</div>
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px;text-align:center">
      <div style="font-size:24px;font-weight:800">{est_con_nota}</div>
      <div style="font-size:12px;color:#64748b">De {est_total} estudiantes</div>
    </div>
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
    <div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px">
      <h3 style="margin:0 0 8px;color:#0B2D57;font-size:14px">Por docente</h3>
      <table style="width:100%;font-size:13px"><tr><th style="text-align:left">Docente</th><th>Actividad</th></tr>
      {filas_d or '<tr><td colspan=2>Sin datos esta semana</td></tr>'}
      </table>
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px">
      <h3 style="margin:0 0 8px;color:#0B2D57;font-size:14px">Por materia</h3>
      <table style="width:100%;font-size:13px"><tr><th style="text-align:left">Materia</th><th>Actividad</th></tr>
      {filas_m or '<tr><td colspan=2>Sin datos esta semana</td></tr>'}
      </table>
    </div>
  </div>
  <p style="margin-top:14px;font-size:12px;color:#94a3b8">Periodo de referencia: {periodo}. Para auditoría de cambios de notas use <a href="/soporte/logs-notas">Auditoría de notas</a>.</p>
</div>
"""
    return page("Monitoreo tareas", shell(content))


@app.route("/dashboard", methods=["GET", "POST"])
def dashboard():
    if not requiere_login(): return redirect("/login")
    if rol_actual() == "Soporte":
        return redirect("/soporte_admin")
    cfg = config()
    if request.method == "POST":
        if not puede_configurar(): return acceso_denegado()
        cfg.periodo_actual = request.form.get("periodo_actual", cfg.periodo_actual)
        cfg.jornada = request.form.get("jornada", cfg.jornada)
        if rol_actual() in ["Administrador", "Soporte"]:
            cfg.modo_mantenimiento = request.form.get("modo_mantenimiento") == "on"
            cfg.mensaje_mantenimiento = request.form.get("mensaje_mantenimiento", cfg.mensaje_mantenimiento)
            detalle_cfg = "Actualizó periodo, jornada o mantenimiento"
        else:
            detalle_cfg = "Rectoría actualizó periodo o jornada"
        db.session.commit(); registrar_auditoria("Configuración global", detalle_cfg)
        return redirect("/dashboard")

    hoy = fecha_hoy()
    # Filtro de sede (sesión o query)
    sede_filtro = request.args.get("sede_id") or session.get("sede_id")
    try:
        sede_filtro = int(sede_filtro) if sede_filtro else None
    except Exception:
        sede_filtro = None
    if request.args.get("sede_id") is not None:
        if sede_filtro:
            session["sede_id"] = sede_filtro
            s = SedeInstitucion.query.get(sede_filtro)
            session["sede_nombre"] = s.nombre if s else ""
        else:
            session.pop("sede_id", None)
            session.pop("sede_nombre", None)

    q_est = q_estudiantes()
    sede_nombre_sel = session.get("sede_nombre") or ""
    if sede_filtro and sede_nombre_sel:
        # filtrar estudiantes por campo sede (nombre) si está cargado
        q_est = q_est.filter(
            or_(
                Estudiante.sede == sede_nombre_sel,
                Estudiante.sede.ilike(f"%{sede_nombre_sel}%"),
            )
        )
    estudiantes_total = q_est.count()
    ingresos_hoy = q_ingresos().filter(IngresoPorteria.fecha == hoy).all()
    est_ids_sede = set()
    if sede_filtro and sede_nombre_sel:
        est_ids_sede = {e.id for e in q_est.limit(5000).all()}
        ingresos_hoy = [i for i in ingresos_hoy if i.estudiante_id in est_ids_sede]
    temprano = sum(1 for i in ingresos_hoy if i.estado == "Temprano")
    tarde = sum(1 for i in ingresos_hoy if i.estado == "Tarde")
    ids_ingreso = {i.estudiante_id for i in ingresos_hoy}
    no_llego = max(estudiantes_total - len(ids_ingreso), 0)
    usuarios_total = q_usuarios().count()
    auditorias_total = Auditoria.query.count()

    # % asistencia y comparación con ayer
    presentes = temprano + tarde
    pct_asist = round(100.0 * presentes / estudiantes_total, 1) if estudiantes_total else 0.0
    try:
        from datetime import datetime as _dt, timedelta as _td
        ayer = (_dt.strptime(hoy, "%Y-%m-%d") - _td(days=1)).strftime("%Y-%m-%d")
    except Exception:
        ayer = hoy
    ingresos_ayer = q_ingresos().filter(IngresoPorteria.fecha == ayer).all()
    tarde_ayer = sum(1 for i in ingresos_ayer if i.estado == "Tarde")
    if tarde_ayer > 0:
        delta_tarde = round(100.0 * (tarde - tarde_ayer) / tarde_ayer, 1)
        txt_tarde = f"{abs(delta_tarde)}% {'más' if delta_tarde > 0 else 'menos'} de tardanzas que ayer"
    else:
        txt_tarde = f"{tarde} llegadas tarde registradas hoy" if tarde else "Sin tardanzas registradas"
