# ═══════════════════════ SECRETARÍA · Documentos legales y reportes MEN ═══════════════════════

def _guard_secretaria_docs():
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ("Secretaría", "Rectoría", "Coordinación", "Administrador", "Soporte"):
        return acceso_denegado("Solo Secretaría, Coordinación o Rectoría.")
    return None


def _puede_editar_secretaria():
    return rol_actual() in ("Secretaría", "Administrador", "Soporte", "Rectoría")


def _promedio_final_estudiante(est_id, iid):
    """Promedio general del estudiante (todas las materias, todos los periodos con nota)."""
    regs = NotaRegistro.query.filter_by(estudiante_id=est_id).all()
    if iid is not None:
        regs = [r for r in regs if r.institucion_id is None or int(r.institucion_id) == int(iid)]
    vals = [float(r.valor) for r in regs if r.valor is not None]
    if not vals:
        return None
    return sum(vals) / len(vals)


def _notas_por_materia_estudiante(e, iid):
    """[(materia, promedio, desempeño)] para el certificado / consolidado."""
    catalogo = [m for m in (materias_para_grado(e.grado) or []) if m and m != "General"]
    regs = NotaRegistro.query.filter_by(estudiante_id=e.id).all()
    if iid is not None:
        regs = [r for r in regs if r.institucion_id is None or int(r.institucion_id) == int(iid)]
    out = []
    for m in catalogo:
        vals = [float(r.valor) for r in regs if r.valor is not None and (r.asignatura or "").strip().lower() == m.strip().lower()]
        prom = (sum(vals) / len(vals)) if vals else None
        lbl, _ = desempeno_label(prom)
        out.append((m, prom, lbl))
    return out


