@app.route("/secretaria/planilla-grupo/generar")
def secretaria_planilla_grupo_generar():
    g = _guard_secretaria_docs()
    if g:
        return g
    ok_rl, espera = _rate_limit("planilla-grupo", max_veces=15, ventana_seg=60)
    if not ok_rl:
        return _rate_limit_response(espera)
    usuario_id = request.args.get("usuario_id", type=int)
    tipo = (request.args.get("tipo") or "asistencia").strip()
    mes = (request.args.get("mes") or "").strip()[:40]
    anio = (request.args.get("anio") or "").strip()[:10]
    grado_f = (request.args.get("grado") or "").strip()
    grupo_f = (request.args.get("grupo") or "").strip()
    docente = Usuario.query.get(usuario_id) if usuario_id else None
    if not docente or (docente.rol or "") not in ("Docente", "DOCENTE"):
        return page("Planilla", shell("<div class='msg err'>Docente no válido. <a href='/secretaria/planilla-grupo'>Volver</a></div>"))
    iid = institucion_id_actual()
    combos = _grupos_de_docente(docente.id, iid, grado_filtro=grado_f or None, grupo_filtro=grupo_f or None)
    if not combos and grado_f:
        # Forzar combo aunque no haya grupo: buscar estudiantes del grado
        q = Estudiante.query.filter(Estudiante.grado == grado_f)
        if iid is not None:
            q = q.filter(Estudiante.institucion_id == iid)
        if grupo_f:
            q = q.filter(Estudiante.grupo == grupo_f)
        combos = sorted({(e.grado or grado_f, (e.grupo or "").strip()) for e in q.all()})
    if not combos:
        return page("Planilla", shell(
            f"<div class='msg err'>No hay estudiantes matriculados en el grado/grupo seleccionado "
            f"({_esc(grado_f or '—')} / {_esc(grupo_f or 'todos')}). "
            f"Importe estudiantes o elija otro grado. "
            f"<a href='/secretaria/planilla-grupo'>Volver</a></div>"
        ))
    inst = Institucion.query.get(iid) if iid else None
    nom_inst = (inst.nombre if inst else None) or INST_NOMBRE or "Institución educativa"
    from reportlab.lib.pagesizes import letter
    from reportlab.pdfgen import canvas as _canvas
    # Carta horizontal (Letter) — tamaño block/escolar estándar en Colombia
    page_w, page_h = letter  # 612 x 792 pt
    # Usamos landscape letter compacto
    from reportlab.lib.pagesizes import landscape as _ls
    buf = BytesIO()
    pdf = _canvas.Canvas(buf, pagesize=_ls(letter))
    w, h = _ls(letter)
    dias_mes = 31
    for grado, grupo in combos:
        gk = _norm_grado_key(grado)
        q = Estudiante.query
        if iid is not None:
            q = q.filter(Estudiante.institucion_id == iid)
        # Match flexible de grado
        candidatos = q.order_by(Estudiante.apellido.asc(), Estudiante.nombre.asc()).limit(500).all()
        estudiantes = []
        for e in candidatos:
            if _norm_grado_key(getattr(e, "grado", None)) != gk:
                continue
            eg = (getattr(e, "grupo", None) or "").strip()
            if grupo:
                if eg != str(grupo).strip() and eg.lstrip("0") != str(grupo).strip().lstrip("0"):
                    continue
            estudiantes.append(e)
        # --- Encabezado compacto ---
        pdf.setFont("Helvetica-Bold", 11)
        pdf.drawCentredString(w / 2, h - 22, str(nom_inst)[:80])
        pdf.setFont("Helvetica-Bold", 10)
        titulo = "PLANILLA DE ASISTENCIA" if tipo == "asistencia" else "PLANILLA DE NOTAS"
        pdf.drawCentredString(w / 2, h - 36, titulo)
        pdf.setFont("Helvetica", 8)
        pdf.drawString(24, h - 52, f"Docente: {(docente.nombre_completo or docente.usuario)}")
        pdf.drawString(220, h - 52, f"Grado: {grado}" + (f" - {grupo}" if grupo else ""))
        pdf.drawString(380, h - 52, f"Año: {anio}")
        pdf.drawString(480, h - 52, f"Mes: {mes}" if tipo == "asistencia" else "")
        y_tabla = h - 68
        col_orden_w, col_nombre_w, col_codigo_w = 22, 170, 54
        x0 = 24
        x_orden = x0
        x_nombre = x_orden + col_orden_w
        x_codigo = x_nombre + col_nombre_w
        x_grid = x_codigo + col_codigo_w
        n_cols_grid = dias_mes if tipo == "asistencia" else 8
        ancho_disp = (w - 24) - x_grid
        col_w = ancho_disp / n_cols_grid
        alto_fila = 12
        alto_encabezado = 14
        pdf.setFont("Helvetica-Bold", 6)
        pdf.rect(x_orden, y_tabla - alto_encabezado, col_orden_w, alto_encabezado)
        pdf.drawCentredString(x_orden + col_orden_w / 2, y_tabla - alto_encabezado + 4, "N°")
        pdf.rect(x_nombre, y_tabla - alto_encabezado, col_nombre_w, alto_encabezado)
        pdf.drawCentredString(x_nombre + col_nombre_w / 2, y_tabla - alto_encabezado + 4, "APELLIDOS Y NOMBRE")
        pdf.rect(x_codigo, y_tabla - alto_encabezado, col_codigo_w, alto_encabezado)
        pdf.drawCentredString(x_codigo + col_codigo_w / 2, y_tabla - alto_encabezado + 4, "CÓDIGO")
        for c in range(n_cols_grid):
            cx = x_grid + c * col_w
            pdf.rect(cx, y_tabla - alto_encabezado, col_w, alto_encabezado)
            etiqueta = str(c + 1) if tipo == "asistencia" else (f"P{c+1}" if c < 4 else "")
            pdf.setFont("Helvetica-Bold", 5)
            pdf.drawCentredString(cx + col_w / 2, y_tabla - alto_encabezado + 4, etiqueta)
        y = y_tabla - alto_encabezado
        pdf.setFont("Helvetica", 6)
        # Solo alumnos + 2 filas libres (no llena la hoja de vacíos)
        max_filas = max(len(estudiantes) + 2, 12)
        max_filas = min(max_filas, 35)
        for i in range(max_filas):
            y -= alto_fila
            if y < 28:
                break
            pdf.rect(x_orden, y, col_orden_w, alto_fila)
            pdf.drawCentredString(x_orden + col_orden_w / 2, y + 3, str(i + 1))
            pdf.rect(x_nombre, y, col_nombre_w, alto_fila)
            pdf.rect(x_codigo, y, col_codigo_w, alto_fila)
            if i < len(estudiantes):
                e = estudiantes[i]
                pdf.drawString(x_nombre + 2, y + 3, f"{(e.apellido or '')} {(e.nombre or '')}"[:42])
                pdf.drawString(x_codigo + 2, y + 3, str(e.codigo or "")[:12])
            for c in range(n_cols_grid):
                cx = x_grid + c * col_w
                pdf.rect(cx, y, col_w, alto_fila)
        # Pie de página tamaño carta
        pdf.setFont("Helvetica", 6)
        pdf.setFillColorRGB(0.4, 0.4, 0.45)
        pdf.drawString(24, 14, "Formato carta (Letter) · EduTrack / PROCSIS · Uso institucional")
        pdf.setFillColorRGB(0, 0, 0)
        pdf.showPage()
    pdf.save()
    buf.seek(0)
    registrar_auditoria("Planilla de grupo generada", f"{docente.usuario}: {len(combos)} grupo(s) · {tipo}")
    return send_file(buf, as_attachment=True, download_name=f"planilla_{tipo}_{docente.usuario}.pdf", mimetype="application/pdf")


@app.route("/secretaria/certificado", methods=["GET", "POST"])
def secretaria_certificado_buscar():
    g = _guard_secretaria_docs()
    if g:
        return g
    iid = institucion_id_actual()
    resultados = []
    q = (request.values.get("q") or "").strip()
    if q:
        query = Estudiante.query.filter(
            (Estudiante.codigo.ilike(f"%{q}%")) | (Estudiante.documento.ilike(f"%{q}%")) |
            (Estudiante.nombre.ilike(f"%{q}%")) | (Estudiante.apellido.ilike(f"%{q}%"))
        )
        if iid is not None:
            query = query.filter(Estudiante.institucion_id == iid)
        resultados = query.limit(30).all()
    filas = "".join(
        f"<tr><td>{_esc(e.codigo)}</td><td>{_esc(estudiante_nombre(e))}</td><td>{_esc(e.documento)}</td><td>{_esc(e.grado)}</td>"
        f"<td><a class='btn-pdf' href='/secretaria/certificado/{e.id}/pdf?tipo=matricula' target='_blank'>Constancia (matrícula)</a> "
        f"<a class='btn-pdf' href='/secretaria/certificado/{e.id}/pdf?tipo=aprobado' target='_blank'>Cursó y aprobó el año</a></td></tr>"
        for e in resultados
    ) or ('<tr><td colspan="5">Busque un estudiante para generar su certificado.</td></tr>' if q else '')
    content = f"""
<header class="role-hero"><div>
  <h1>Certificado de estudio</h1>
  <p>Incluye materias, notas y equivalencia SIEE del año lectivo, con código QR de verificación.</p>
</div>
<a class="btn" href="/secretaria/documentos">Volver</a></header>
<section class="role-panel">
  <form method="GET">
    <label><b>Buscar estudiante</b> (código, documento o nombre)</label>
    <input name="q" value="{_esc(q)}" placeholder="Ej. 2026045 o Juan Pérez" autofocus>
    <button type="submit" style="margin-top:10px">Buscar</button>
  </form>
  <div style="overflow-x:auto;margin-top:14px">
    <table>
      <tr><th>Código</th><th>Nombre</th><th>Documento</th><th>Grado</th><th>Acción</th></tr>
      {filas}
    </table>
  </div>
  <p class="mini-text" style="margin-top:8px">"Cursó y aprobó el año" solo usa ese texto si el estudiante ya está marcado como <b>Promovido</b> en el <a href="/secretaria/simat">reporte SIMAT</a>; si no, genera la constancia de matrícula normal.</p>
</section>
"""
    return page("Certificado de estudio", shell(content))


@app.route("/secretaria/certificado/<int:id>/pdf")
def secretaria_certificado_pdf(id):
    g = _guard_secretaria_docs()
    if g:
        return g
    ok_rl, espera = _rate_limit("certificado-pdf", max_veces=30, ventana_seg=60)
    if not ok_rl:
        return _rate_limit_response(espera)
    e = Estudiante.query.get_or_404(id)
    iid = institucion_id_actual()
    if iid is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid):
        return acceso_denegado()
    import secrets as _secrets
    codigo = "CERT-" + _secrets.token_hex(6).upper()
    anio = str(ahora().year) if hasattr(ahora(), "year") else fecha_hoy()[:4]
    try:
        db.create_all()
    except Exception:
        pass
    cert = CertificadoEstudio(
        institucion_id=e.institucion_id, estudiante_id=e.id, codigo_verificacion=codigo,
        tipo="ESTUDIO_NOTAS", emitido_en=f"{fecha_hoy()} {hora_actual()}",
        emitido_por=session.get("usuario") or "secretaría", anio=anio,
    )
    db.session.add(cert)
    db.session.commit()
    registrar_auditoria("Certificado de estudio generado", f"{estudiante_nombre(e)} ({e.codigo}) · {codigo}")
    materias = _notas_por_materia_estudiante(e, iid)
    inst = Institucion.query.get(iid) if iid else None
    nom_inst = (inst.nombre if inst else None) or INST_NOMBRE or "Institución educativa"
    promedio_gral = _promedio_final_estudiante(e.id, iid)
    tipo_cert = (request.args.get("tipo") or "matricula").strip()
    aprobo = (getattr(e, "estado_promocion", "") or "").strip().lower() == "promovido"
    if tipo_cert == "aprobado" and aprobo:
        frase_estado = (
            f"cursó y aprobó satisfactoriamente el grado {e.grado} durante el año lectivo {anio}, "
            f"con un promedio general de {promedio_gral:.1f}" if promedio_gral is not None else
            f"cursó y aprobó satisfactoriamente el grado {e.grado} durante el año lectivo {anio}"
        )
    else:
        frase_estado = f"se encuentra matriculado(a) en el grado {e.grado} durante el año lectivo {anio}"
    from reportlab.lib.pagesizes import letter
    from reportlab.pdfgen import canvas as _canvas
    from reportlab.lib.units import cm
    from reportlab.lib.utils import simpleSplit
    buf = BytesIO()
    pdf = _canvas.Canvas(buf, pagesize=letter)
    w, h = letter
    try:
        pdf.drawImage(logo_fs(), 2 * cm, h - 3 * cm, width=1.6 * cm, height=1.6 * cm, preserveAspectRatio=True, mask="auto")
    except Exception:
        pass
    pdf.setFont("Helvetica-Bold", 14)
    pdf.drawCentredString(w / 2, h - 2.2 * cm, str(nom_inst)[:70])
    pdf.setFont("Helvetica-Bold", 12)
    pdf.drawCentredString(w / 2, h - 2.9 * cm, "CERTIFICADO DE ESTUDIO")
    pdf.setFont("Helvetica", 10)
    y = h - 4.2 * cm
    texto = (
        f"La institución certifica que el(la) estudiante {estudiante_nombre(e)}, identificado(a) con "
        f"{e.tipo_doc or 'documento'} {e.documento or '—'}, {frase_estado}, "
        f"con el siguiente desempeño académico:"
    )
    for ln in simpleSplit(texto, "Helvetica", 10, w - 4 * cm):
        pdf.drawString(2 * cm, y, ln)
        y -= 14
    y -= 10
    pdf.setFont("Helvetica-Bold", 9)
    pdf.drawString(2 * cm, y, "Asignatura")
    pdf.drawString(11 * cm, y, "Nota final")
    pdf.drawString(14.5 * cm, y, "Desempeño (Decreto 1290)")
    y -= 4
    pdf.line(2 * cm, y, w - 2 * cm, y)
    y -= 12
    pdf.setFont("Helvetica", 9)
    for materia, prom, lbl in materias:
        if y < 4 * cm:
            pdf.showPage()
            y = h - 3 * cm
            pdf.setFont("Helvetica", 9)
        pdf.drawString(2 * cm, y, materia[:45])
        pdf.drawString(11 * cm, y, f"{prom:.1f}" if prom is not None else "—")
        pdf.drawString(14.5 * cm, y, lbl if prom is not None else "Sin registrar")
        y -= 14
    y -= 16
    pdf.setFont("Helvetica", 9)
    pdf.drawString(2 * cm, y, f"Código de verificación: {codigo}")
    y -= 14
    pdf.drawString(2 * cm, y, f"Emitido: {cert.emitido_en}")
    y -= 40
    pdf.drawString(2 * cm, y, "___________________________")
    y -= 12
    pdf.drawString(2 * cm, y, "Secretaría académica")
    # QR real de verificación en la esquina inferior
    try:
        base = request.host_url.rstrip("/")
    except Exception:
        base = ""
    qr_url = f"{base}/verificar-certificado/{codigo}"
    qr_img = qrcode.make(qr_url)
    qr_buf = BytesIO()
    qr_img.save(qr_buf, format="PNG")
    qr_buf.seek(0)
    from reportlab.lib.utils import ImageReader
    pdf.drawImage(ImageReader(qr_buf), w - 4.5 * cm, 1.3 * cm, width=2.3 * cm, height=2.3 * cm)
    pdf.setFont("Helvetica", 6.5)
    pdf.drawCentredString(w - 3.35 * cm, 1.15 * cm, "Verifique aquí")
    pdf.setFont("Helvetica", 7)
    pdf.drawString(2 * cm, 1.3 * cm, f"Verifique autenticidad: {qr_url}")
    pdf.save()
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name=f"certificado_{e.codigo}_{codigo}.pdf", mimetype="application/pdf")


# ── Acta de grado ────────────────────────────────────────────────────────────

def _texto_acta(e, cfg, anio, tipo_ciclo):
    if tipo_ciclo == "bachiller":
        return (
            f"Que el(la) alumno(a) {estudiante_nombre(e)}, identificado(a) con {e.tipo_doc or 'documento'} "
            f"{e.documento or '—'}, cursó y aprobó los estudios de Educación Media correspondientes al grado "
            f"Undécimo (11°), de conformidad con las normas vigentes del Ministerio de Educación Nacional, "
            f"razón por la cual se le confiere el título de BACHILLER ACADÉMICO, en ceremonia realizada el "
            f"{cfg.acta_fecha or '—'}, según consta en el Acta N.º {cfg.acta_numero or '—'}, Libro N.º "
            f"{cfg.acta_libro or '—'}, Folio N.º {cfg.acta_folio or '—'}."
        )
    return (
        f"Que el(la) alumno(a) {estudiante_nombre(e)}, identificado(a) con {e.tipo_doc or 'documento'} "
        f"{e.documento or '—'}, cursó y aprobó satisfactoriamente el grado {e.grado} durante el año lectivo "
        f"{anio}, culminando el ciclo correspondiente, según consta en el Acta N.º {cfg.acta_numero or '—'}, "
        f"Libro N.º {cfg.acta_libro or '—'}, Folio N.º {cfg.acta_folio or '—'}, de fecha {cfg.acta_fecha or '—'}."
    )


@app.route("/secretaria/acta-grado", methods=["GET", "POST"])
def secretaria_acta_grado():
    g = _guard_secretaria_docs()
    if g:
        return g
    cfg = config()
    mensaje = ""
    if request.method == "POST" and request.form.get("accion") == "guardar_ceremonia":
        if not _puede_editar_secretaria():
            return acceso_denegado()
        cfg.acta_numero = (request.form.get("acta_numero") or "").strip()[:40]
        cfg.acta_libro = (request.form.get("acta_libro") or "").strip()[:40]
        cfg.acta_folio = (request.form.get("acta_folio") or "").strip()[:40]
        cfg.acta_fecha = (request.form.get("acta_fecha") or "").strip()[:20]
        db.session.commit()
        registrar_auditoria("Acta de grado · datos de ceremonia", f"{cfg.acta_numero}/{cfg.acta_libro}/{cfg.acta_folio}")
        mensaje = "Datos de la ceremonia guardados."
    iid = institucion_id_actual()
    q = Estudiante.query.filter(Estudiante.grado.in_(["11°", "11", "Transición", "Transicion", "5°", "5"]))
    if iid is not None:
        q = q.filter(Estudiante.institucion_id == iid)
    candidatos = q.order_by(Estudiante.grado.asc(), Estudiante.apellido.asc()).all()
    filas = "".join(
        f"<tr><td><input type='checkbox' name='ids' value='{e.id}'></td><td>{_esc(estudiante_nombre(e))}</td>"
        f"<td>{_esc(e.documento)}</td><td>{_esc(e.grado)}</td>"
        f"<td>{_esc(getattr(e,'estado_promocion','') or 'Sin definir')}</td></tr>"
        for e in candidatos
    ) or '<tr><td colspan="5">No hay estudiantes en 11°, 5° o Transición registrados.</td></tr>'
    content = f"""
<header class="role-hero"><div>
  <h1>🎓 Actas de grado</h1>
  <p>Registre una sola vez los datos de la ceremonia; luego genere el PDF de cada estudiante en lote.</p>
</div>
<a class="btn" href="/secretaria/documentos">Volver</a></header>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
<section class="role-panel">
  <h2>Datos de la ceremonia (una vez por promoción)</h2>
  <form method="POST">
    <input type="hidden" name="accion" value="guardar_ceremonia">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
      <div><label><b>Número de Acta</b></label><input name="acta_numero" value="{_esc(cfg.acta_numero)}"></div>
      <div><label><b>Número de Libro</b></label><input name="acta_libro" value="{_esc(cfg.acta_libro)}"></div>
      <div><label><b>Número de Folio</b></label><input name="acta_folio" value="{_esc(cfg.acta_folio)}"></div>
      <div><label><b>Fecha del grado</b></label><input type="date" name="acta_fecha" value="{_esc(cfg.acta_fecha)}"></div>
    </div>
    <button type="submit" style="margin-top:12px">Guardar datos de ceremonia</button>
  </form>
</section>
<section class="role-panel" style="margin-top:12px">
  <h2>Graduandos (11° Bachillerato · 5° y Transición ciclo)</h2>
  <form method="POST" action="/secretaria/acta-grado/generar" target="_blank">
    <div style="overflow-x:auto">
      <table>
        <tr><th></th><th>Nombre</th><th>Documento</th><th>Grado</th><th>Estado SIMAT</th></tr>
        {filas}
      </table>
    </div>
    <button type="submit" style="margin-top:12px">Generar actas seleccionadas (ZIP de PDFs)</button>
  </form>
  <p class="mini-text" style="margin-top:8px">Debe guardar primero los datos de la ceremonia; si quedan en blanco, el PDF los mostrará como "—".</p>
</section>
"""
    return page("Actas de grado", shell(content))


@app.route("/secretaria/acta-grado/generar", methods=["POST"])
def secretaria_acta_grado_generar():
    g = _guard_secretaria_docs()
    if g:
        return g
    ok_rl, espera = _rate_limit("acta-grado-generar", max_veces=10, ventana_seg=120)
    if not ok_rl:
        return _rate_limit_response(espera)
    ids = request.form.getlist("ids")
    if not ids:
        return page("Actas de grado", shell("<div class='msg err'>No seleccionó ningún estudiante. <a href='/secretaria/acta-grado'>Volver</a></div>"))
    cfg = config()
    iid = institucion_id_actual()
    inst = Institucion.query.get(iid) if iid else None
    nom_inst = (inst.nombre if inst else None) or INST_NOMBRE or "Institución educativa"
    anio = str(ahora().year) if hasattr(ahora(), "year") else fecha_hoy()[:4]
    from reportlab.lib.pagesizes import letter
    from reportlab.pdfgen import canvas as _canvas
    from reportlab.lib.units import cm
    from reportlab.lib.utils import simpleSplit, ImageReader
    import zipfile
    zip_buf = BytesIO()
    zf = zipfile.ZipFile(zip_buf, "w", zipfile.ZIP_DEFLATED)
    generados = 0
    for sid in ids:
        e = Estudiante.query.get(int(sid))
        if not e:
            continue
        if iid is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid):
            continue
        tipo_ciclo = "bachiller" if (e.grado or "").replace("°", "").strip() == "11" else "ciclo"
        import secrets as _secrets
        codigo = "ACTA-" + _secrets.token_hex(6).upper()
        cert = CertificadoEstudio(
            institucion_id=e.institucion_id, estudiante_id=e.id, codigo_verificacion=codigo,
            tipo="ACTA_GRADO", emitido_en=f"{fecha_hoy()} {hora_actual()}",
            emitido_por=session.get("usuario") or "secretaría", anio=anio,
        )
        db.session.add(cert)
        buf = BytesIO()
        pdf = _canvas.Canvas(buf, pagesize=letter)
        w, h = letter
        try:
            pdf.drawImage(logo_fs(), 2 * cm, h - 3 * cm, width=1.6 * cm, height=1.6 * cm, preserveAspectRatio=True, mask="auto")
        except Exception:
            pass
        pdf.setFont("Helvetica-Bold", 14)
        pdf.drawCentredString(w / 2, h - 2.2 * cm, str(nom_inst)[:70])
        pdf.setFont("Helvetica-Bold", 13)
        pdf.drawCentredString(w / 2, h - 3 * cm, "ACTA DE GRADO" if tipo_ciclo == "bachiller" else "ACTA DE PROMOCIÓN DE CICLO")
        pdf.setFont("Helvetica", 11)
        y = h - 4.5 * cm
        texto = _texto_acta(e, cfg, anio, tipo_ciclo)
        for ln in simpleSplit(texto, "Helvetica", 11, w - 4 * cm):
            pdf.drawString(2 * cm, y, ln)
            y -= 16
        y -= 40
        pdf.drawString(2 * cm, y, "___________________________")
        pdf.drawString(11 * cm, y, "___________________________")
        y -= 12
        pdf.drawString(2 * cm, y, "Rector(a)")
        pdf.drawString(11 * cm, y, "Secretario(a) académico(a)")
        try:
            base = request.host_url.rstrip("/")
        except Exception:
            base = ""
        qr_url = f"{base}/verificar-certificado/{codigo}"
        qr_img = qrcode.make(qr_url)
        qr_buf = BytesIO()
        qr_img.save(qr_buf, format="PNG")
        qr_buf.seek(0)
        pdf.drawImage(ImageReader(qr_buf), w - 4.5 * cm, 1.3 * cm, width=2.3 * cm, height=2.3 * cm)
        pdf.setFont("Helvetica", 6.5)
        pdf.drawCentredString(w - 3.35 * cm, 1.15 * cm, "Verifique aquí")
        pdf.setFont("Helvetica", 7)
        pdf.drawString(2 * cm, 1.3 * cm, f"Código: {codigo} · Verifique en: {qr_url}")
        pdf.save()
        buf.seek(0)
        zf.writestr(f"acta_{e.codigo}_{codigo}.pdf", buf.read())
        generados += 1
    zf.close()
    db.session.commit()
    registrar_auditoria("Actas de grado generadas (lote)", f"{generados} estudiante(s)")
    zip_buf.seek(0)
    return send_file(zip_buf, as_attachment=True, download_name=f"actas_grado_{anio}.zip", mimetype="application/zip")


# ── Reporte SIMAT: Promoción / Repitencia ────────────────────────────────────

_SIMAT_ESTADOS = ["Promovido", "No Promovido", "Desertor", "Trasladado"]


@app.route("/secretaria/simat", methods=["GET", "POST"])
def secretaria_simat():
    g = _guard_secretaria_docs()
    if g:
        return g
    iid = institucion_id_actual()
    mensaje = ""
    if request.method == "POST":
        if not _puede_editar_secretaria():
            return acceso_denegado()
        cambios = 0
        for key, val in request.form.items():
            if key.startswith("estado_"):
                try:
                    sid = int(key.split("_", 1)[1])
                except Exception:
                    continue
                e = Estudiante.query.get(sid)
                if not e:
                    continue
                if iid is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid):
                    continue
                if val in _SIMAT_ESTADOS and e.estado_promocion != val:
                    e.estado_promocion = val
                    cambios += 1
        db.session.commit()
        if cambios:
            registrar_auditoria("SIMAT: estado final actualizado", f"{cambios} estudiante(s)")
        mensaje = f"Guardado: {cambios} estudiante(s) actualizado(s)."
    q = Estudiante.query
    if iid is not None:
        q = q.filter(Estudiante.institucion_id == iid)
    estudiantes = q.order_by(Estudiante.grado.asc(), Estudiante.apellido.asc()).all()
    def _opts(actual):
        return "".join(f'<option value="{o}" {"selected" if o==actual else ""}>{o}</option>' for o in [""] + _SIMAT_ESTADOS)
    filas = "".join(
        f"<tr><td>{_esc(e.codigo)}</td><td>{_esc(estudiante_nombre(e))}</td><td>{_esc(e.documento)}</td><td>{_esc(e.grado)}</td>"
        f"<td><select name='estado_{e.id}'>{_opts(getattr(e,'estado_promocion','') or '')}</select></td></tr>"
        for e in estudiantes
    ) or '<tr><td colspan="5">Sin estudiantes</td></tr>'
    content = f"""
<header class="role-hero"><div>
  <h1>📋 Reporte SIMAT · Promoción y repitencia</h1>
  <p>Marque el estado final de cada estudiante para el cierre de año y descargue el archivo plano para el SIMAT.</p>
</div>
<a class="btn" href="/secretaria/documentos">Volver</a></header>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
<section class="role-panel">
  <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px">
    <a class="btn" href="/secretaria/simat/exportar?formato=csv">⬇ Descargar CSV (SIMAT)</a>
    <a class="btn" href="/secretaria/simat/exportar?formato=txt">⬇ Descargar TXT (SIMAT)</a>
  </div>
  <form method="POST">
    <div style="overflow-x:auto">
      <table>
        <tr><th>Código</th><th>Nombre</th><th>Documento</th><th>Grado</th><th>Estado final</th></tr>
        {filas}
      </table>
    </div>
    <button type="submit" style="margin-top:12px">Guardar estados</button>
  </form>
</section>
"""
    return page("Reporte SIMAT", shell(content))


@app.route("/secretaria/simat/exportar")
def secretaria_simat_exportar():
    g = _guard_secretaria_docs()
    if g:
        return g
    from flask import Response
    iid = institucion_id_actual()
    q = Estudiante.query
    if iid is not None:
        q = q.filter(Estudiante.institucion_id == iid)
    estudiantes = q.order_by(Estudiante.grado.asc(), Estudiante.apellido.asc()).all()
    formato = (request.args.get("formato") or "csv").strip().lower()
    # Códigos de estado según nomenclatura habitual del reporte de novedades SIMAT
    cod_estado = {"Promovido": "1", "No Promovido": "2", "Desertor": "3", "Trasladado": "4"}
    encabezado = ["TIPO_DOC", "NUM_DOC", "APELLIDO1", "APELLIDO2", "NOMBRE1", "NOMBRE2", "GRADO", "CODIGO_ESTUDIANTE", "ESTADO_FINAL", "COD_ESTADO"]
    filas = []
    for e in estudiantes:
        filas.append([
            e.tipo_doc or "TI", e.documento or "", e.apellido1 or (e.apellido or "").split(" ")[0],
            e.apellido2 or "", e.nombre1 or (e.nombre or "").split(" ")[0], e.nombre2 or "",
            (e.grado or "").replace("°", ""), e.codigo or "",
            e.estado_promocion or "SIN_DEFINIR", cod_estado.get(e.estado_promocion or "", "0"),
        ])
    sep = "," if formato == "csv" else "|"
    lineas = [sep.join(encabezado)] + [sep.join(str(v) for v in fila) for fila in filas]
    contenido = "\n".join(lineas)
    registrar_auditoria("SIMAT exportado", f"{len(filas)} estudiante(s) · formato {formato}")
    ext = "csv" if formato == "csv" else "txt"
    return Response(
        contenido,
        mimetype="text/csv" if formato == "csv" else "text/plain",
        headers={"Content-Disposition": f"attachment; filename=simat_promocion_{fecha_hoy()}.{ext}"},
    )


