def _consolidado_siee_datos():
    iid = institucion_id_actual()
    q = Estudiante.query
    if iid is not None:
        q = q.filter(Estudiante.institucion_id == iid)
    estudiantes = q.order_by(Estudiante.grado.asc(), Estudiante.apellido.asc()).all()
    out = []
    for e in estudiantes:
        prom = _promedio_final_estudiante(e.id, iid)
        lbl, _ = desempeno_label(prom)
        out.append((e, prom, lbl))
    return out


@app.route("/secretaria/consolidado-siee/pdf")
def secretaria_consolidado_siee_pdf():
    g = _guard_secretaria_docs()
    if g:
        return g
    datos = _consolidado_siee_datos()
    iid = institucion_id_actual()
    inst = Institucion.query.get(iid) if iid else None
    nom_inst = (inst.nombre if inst else None) or INST_NOMBRE or "Institución educativa"
    from reportlab.lib.pagesizes import landscape, letter
    from reportlab.pdfgen import canvas as _canvas
    buf = BytesIO()
    pdf = _canvas.Canvas(buf, pagesize=landscape(letter))
    w, h = landscape(letter)
    pdf.setFont("Helvetica-Bold", 13)
    pdf.drawCentredString(w / 2, h - 30, str(nom_inst)[:80])
    pdf.setFont("Helvetica-Bold", 11)
    pdf.drawCentredString(w / 2, h - 46, f"LIBRO CALIFICADOR FINAL · Año lectivo {ahora().year if hasattr(ahora(),'year') else fecha_hoy()[:4]}")
    y = h - 74
    pdf.setFont("Helvetica-Bold", 9)
    pdf.drawString(30, y, "Código"); pdf.drawString(120, y, "Nombre"); pdf.drawString(420, y, "Grado")
    pdf.drawString(500, y, "Promedio"); pdf.drawString(580, y, "Desempeño")
    y -= 4
    pdf.line(30, y, w - 30, y)
    y -= 14
    pdf.setFont("Helvetica", 8.5)
    for e, prom, lbl in datos:
        if y < 40:
            pdf.showPage()
            y = h - 40
            pdf.setFont("Helvetica", 8.5)
        pdf.drawString(30, y, str(e.codigo)[:20])
        pdf.drawString(120, y, estudiante_nombre(e)[:55])
        pdf.drawString(420, y, str(e.grado))
        pdf.drawString(500, y, f"{prom:.2f}" if prom is not None else "—")
        pdf.drawString(580, y, lbl)
        y -= 13
    pdf.save()
    buf.seek(0)
    registrar_auditoria("Consolidado SIEE exportado (PDF)", f"{len(datos)} estudiante(s)")
    return send_file(buf, as_attachment=True, download_name=f"libro_calificador_final_{fecha_hoy()}.pdf", mimetype="application/pdf")


@app.route("/secretaria/consolidado-siee/excel")
def secretaria_consolidado_siee_excel():
    g = _guard_secretaria_docs()
    if g:
        return g
    datos = _consolidado_siee_datos()
    wb = Workbook()
    ws = wb.active
    ws.title = "Libro Calificador Final"
    encabezado = ["Código", "Documento", "Nombre completo", "Grado", "Promedio final", "Desempeño nacional"]
    ws.append(encabezado)
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill(start_color="0B2D57", end_color="0B2D57", fill_type="solid")
    for e, prom, lbl in datos:
        ws.append([e.codigo, e.documento, estudiante_nombre(e), e.grado, round(prom, 2) if prom is not None else None, lbl])
    for i, colw in enumerate([14, 16, 34, 10, 14, 18], start=1):
        ws.column_dimensions[get_column_letter(i)].width = colw
    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    registrar_auditoria("Consolidado SIEE exportado (Excel)", f"{len(datos)} estudiante(s)")
    return send_file(buf, as_attachment=True, download_name=f"libro_calificador_final_{fecha_hoy()}.xlsx",
                      mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


# ── PIAR: Índice de inclusión (Decreto 1421 de 2017) ────────────────────────

@app.route("/secretaria/piar", methods=["GET", "POST"])
def secretaria_piar():
    g = _guard_secretaria_docs()
    if g:
        return g
    iid = institucion_id_actual()
    mensaje = ""
    if request.method == "POST":
        sid = request.form.get("estudiante_id")
        e = Estudiante.query.get(int(sid)) if sid else None
        if e and (iid is None or e.institucion_id is None or int(e.institucion_id) == int(iid)):
            e.piar_activo = request.form.get("piar_activo") == "1"
            archivo = request.files.get("piar_pdf")
            if archivo and archivo.filename:
                if not archivo.filename.lower().endswith(".pdf"):
                    mensaje = "El seguimiento debe subirse en PDF."
                else:
                    up_dir = os.path.join(app.root_path, "static", "uploads", "piar")
                    os.makedirs(up_dir, exist_ok=True)
                    fname = f"piar_{e.id}_{int(__import__('time').time())}.pdf"
                    archivo.save(os.path.join(up_dir, fname))
                    e.piar_pdf = f"/static/uploads/piar/{fname}"
            db.session.commit()
            registrar_auditoria("PIAR actualizado", f"{estudiante_nombre(e)}: activo={e.piar_activo}")
            mensaje = mensaje or "Guardado."
    q = Estudiante.query
    if iid is not None:
        q = q.filter(Estudiante.institucion_id == iid)
    estudiantes = q.order_by(Estudiante.sede.asc(), Estudiante.grado.asc(), Estudiante.apellido.asc()).all()
    por_sede = {}
    for e in estudiantes:
        if getattr(e, "piar_activo", False):
            sede = e.sede or "Sin sede"
            por_sede[sede] = por_sede.get(sede, 0) + 1
    resumen = "".join(f"<tr><td>{_esc(s)}</td><td>{n}</td></tr>" for s, n in sorted(por_sede.items())) or '<tr><td colspan="2">Sin estudiantes con PIAR activo</td></tr>'
    filas = "".join(
        f"""<tr><td>{_esc(e.codigo)}</td><td>{_esc(estudiante_nombre(e))}</td><td>{_esc(e.grado)}</td><td>{_esc(e.sede) or '—'}</td>
        <td><form method="POST" enctype="multipart/form-data" style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">
          <input type="hidden" name="estudiante_id" value="{e.id}">
          <label style="font-size:12px"><input type="checkbox" name="piar_activo" value="1" {"checked" if getattr(e,'piar_activo',False) else ""}> Requiere PIAR</label>
          <input type="file" name="piar_pdf" accept="application/pdf" style="width:140px">
          <button type="submit" class="small-action">Guardar</button>
          {"<a href='"+_esc(e.piar_pdf)+"' target='_blank' class='small-action'>Ver PDF</a>" if getattr(e,'piar_pdf',None) else ""}
        </form></td></tr>"""
        for e in estudiantes
    ) or '<tr><td colspan="5">Sin estudiantes</td></tr>'
    content = f"""
<header class="role-hero"><div>
  <h1>📈 PIAR · Índice de inclusión</h1>
  <p>Decreto 1421 de 2017 — Plan Individual de Ajustes Razonables por estudiante y reporte por sede.</p>
</div>
<a class="btn" href="/secretaria/documentos">Volver</a></header>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
<section class="role-panel">
  <h2>Resumen por sede (estudiantes con PIAR activo)</h2>
  <table><tr><th>Sede</th><th>Cantidad</th></tr>{resumen}</table>
</section>
<section class="role-panel" style="margin-top:12px">
  <h2>Detalle por estudiante</h2>
  <div style="overflow-x:auto">
    <table>
      <tr><th>Código</th><th>Nombre</th><th>Grado</th><th>Sede</th><th>PIAR / seguimiento</th></tr>
      {filas}
    </table>
  </div>
</section>
"""
    return page("PIAR", shell(content))


