@app.route("/registrar_estudiante", methods=["GET", "POST"])
def registrar_estudiante():
    if not requiere_login(): return redirect("/login")
    if not puede_estudiantes(): return acceso_denegado("No tienes permiso para registrar estudiantes.")

    mensaje = ""
    if request.method == "POST":
        codigo = request.form.get("codigo", "").strip()
        nombre_chk = request.form.get("nombre", "").strip()
        apellido_chk = request.form.get("apellido", "").strip()
        if codigo and not (nombre_chk and apellido_chk):
            mensaje = "Nombre y apellido son obligatorios, no se guardó el registro."
        elif codigo:
            iid = institucion_id_actual()
            # codigo es UNIQUE global: buscar siempre por código para no intentar INSERT duplicado
            e = Estudiante.query.filter_by(codigo=codigo).first()
            if e:
                # Si ya pertenece a OTRO colegio, no permitir robarlo
                if iid is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid):
                    mensaje = f"El código {codigo} ya está registrado en otra institución. Usa un código distinto."
                else:
                    if iid is not None:
                        e.institucion_id = iid  # reasigna huérfanos o actualiza del mismo colegio
                    _aplicar_nombres_estudiante(e, request.form)
                    e.grado = request.form.get("grado", "").strip()
                    e.director = request.form.get("director", "").strip()
                    e.documento = request.form.get("documento", "").strip()
                    if hasattr(e, "tipo_doc"):
                        e.tipo_doc = (request.form.get("tipo_doc") or e.tipo_doc or "TI").strip()[:20]
                    e.rh = request.form.get("rh", "").strip()
                    e.acudiente = request.form.get("acudiente", "").strip()
                    e.padre = request.form.get("padre", "").strip()
                    e.madre = request.form.get("madre", "").strip()
                    e.telefono_acudiente = request.form.get("telefono_acudiente", "").strip()
                    e.correo_acudiente = request.form.get("correo_acudiente", "").strip()
                    e.direccion = request.form.get("direccion", "").strip()
                    e.observacion = request.form.get("observacion", "").strip()
                    for campo in ("fecha_nacimiento", "genero", "barrio", "estrato", "zona", "mun_res", "dep_res", "grupo", "sede", "jornada", "eps"):
                        if hasattr(e, campo) and request.form.get(campo) is not None:
                            setattr(e, campo, (request.form.get(campo) or "").strip()[:120])
                    try:
                        db.session.commit()
                        foto_f = request.files.get("foto")
                        if foto_f and getattr(foto_f, "filename", ""):
                            ruta = guardar_foto_estudiante(foto_f, e.id, iid)
                            if ruta and hasattr(e, "foto_path"):
                                e.foto_path = ruta
                                db.session.commit()
                        mensaje = "Alumno actualizado correctamente."
                        registrar_auditoria("Actualizar estudiante", f"{codigo} - {e.nombre} {e.apellido} - grado {e.grado} - inst {iid}")
                    except Exception as ex:
                        db.session.rollback()
                        mensaje = f"No se pudo guardar: {ex}"
            else:
                ok_cap, n_est, max_e = capacidad_estudiantes_ok(iid)
                if not ok_cap:
                    mensaje = f"Tope de capacidad alcanzado ({n_est}/{max_e}). Contacte a Procsis para ampliar el plan."
                else:
                    e = Estudiante(codigo=codigo, institucion_id=iid)
                    _aplicar_nombres_estudiante(e, request.form)
                    e.grado = request.form.get("grado", "").strip()
                    e.director = request.form.get("director", "").strip()
                    e.documento = request.form.get("documento", "").strip()
                    if hasattr(e, "tipo_doc"):
                        e.tipo_doc = (request.form.get("tipo_doc") or e.tipo_doc or "TI").strip()[:20]
                    e.rh = request.form.get("rh", "").strip()
                    e.acudiente = request.form.get("acudiente", "").strip()
                    e.padre = request.form.get("padre", "").strip()
                    e.madre = request.form.get("madre", "").strip()
                    e.telefono_acudiente = request.form.get("telefono_acudiente", "").strip()
                    e.correo_acudiente = request.form.get("correo_acudiente", "").strip()
                    e.direccion = request.form.get("direccion", "").strip()
                    e.observacion = request.form.get("observacion", "").strip()
                    for campo in ("fecha_nacimiento", "genero", "barrio", "estrato", "zona", "mun_res", "dep_res", "grupo", "sede", "jornada", "eps"):
                        if hasattr(e, campo) and request.form.get(campo) is not None:
                            setattr(e, campo, (request.form.get(campo) or "").strip()[:120])
                    db.session.add(e)
                    try:
                        db.session.commit()
                        foto_f = request.files.get("foto")
                        if foto_f and getattr(foto_f, "filename", ""):
                            ruta = guardar_foto_estudiante(foto_f, e.id, iid)
                            if ruta and hasattr(e, "foto_path"):
                                e.foto_path = ruta
                                db.session.commit()
                        mensaje = "Alumno registrado correctamente."
                        registrar_auditoria("Guardar estudiante", f"{codigo} - {e.nombre} {e.apellido} - grado {e.grado} - inst {iid}")
                    except Exception as ex:
                        db.session.rollback()
                        mensaje = f"No se pudo registrar: {ex}"

