@app.route("/periodo", methods=["GET", "POST"])
def cambiar_periodo():
    """Cambio de periodo académico (Secretaría y dirección)."""
    if not requiere_login():
        return redirect("/login")
    if not puede_cambiar_periodo():
        return acceso_denegado("No tienes permiso para cambiar el periodo.")
    cfg = config()
    mensaje = ""
    if request.method == "POST":
        custom = (request.form.get("periodo_custom") or "").strip()
        lista = (request.form.get("periodo_actual") or "").strip()
        nuevo = custom or lista
        if nuevo:
            cfg.periodo_actual = nuevo
            db.session.commit()
            mensaje = f"Periodo actualizado a: {nuevo}"
            try:
                registrar_auditoria("Cambio de periodo", nuevo)
            except Exception:
                pass
    periodos = ["Periodo 1", "Periodo 2", "Periodo 3", "Periodo 4", "Final"]
    opts = "".join(
        f'<option value="{p}" {"selected" if (cfg.periodo_actual or "") == p else ""}>{p}</option>'
        for p in periodos
    )
    content = f"""
<header class="role-hero"><div>
  <h1>Periodo académico</h1>
  <p>Define el periodo vigente del colegio. Afecta planilla, asistencia, boletines y reportes.</p>
</div>
<a class="btn" href="/dashboard">Volver</a></header>
{'<div class="msg ok">'+mensaje+'</div>' if mensaje else ''}
<section class="role-panel" style="max-width:520px">
  <form method="POST">
    <label><b>Seleccionar periodo</b></label>
    <select name="periodo_actual">{opts}</select>
    <label style="margin-top:12px"><b>O escribir periodo personalizado</b></label>
    <input name="periodo_custom" placeholder="Ej: Periodo 1 · 2026" value="">
    <p class="mini-text">Si escribes un texto personalizado, ese valor tiene prioridad.</p>
    <button type="submit" style="margin-top:14px">Guardar periodo</button>
  </form>
  <p style="margin-top:16px;font-size:15px">Periodo en sistema ahora: <b style="color:#0B2D57">{cfg.periodo_actual or "—"}</b></p>
</section>
"""
    return page("Periodo", shell(content))


@app.route("/configuracion", methods=["GET", "POST"])
def configuracion():
    """Toda la configuración institucional se gestiona desde la app (no desde código/VS Code)."""
    if not requiere_login():
        return redirect("/login")
    if not puede_configurar():
        return acceso_denegado()
    cfg = config()
    inst = get_institucion()
    mensaje = ""
    if request.method == "POST":
        cfg.periodo_actual = request.form.get("periodo_actual", cfg.periodo_actual)
        cfg.jornada = request.form.get("jornada", cfg.jornada)
        cfg.inst_nombre = request.form.get("inst_nombre", cfg.inst_nombre or "").strip() or cfg.inst_nombre
        cfg.inst_sede = request.form.get("inst_sede", cfg.inst_sede or "").strip() or cfg.inst_sede
        cfg.inst_dane = request.form.get("inst_dane", cfg.inst_dane or "").strip()
        cfg.inst_nit = request.form.get("inst_nit", cfg.inst_nit or "").strip()
        cfg.inst_direccion = request.form.get("inst_direccion", cfg.inst_direccion or "").strip()
        resol_in = request.form.get("inst_resolucion", cfg.inst_resolucion or "").strip()
        # No permitir guardar texto comercial de asesor en resolución educativa
        if resol_in.lower().startswith("asesor"):
            resol_in = ""
        cfg.inst_resolucion = resol_in
        cfg.inst_municipio = request.form.get("inst_municipio", cfg.inst_municipio or "").strip()
        cfg.inst_departamento = request.form.get("inst_departamento", cfg.inst_departamento or "").strip()
        cfg.hora_inicio_asistencia = request.form.get("hora_inicio_asistencia", cfg.hora_inicio_asistencia or "06:00").strip()
        cfg.hora_fin_asistencia_docente = request.form.get("hora_fin_asistencia_docente", cfg.hora_fin_asistencia_docente or "07:20").strip()
        cfg.contacto_soporte = request.form.get("contacto_soporte", cfg.contacto_soporte or "").strip()
        cfg.contacto_cartera = request.form.get("contacto_cartera", cfg.contacto_cartera or "").strip()
        if rol_actual() in ["Administrador", "Soporte"]:
            cfg.modo_mantenimiento = request.form.get("modo_mantenimiento") == "on"
            cfg.mensaje_mantenimiento = request.form.get("mensaje_mantenimiento", cfg.mensaje_mantenimiento)

        # Cambio de logo institucional
        logo_file = request.files.get("logo")
        if logo_file and logo_file.filename:
            nueva = guardar_logo_institucional(logo_file, inst.id if inst else None)
            if nueva:
                cfg.logo_path = nueva
                if inst:
                    inst.logo = nueva
            else:
                mensaje = "El logo debe ser PNG, JPG, JPEG, WEBP o GIF."

        if inst and not mensaje:
            inst.nombre = cfg.inst_nombre
            inst.sede = cfg.inst_sede
            inst.dane = cfg.inst_dane
            inst.nit = cfg.inst_nit
            inst.direccion = cfg.inst_direccion
            inst.resolucion = cfg.inst_resolucion
            inst.municipio = cfg.inst_municipio
            inst.departamento = cfg.inst_departamento

        if not mensaje:
            db.session.commit()
            sincronizar_inst_globals(cfg)
            registrar_auditoria(
                "Configuración institucional",
                f"Actualizó datos institucionales / periodo {cfg.periodo_actual} / jornada {cfg.jornada} / logo {cfg.logo_path or ''}"
            )
            mensaje = "Configuración guardada correctamente. Los cambios (incluido el logo) aplican de inmediato."
        else:
            db.session.rollback()

    mantenimiento = ""
    if rol_actual() in ["Administrador", "Soporte"]:
        mantenimiento = f"""
        <div class='student-section-title'>Mantenimiento</div>
        <label><input type='checkbox' name='modo_mantenimiento' style='width:auto' {'checked' if cfg.modo_mantenimiento else ''}> Activar modo mantenimiento</label>
        <input name='mensaje_mantenimiento' value='{(cfg.mensaje_mantenimiento or "").replace(chr(39), "")}' placeholder='Mensaje de mantenimiento'>
        """
    logo_url = logo_actual()
    content = f"""
<header class='role-hero'>
  <div>
    <h1>Configuración institucional</h1>
    <p>Edita nombre del colegio, logo, sede, DANE, NIT, periodos y horarios <b>desde la aplicación</b>. No necesitas tocar código ni VS Code.</p>
  </div>
  <a class='btn' href='/dashboard'>Volver</a>
</header>
{'<div class="msg ok">'+mensaje+'</div>' if mensaje and 'correctamente' in mensaje else ''}
{'<div class="msg danger">'+mensaje+'</div>' if mensaje and 'correctamente' not in mensaje else ''}
<section class='role-panel'>
<form method='POST' enctype='multipart/form-data'>
  <div class='student-section-title'>Logo institucional</div>
  <div style='display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin-bottom:16px'>
    <img src='{logo_url}' alt='Logo actual' style='width:110px;height:110px;object-fit:contain;background:#fff;border-radius:18px;padding:8px;border:1px solid #dbe3f0'>
    <div style='flex:1;min-width:220px'>
      <label><b>Cambiar logo</b></label>
      <input type='file' name='logo' accept='image/png,image/jpeg,image/jpg,image/webp,image/gif'>
      <p class='field-help' style='margin:8px 0 0;color:#64748b;font-size:13px'>PNG, JPG o WEBP. Se muestra en el menú lateral, login y documentos. En Railway el archivo se guarda en el servidor; para producción permanente se recomienda almacenamiento externo si el disco es efímero.</p>
    </div>
  </div>

  <div class='student-section-title'>Datos de la institución</div>
  <div class='form-row'>
    <div><label><b>Nombre institucional</b></label><input name='inst_nombre' value='{(cfg.inst_nombre or "").replace(chr(39), "")}' required></div>
    <div><label><b>Sede</b></label><input name='inst_sede' value='{(cfg.inst_sede or "").replace(chr(39), "")}'></div>
  </div>
  <div class='form-row'>
    <div><label><b>DANE</b></label><input name='inst_dane' value='{(cfg.inst_dane or "").replace(chr(39), "")}'></div>
    <div><label><b>NIT</b></label><input name='inst_nit' value='{(cfg.inst_nit or "").replace(chr(39), "")}'></div>
  </div>
  <label><b>Dirección</b></label>
  <input name='inst_direccion' value='{(cfg.inst_direccion or "").replace(chr(39), "")}'>
  <div class='form-row'>
    <div><label><b>Municipio</b></label><input name='inst_municipio' value='{(cfg.inst_municipio or "").replace(chr(39), "")}'></div>
    <div><label><b>Departamento</b></label><input name='inst_departamento' value='{(cfg.inst_departamento or "").replace(chr(39), "")}'></div>
  </div>
  <label><b>Resolución / acto administrativo</b></label>
  <input name='inst_resolucion' value='{(cfg.inst_resolucion or "").replace(chr(39), "")}'>

  <div class='student-section-title'>Periodo académico y jornada</div>
  <div class='form-row'>
    <div>
      <label><b>Periodo actual</b></label>
      <select name='periodo_actual'>
        <option {'selected' if periodo_actual()=='Periodo 1' else ''}>Periodo 1</option>
        <option {'selected' if periodo_actual()=='Periodo 2' else ''}>Periodo 2</option>
        <option {'selected' if periodo_actual()=='Periodo 3' else ''}>Periodo 3</option>
      </select>
    </div>
    <div>
      <label><b>Jornada</b></label>
      <select name='jornada'>
        <option {'selected' if jornada_actual()=='Mañana' else ''}>Mañana</option>
        <option {'selected' if jornada_actual()=='Tarde' else ''}>Tarde</option>
        <option {'selected' if jornada_actual()=='Única' else ''}>Única</option>
      </select>
    </div>
  </div>
  <div class='form-row'>
    <div><label><b>Hora inicio asistencia</b></label><input name='hora_inicio_asistencia' value='{(cfg.hora_inicio_asistencia or "06:00")}' placeholder='06:00'></div>
    <div><label><b>Hora fin asistencia docente</b></label><input name='hora_fin_asistencia_docente' value='{(cfg.hora_fin_asistencia_docente or "07:20")}' placeholder='07:20'></div>
  </div>

  <div class='student-section-title'>Contactos</div>
  <div class='form-row'>
    <div><label><b>Contacto soporte</b></label><input name='contacto_soporte' value='{(cfg.contacto_soporte or "").replace(chr(39), "")}'></div>
    <div><label><b>Contacto cartera</b></label><input name='contacto_cartera' value='{(cfg.contacto_cartera or "").replace(chr(39), "")}'></div>
  </div>
  {mantenimiento}
  <br>
  <button>Guardar configuración</button>
</form>
</section>
<div class='security-note'>Tenant actual: <b>{inst.codigo if inst else "N/A"}</b> · ID {inst.id if inst else "-"} · Estado {inst.estado if inst else "-"} · Logo: {logo_url}</div>
"""
    return page("Configuración", shell(content))


