@app.route("/auditoria", methods=["GET", "POST"])
def auditoria():
    if not requiere_login(): return redirect("/login")
    if not puede_auditoria(): return acceso_denegado()
    mensaje = ""
    if request.method == "POST":
        if rol_actual() != "Soporte":
            return acceso_denegado("Solo Soporte puede gestionar auditoría (requiere código).")
        codigo = request.form.get("codigo_seguridad", "")
        if verificar_codigo_auditoria(codigo):
            Auditoria.query.delete()
            db.session.commit()
            registrar_auditoria("Limpieza auditoría", "Soporte limpió el historial de auditoría con código de seguridad")
            mensaje = "Auditoría limpiada correctamente."
        else:
            registrar_auditoria("Intento limpieza auditoría", "Código de seguridad incorrecto")
            mensaje = "Código de seguridad incorrecto."
    q = request.args.get("q") or ""
    eventos_q = Auditoria.query.order_by(Auditoria.id.desc())
    # Un asesor de Soporte/Ventas no debe ver qué hizo OTRO asesor — cada quien ve solo lo suyo.
    # Gerencia/Administrador/Superadmin sí ven todo, para poder supervisar.
    if rol_actual() == "Soporte":
        eventos_q = eventos_q.filter(Auditoria.usuario == session.get("usuario"))
    if q:
        like = f"%{q}%"
        eventos_q = eventos_q.filter(
            db.or_(
                Auditoria.usuario.ilike(like),
                Auditoria.accion.ilike(like),
                Auditoria.ip.ilike(like),
                Auditoria.ubicacion.ilike(like),
                Auditoria.detalle.ilike(like),
            )
        )
    eventos = eventos_q.limit(400).all()
    filas = ""
    for a in eventos:
        ua_short = (getattr(a, "user_agent", None) or "")[:80]
        filas += f"""<tr class='audit-row'>
          <td>{a.fecha}<br><span class='mini-text'>{a.hora}</span></td>
          <td><b>{a.usuario}</b><br><span class='mini-text'>{a.rol}</span></td>
          <td><b>{a.accion}</b><br><span class='mini-text'>{(a.detalle or '')[:120]}</span></td>
          <td><code>{a.ip or '—'}</code></td>
          <td>{getattr(a, 'ubicacion', None) or '—'}</td>
          <td>{getattr(a, 'dispositivo', None) or '—'} · {getattr(a, 'navegador', None) or '—'} · {getattr(a, 'sistema_os', None) or '—'}</td>
          <td><span class='mini-text' title='{ua_short.replace(chr(39), "")}'>{getattr(a, 'ruta', None) or '—'}</span></td>
        </tr>"""
    limpiar = ""
    if rol_actual() == "Soporte":
        limpiar = """<section class='role-panel'><h2>Limpiar auditoría</h2><p class='role-muted'>Solo Soporte con código. La limpieza también queda registrada.</p><form method='POST'><input name='codigo_seguridad' type='password' placeholder='Código secreto de auditoría' required><button class='btn-red'>Eliminar auditoría</button></form></section><br>"""
    content = f"""
<header class='role-hero'>
  <div>
    <h1>Auditoría de seguridad</h1>
    <p>Registro preciso: <b>quién</b>, <b>qué</b>, <b>cuándo</b>, <b>IP</b>, <b>ubicación aprox.</b>, <b>dispositivo</b> y <b>ruta</b>.</p>
  </div>
  <a class='btn' href='/dashboard'>Volver</a>
</header>
{'<div class="msg ok">'+mensaje+'</div>' if mensaje and 'correctamente' in mensaje else ''}
{'<div class="msg danger">'+mensaje+'</div>' if mensaje and 'incorrecto' in mensaje else ''}
<section class='role-panel' style='margin-bottom:12px'>
  <form method='GET' style='display:flex;gap:8px;flex-wrap:wrap;align-items:end'>
    <div style='flex:1;min-width:200px'>
      <label><b>Buscar</b></label>
      <input name='q' value='{q.replace(chr(39), "")}' placeholder='Usuario, IP, ciudad, acción…'>
    </div>
    <button>Filtrar</button>
  </form>
  <p class='mini-text' style='margin-top:8px'>La ubicación es <b>aproximada por IP</b> (no GPS del dispositivo). En redes locales verá “Red local / privada”.</p>
</section>
{limpiar}
<div class='table-card' style='overflow:auto'>
<table>
<tr>
  <th>Fecha / hora</th><th>Usuario</th><th>Acción</th>
  <th>IP</th><th>Ubicación</th><th>Equipo</th><th>Ruta</th>
</tr>
{filas if filas else "<tr><td colspan='7'>Sin eventos</td></tr>"}
</table>
</div>"""
    return page("Auditoría", shell(content))


@app.route("/backup")
@app.route("/backup_datos")
def backup():
    """Respaldo Excel de protección de datos (Secretaría / dirección / Soporte)."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ("Secretaría", "Rectoría", "Coordinación", "Administrador", "Soporte"):
        return acceso_denegado("Solo Secretaría, dirección o Soporte pueden descargar respaldos.")
    # Página informativa si GET sin ?dl=1
    if request.args.get("dl") != "1" and request.path.endswith("backup_datos"):
        cfg = config()
        last = getattr(cfg, "last_backup", None) or "Nunca"
        aviso = ""
        try:
            from datetime import datetime as _dt
            if last and last != "Nunca":
                dias = (_dt.strptime(fecha_hoy(), "%Y-%m-%d") - _dt.strptime(last[:10], "%Y-%m-%d")).days
                if dias >= 15:
                    aviso = f'<div class="msg danger">Han pasado <b>{dias} días</b> desde el último respaldo. Descargue una copia ahora.</div>'
                else:
                    aviso = f'<div class="msg ok">Último respaldo hace {dias} día(s). Recomendado cada 15 días.</div>'
            else:
                aviso = '<div class="msg warn">Aún no hay respaldo registrado. Descargue la primera copia de seguridad.</div>'
        except Exception:
            pass
        content = f"""
<header class="role-hero"><div>
  <h1>Respaldo y protección de datos</h1>
  <p>Habeas data · Copia de seguridad del colegio · Cada 15 días</p>
</div></header>
{aviso}
<section class="role-panel">
  <p>Para proteger la información ante caídas del servidor, borrados accidentales o cambios de equipo,
  descargue periódicamente un archivo Excel con <b>estudiantes (SIMAT)</b>, ingresos y usuarios del colegio.</p>
  <ul>
    <li>Último respaldo registrado: <b>{last}</b></li>
    <li>Frecuencia recomendada: <b>cada 15 días</b></li>
    <li>Guarde el archivo en un disco seguro del colegio (no solo en este computador).</li>
  </ul>
  <p><a class="btn btn-green" href="/backup?dl=1">Descargar respaldo ahora (.xlsx)</a></p>
  <p class="mini-text">El sistema registra la fecha al descargar para recordarle el próximo ciclo de 15 días.</p>
</section>
"""
        return page("Respaldo", shell(content))

