@app.route("/importar_estudiantes", methods=["GET", "POST"])
def importar_estudiantes():
    if not requiere_login(): return redirect("/login")
    if not puede_estudiantes(): return acceso_denegado()
    mensaje = ""
    if request.method == "POST":
        archivo = request.files.get("archivo")
        if not archivo or not archivo.filename.lower().endswith(".xlsx"):
            mensaje = "Sube un archivo Excel .xlsx válido."
        else:
            wb = load_workbook(archivo, data_only=True)
            ws = wb.active
            headers = [str(c.value or "").strip().lower() for c in ws[1]]
            def val(row, names):
                for name in names:
                    if name in headers:
                        v = row[headers.index(name)].value
                        return str(v).strip() if v is not None else ""
                return ""
            creados = actualizados = saltados = 0
            for row in ws.iter_rows(min_row=2):
                codigo = val(row, ["codigo", "código", "cod"])
                if not codigo:
                    saltados += 1; continue
                e = Estudiante.query.filter_by(codigo=codigo).first()
                iid_imp = institucion_id_actual()
                if not e:
                    e = Estudiante(codigo=codigo, institucion_id=iid_imp)
                    db.session.add(e); creados += 1
                else:
                    # Solo actualizar si es del mismo colegio o está sin colegio
                    if iid_imp is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid_imp):
                        saltados += 1
                        continue
                    e.institucion_id = iid_imp or e.institucion_id
                    actualizados += 1
                # Nombres: columnas simples o SIMAT (nombre1/apellido1)
                a1 = val(row, ["apellido1", "primer apellido", "primer_apellido"])
                a2 = val(row, ["apellido2", "segundo apellido", "segundo_apellido"])
                n1 = val(row, ["nombre1", "primer nombre", "primer_nombre"])
                n2 = val(row, ["nombre2", "segundo nombre", "segundo_nombre"])
                nombre = val(row, ["nombre", "nombres"])
                apellido = val(row, ["apellido", "apellidos"])
                if a1 or n1:
                    e.apellido1 = (a1 or "")[:80]
                    e.apellido2 = (a2 or "")[:80]
                    e.nombre1 = (n1 or "")[:80]
                    e.nombre2 = (n2 or "")[:80]
                    e.apellido = f"{a1} {a2}".strip()[:120] or apellido or "Sin apellido"
                    e.nombre = f"{n1} {n2}".strip()[:120] or nombre or "Sin nombre"
                else:
                    e.nombre = nombre or e.nombre or "Sin nombre"
                    e.apellido = apellido or e.apellido or "Sin apellido"
                    # rellenar desglose básico
                    parts_n = (e.nombre or "").split()
                    parts_a = (e.apellido or "").split()
                    e.nombre1 = (parts_n[0] if parts_n else "")[:80]
                    e.nombre2 = (" ".join(parts_n[1:]) if len(parts_n) > 1 else "")[:80]
                    e.apellido1 = (parts_a[0] if parts_a else "")[:80]
                    e.apellido2 = (" ".join(parts_a[1:]) if len(parts_a) > 1 else "")[:80]
                e.grado = val(row, ["grado"]) or e.grado or "11"
                e.grupo = val(row, ["grupo"]) or getattr(e, "grupo", "") or ""
                e.director = val(row, ["director", "director de grupo"]) or e.director or "Sin asignar"
                e.tipo_doc = val(row, ["tipo_doc", "tipo documento", "tipodoc"]) or getattr(e, "tipo_doc", None) or "TI"
                e.documento = val(row, ["documento", "nro_doc", "dni", "tarjeta", "ti"]) or e.documento
                e.exp_depa = val(row, ["exp_depa", "depto expedicion", "departamento expedicion"]) or getattr(e, "exp_depa", "") or ""
                e.exp_muni = val(row, ["exp_muni", "mpio expedicion", "municipio expedicion"]) or getattr(e, "exp_muni", "") or ""
                e.fecha_nacimiento = val(row, ["fecha_nacimiento", "fecha nac", "nacimiento"]) or getattr(e, "fecha_nacimiento", "") or ""
                e.genero = val(row, ["genero", "sexo"]) or getattr(e, "genero", "") or ""
                e.rh = val(row, ["rh", "sangre"]) or e.rh
                e.direccion = val(row, ["direccion", "dirección"]) or e.direccion
                e.barrio = val(row, ["barrio"]) or getattr(e, "barrio", "") or ""
                e.estrato = val(row, ["estrato"]) or getattr(e, "estrato", "") or ""
                e.zona = val(row, ["zona"]) or getattr(e, "zona", "") or ""
                e.mun_res = val(row, ["mun_res", "municipio", "municipio residencia"]) or getattr(e, "mun_res", "") or ""
                e.dep_res = val(row, ["dep_res", "departamento", "departamento residencia"]) or getattr(e, "dep_res", "") or ""
                e.sisben_grupo = val(row, ["sisben_grupo", "sisben"]) or getattr(e, "sisben_grupo", "") or ""
                e.discapacidad = val(row, ["discapacidad"]) or getattr(e, "discapacidad", "") or ""
                e.capacidad_excep = val(row, ["capacidad_excep", "capacidades"]) or getattr(e, "capacidad_excep", "") or ""
                e.victima = val(row, ["victima"]) or getattr(e, "victima", "") or ""
                e.etnia = val(row, ["etnia"]) or getattr(e, "etnia", "") or ""
                e.eps = val(row, ["eps"]) or getattr(e, "eps", "") or ""
                e.acudiente = val(row, ["acudiente", "acudiente principal"]) or e.acudiente
                e.acudiente_doc = val(row, ["acudiente_doc", "doc acudiente"]) or getattr(e, "acudiente_doc", "") or ""
                e.padre = val(row, ["padre"]) or e.padre
                e.madre = val(row, ["madre"]) or e.madre
                e.telefono_acudiente = val(row, ["telefono_acudiente", "telefono", "teléfono", "telefono acudiente", "teléfono acudiente", "celular"]) or e.telefono_acudiente
                e.correo_acudiente = val(row, ["correo_acudiente", "correo", "email", "correo acudiente"]) or e.correo_acudiente
                e.jornada = val(row, ["jornada"]) or getattr(e, "jornada", "") or ""
                e.sede = val(row, ["sede"]) or getattr(e, "sede", "") or ""
                e.observacion = val(row, ["observacion", "observación"]) or e.observacion
                est = val(row, ["estado"])
                if est:
                    e.estado = est[:30]
            db.session.commit()
            registrar_auditoria("Importar estudiantes Excel", f"Creados {creados}, actualizados {actualizados}, saltados {saltados}")
            mensaje = f"Importación terminada. Creados: {creados}. Actualizados: {actualizados}. Saltados: {saltados}."
    content = f"""
<header class='role-hero'><div><h1>Importar estudiantes desde Excel</h1><p>Sube estudiantes por grupo sin registrarlos uno por uno.</p></div><a class='btn' href='/estudiantes'>Volver</a></header>
<div class='role-panel'>
  {'<div class="msg ok">'+mensaje+'</div>' if mensaje and 'terminada' in mensaje else ''}
  {'<div class="msg danger">'+mensaje+'</div>' if mensaje and 'terminada' not in mensaje else ''}
  <form method='POST' enctype='multipart/form-data'>
    <input type='file' name='archivo' accept='.xlsx' required>
    <button>Subir e importar</button>
  </form>
  <div class='security-note'>Columnas aceptadas: codigo, nombre, apellido, documento, grado, director, rh, acudiente, padre, madre, telefono, correo, direccion, observacion.</div>
  <p style="margin-top:12px"><a class="btn" href="/migracion-historica">Migración histórica Sinaí / Coaweb</a></p>
</div>
"""
    return page("Importar Excel", shell(content))


@app.route("/migracion-historica", methods=["GET", "POST"])
def migracion_historica():
    """Migración de estudiantes y notas históricas desde Sinaí, Coaweb u otros (Excel/CSV)."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Administrador", "Rectoría", "Secretaría", "Soporte", "Coordinación"]:
        return acceso_denegado()
    mensaje = error = ""
    iid = institucion_id_actual()
    if request.method == "POST":
        origen = (request.form.get("origen") or "OTRO").strip()
        tipo = (request.form.get("tipo") or "estudiantes").strip()
        archivo = request.files.get("archivo")
        if not archivo or not archivo.filename:
            error = "Suba un archivo .xlsx o .csv"
        else:
            fname = archivo.filename.lower()
            try:
                if fname.endswith(".csv"):
                    import csv, io
                    text = archivo.read().decode("utf-8-sig", errors="replace")
                    reader = csv.DictReader(io.StringIO(text))
                    rows = []
                    for row in reader:
                        rows.append({(k or "").strip().lower(): ("" if v is None else str(v).strip()) for k, v in row.items()})
                elif fname.endswith(".xlsx"):
                    wb = load_workbook(archivo, data_only=True)
                    ws = wb.active
                    headers = [str(c.value or "").strip().lower() for c in ws[1]]
                    rows = []
                    for row in ws.iter_rows(min_row=2, values_only=True):
                        d = {}
                        for i, h in enumerate(headers):
                            if i < len(row):
                                d[h] = "" if row[i] is None else str(row[i]).strip()
                        rows.append(d)
                else:
                    error = "Use Excel .xlsx o CSV."
                    rows = []

                def gv(r, names):
                    for n in names:
                        if n.lower() in r and r[n.lower()]:
                            return str(r[n.lower()]).strip()
                    return ""

                if not error and tipo == "estudiantes":
                    creados = actualizados = saltados = 0
                    for r in rows:
                        codigo = gv(r, ["codigo", "código", "cod", "codigo_estudiante", "id_estudiante"])
                        if not codigo:
                            saltados += 1
                            continue
                        e = None
                        if iid:
                            e = Estudiante.query.filter_by(codigo=codigo, institucion_id=iid).first()
                        if not e:
                            e = Estudiante.query.filter_by(codigo=codigo).first()
                        if not e:
                            e = Estudiante(codigo=codigo[:80], institucion_id=iid)
                            db.session.add(e)
                            creados += 1
                        else:
                            if iid and e.institucion_id and int(e.institucion_id) != int(iid):
                                saltados += 1
                                continue
                            e.institucion_id = iid or e.institucion_id
                            actualizados += 1
                        e.nombre = (gv(r, ["nombre", "nombres", "primer_nombre"]) or e.nombre or "Sin nombre")[:120]
                        e.apellido = (gv(r, ["apellido", "apellidos", "primer_apellido"]) or e.apellido or "Sin apellido")[:120]
                        e.grado = (gv(r, ["grado", "curso", "grupo"]) or e.grado or "1")[:30]
                        e.director = (gv(r, ["director", "director_grupo", "docente"]) or e.director or "Por asignar")[:120]
                        e.documento = (gv(r, ["documento", "doc", "identificacion", "cedula"]) or e.documento or "")[:80]
                        e.acudiente = (gv(r, ["acudiente", "padre", "madre", "responsable"]) or e.acudiente or "")[:160]
                        e.telefono_acudiente = (gv(r, ["telefono", "teléfono", "celular", "telefono_acudiente"]) or e.telefono_acudiente or "")[:80]
                        e.correo_acudiente = (gv(r, ["correo", "email", "correo_acudiente"]) or e.correo_acudiente or "")[:160]
                        e.direccion = (gv(r, ["direccion", "dirección", "dir"]) or e.direccion or "")[:220]
                        e.dep_res = (gv(r, ["departamento", "dep_res", "depto"]) or e.dep_res or "")[:80]
                        e.mun_res = (gv(r, ["municipio", "mun_res", "ciudad"]) or e.mun_res or "")[:80]
                    db.session.commit()
                    mensaje = f"Migración {origen} (estudiantes): creados {creados}, actualizados {actualizados}, saltados {saltados}."
                    registrar_auditoria("Migración histórica", f"{origen} est c={creados} a={actualizados}")

                elif not error and tipo == "notas":
                    importadas = sin_est = 0
                    for r in rows:
                        codigo = gv(r, ["codigo", "código", "codigo_estudiante", "estudiante"])
                        materia = gv(r, ["materia", "asignatura", "area", "área"])
                        periodo = gv(r, ["periodo", "period", "bimestre"]) or periodo_actual()
                        nota_s = gv(r, ["nota", "valor", "calificacion", "calificación", "definitiva"])
                        if not codigo or not materia:
                            continue
                        e = Estudiante.query.filter_by(codigo=codigo, institucion_id=iid).first() if iid else Estudiante.query.filter_by(codigo=codigo).first()
                        if not e:
                            sin_est += 1
                            continue
                        try:
                            nota_v = float(str(nota_s).replace(",", "."))
                        except Exception:
                            continue
                        try:
                            db.session.add(AnotacionEstudiante(
                                estudiante_id=e.id,
                                institucion_id=iid,
                                tipo="OBSERVACIÓN",
                                descripcion=f"[Migración {origen}] {materia} · {periodo}: {nota_v}",
                                registrado_por=session.get("usuario") or "migracion",
                                fecha=fecha_hoy(),
                            ))
                            importadas += 1
                        except Exception:
                            e.observacion = ((e.observacion or "") + f"\n[{origen}] {materia} {periodo}={nota_v}")[:2000]
                            importadas += 1
                    try:
                        db.session.commit()
                        mensaje = f"Migración {origen} (notas): {importadas} registros. Sin estudiante: {sin_est}."
                        registrar_auditoria("Migración notas", f"{origen} n={importadas}")
                    except Exception as ex:
                        db.session.rollback()
                        error = f"Error al guardar: {ex}"
            except Exception as ex:
                error = f"Error leyendo archivo: {ex}"

    content = f"""
<style>
.mh{{max-width:820px;margin:0 auto;font-family:Segoe UI,system-ui,sans-serif}}
.mh .box{{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin-bottom:14px}}
.mh h1{{color:#0B2D57;margin:0 0 8px}}
.mh label{{display:block;font-weight:700;font-size:12px;margin:8px 0 4px}}
.mh select,.mh input{{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:10px;box-sizing:border-box}}
.mh .ok{{background:#ecfdf5;color:#065f46;padding:10px;border-radius:10px;margin-bottom:10px}}
.mh .err{{background:#fef2f2;color:#991b1b;padding:10px;border-radius:10px;margin-bottom:10px}}
.mh .tip{{background:#eff6ff;border-left:4px solid #1e40af;padding:12px;font-size:13px;color:#1e3a8a;line-height:1.5;margin-bottom:14px}}
</style>
<div class="mh">
  <h1>Migración de datos históricos</h1>
  <p style="color:#64748b;font-size:14px">Traslado desde <b>Sinaí</b>, <b>Coaweb</b> u otros sistemas a EduTrack, sin perder registros de matrícula y notas.</p>
  <div class="tip">
    <b>Preparación</b><br>
    1. Exporte desde el sistema anterior a Excel o CSV.<br>
    2. <b>Estudiantes:</b> codigo, nombre, apellido, grado, documento, acudiente, telefono, correo, direccion, departamento, municipio.<br>
    3. <b>Notas:</b> codigo, materia, periodo, nota (importe primero estudiantes).<br>
    4. Coincidencias por <b>código</b>: se actualizan; los nuevos se crean.
  </div>
  {"<div class='ok'>"+mensaje+"</div>" if mensaje else ""}
  {"<div class='err'>"+error+"</div>" if error else ""}
  <div class="box">
    <form method="POST" enctype="multipart/form-data">
      <label>Sistema de origen</label>
      <select name="origen"><option>Sinaí</option><option>Coaweb</option><option>SIMAT</option><option>Excel propio</option><option>OTRO</option></select>
      <label>Tipo de carga</label>
      <select name="tipo"><option value="estudiantes">Estudiantes / base</option><option value="notas">Notas históricas</option></select>
      <label>Archivo (.xlsx o .csv)</label>
      <input type="file" name="archivo" accept=".xlsx,.csv" required>
      <button style="margin-top:12px;background:#0B2D57;color:#fff;border:0;padding:12px 18px;border-radius:10px;font-weight:800;cursor:pointer">Migrar a EduTrack</button>
    </form>
  </div>
  <p style="font-size:13px"><a href="/importar_estudiantes">Importación Excel</a> · <a href="/exportar_estudiantes">Exportar respaldo</a></p>
</div>
"""
    return page("Migración histórica", shell(content))


