@app.before_request
def _aislar_paneles_internos():
    """Cada rol interno SOLO opera en su portal. Atrás del navegador no salta a otro panel."""
    path = request.path or ""
    if path.startswith("/static") or path.startswith("/api/webhooks"):
        return None
    # Login y panel de desarrollo: no mezclar con login de colegios
    if path in ("/dev-console-login",) or (path.startswith("/dev-console") and not session.get("usuario")):
        if path.startswith("/dev-console") and path != "/dev-console-login" and not session.get("usuario"):
            return redirect("/dev-console-login")
        return None

    # Páginas de login de portales: limpiar sesión ajena y no mezclar
    login_map = {
        "/ventas-login": "Comercial",
        "/soporte-login": "Soporte",
        "/gerencia-login": ("Gerente", "Superadmin", "Administrador"),
        "/cobranza-login": "Cobranza",
        "/dev-console-login": ("Desarrollador", "Developer", "Superadmin"),
    }
    if path in login_map and request.method == "GET":
        rol = (session.get("rol") or "").strip()
        esperado = login_map[path]
        ok = rol in esperado if isinstance(esperado, tuple) else (rol == esperado)
        if session.get("usuario") and not ok:
            # Había otra sesión (otro portal): cerrar para no cruzar
            session.clear()
        elif session.get("usuario") and ok:
            return redirect(_home_portal(rol))
        return None

    if path == "/login" and request.method == "GET":
        # Login de colegios: se muestra siempre el formulario, incluso si hay una sesión
        # de staff abierta en otra pestaña del mismo navegador (las cookies de sesión son
        # por navegador, no por pestaña). Si el usuario efectivamente inicia sesión aquí
        # como colegio, la ruta /login se encarga de reemplazar la sesión.
        return None

    if not session.get("usuario"):
        return None

    rol = (session.get("rol") or "").strip()
    if rol not in ROLES_INTERNOS and rol != "Soporte":
        return None

    # Rutas siempre permitidas para staff
    if path in ("/logout", "/mi-perfil", "/cambiar_password", "/mfa", "/backoffice", "/edutrack-backoffice", "/backoffice/login", "/backoffice/hub") or path.startswith("/biometria"):
        return None
    if path.startswith("/api/interno") or path.startswith("/backoffice"):
        return None

    home = _home_portal(rol)

    def _login_del_portal(p):
        """Login único staff: siempre /backoffice."""
        return "/backoffice"
        if p.startswith("/gerencia"):
            return "/backoffice"
        if p.startswith("/soporte_admin") or p.startswith("/soporte"):
            return "/backoffice"
        if p.startswith("/ventas"):
            return "/backoffice"
        if p.startswith("/cobranza"):
            return "/backoffice"
        if p.startswith("/dev-console"):
            return "/dev-console-login"
        return home

    # Rutas de colegio: staff no debe entrar al dashboard escolar
    if path in ("/dashboard", "/estudiantes", "/reportes", "/usuarios") or path.startswith("/familia"):
        # /usuarios lo usa soporte: permitir solo Soporte/Gerente
        if path.startswith("/usuarios") and rol in ("Soporte", "Gerente", "Superadmin", "Administrador"):
            return None
        if path in ("/dashboard", "/estudiantes", "/reportes") or path.startswith("/familia"):
            return redirect(home)

    # —— Aislamiento estricto por rol ——
    if rol == "Comercial":
        permitido = (
            path.startswith("/ventas/panel")
            or path.startswith("/ventas/comisiones")
            or path.startswith("/ventas/kit")
            or path.startswith("/ventas/crm")
            or path.startswith("/ventas/demos")
            or path.startswith("/ventas/notas")
            or path.startswith("/ventas/contrato")
            or path.startswith("/ventas/propuesta")
            or path.startswith("/ventas/comprar")
            or path.startswith("/ventas/fidelizacion")
            or path.startswith("/ventas/verificacion")
            or path.startswith("/api/ventas")
            or path == "/ventas"
            or path.startswith("/interno/buscar")
            or path.startswith("/notas-cliente")
        )
        if not permitido and (path.startswith("/gerencia") or path.startswith("/soporte")
                              or path.startswith("/cobranza") or path.startswith("/soporte_admin")
                              or path.startswith("/tenants")):
            return redirect(_login_del_portal(path))
        if path.startswith("/gerencia") or path.startswith("/soporte_admin") or path.startswith("/cobranza"):
            return redirect(_login_del_portal(path))

    elif rol == "Soporte":
        if (path.startswith("/ventas/panel") or path.startswith("/ventas/comisiones")
                or path.startswith("/cobranza") or path.startswith("/gerencia/")
                or path == "/gerencia" or path == "/gerencia/hq"):
            return redirect(_login_del_portal(path))

    elif rol == "Cobranza":
        ok_cob = (
            path.startswith("/cobranza")
            or path.startswith("/gerencia/facturacion")
            or path.startswith("/gerencia/plazos-cuotas")
            or path.startswith("/interno/buscar")
            or path.startswith("/interno/turnos")
            or path.startswith("/cobranza/turnos")
            or path.startswith("/tenants")
            or path.startswith("/mi-perfil")
            or path.startswith("/cambiar_password")
            or path.startswith("/abrir-turno")
            or path.startswith("/cerrar-turno")
            or path.startswith("/soporte/reinicio-acceso")
            or path.startswith("/cobranza/conciliacion")
        )
        # Cobranza NUNCA debe caer en portal de soporte por error de ruta
        if path.startswith("/soporte") and not path.startswith("/soporte/reinicio-acceso"):
            return redirect("/cobranza/panel")
        if path.startswith("/soporte_admin") or path.startswith("/ventas"):
            return redirect("/cobranza/panel")
        if path.startswith("/gerencia/") and not path.startswith("/gerencia/facturacion"):
            return redirect("/cobranza/panel")
        if not ok_cob and (path.startswith("/gerencia") or path.startswith("/usuarios")):
            return redirect("/cobranza/panel")

    elif rol in ("Desarrollador", "Developer"):
        ok_dev = (
            path.startswith("/dev-console")
            or path == "/backoffice"
            or path.startswith("/backoffice/")
            or path.startswith("/logout")
            or path.startswith("/mi-perfil")
            or path.startswith("/cambiar_password")
            or path.startswith("/gerencia/planes/nuevo")
            or path.startswith("/static")
        )
        if not ok_dev:
            return redirect("/dev-console")

    elif rol in ("Gerente", "Superadmin", "Administrador"):
        # Superadmin puede usar consola de desarrollo
        if rol == "Superadmin" and path.startswith("/dev-console"):
            return None
        if path.startswith("/ventas/panel") or path.startswith("/ventas/comisiones"):
            return redirect(_login_del_portal(path))
        if path.startswith("/cobranza/panel") or path == "/cobranza":
            return redirect("/gerencia/facturacion-cobranza")

    # Headers anti-caché en portales internos (botón atrás no reusa página de otro rol)
    return None



@app.before_request
def _bloquear_auditoria_boletines_soporte():
    """Auditoría y boletines no son de Soporte: solo Gerencia."""
    try:
        if not session.get("usuario"):
            return None
        rol = (session.get("rol") or "").strip()
        if rol != "Soporte":
            return None
        p = request.path or ""
        if p.startswith("/auditoria") or p.startswith("/soporte/boletines") or p.startswith("/gerencia/auditoria"):
            return acceso_denegado("Auditoría y boletines son exclusivos de Gerencia. Soporte no tiene acceso a este módulo.")
    except Exception:
        return None

@app.after_request
def _no_cache_portales_internos(resp):
    try:
        path = request.path or ""
        if any(path.startswith(p) for p in (
            "/ventas/panel", "/ventas/comisiones", "/soporte", "/soporte_admin",
            "/gerencia", "/cobranza", "/interno/",
        )):
            resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, private"
            resp.headers["Pragma"] = "no-cache"
            resp.headers["Expires"] = "0"
    except Exception:
        pass
    return resp

def requiere_gerencia():
    if not requiere_login():
        return False
    return rol_actual() in ["Gerente", "Superadmin", "Administrador"]


