@app.route("/media/login-banner/<int:bid>")
def media_login_banner(bid):
    """Sirve imagen de banner del login backoffice (data URI o URL)."""
    try:
        try:
            db.session.rollback()
        except Exception:
            pass
        row = db.session.execute(text(
            "SELECT url_imagen FROM login_banners WHERE id=:id LIMIT 1"
        ), {"id": bid}).first()
        if not row or not (row[0] or "").strip():
            return ("", 404)
        data = (row[0] or "").strip()
        if data.startswith("http://") or data.startswith("https://"):
            return redirect(data)
        if data.startswith("data:"):
            # data:image/png;base64,XXXX
            try:
                header, b64 = data.split(",", 1)
                mime = "image/jpeg"
                if "image/png" in header:
                    mime = "image/png"
                elif "image/webp" in header:
                    mime = "image/webp"
                elif "image/gif" in header:
                    mime = "image/gif"
                import base64 as _b64
                raw = _b64.b64decode(b64)
                from flask import Response
                resp = Response(raw, mimetype=mime)
                resp.headers["Cache-Control"] = "public, max-age=3600"
                return resp
            except Exception:
                return ("", 404)
        return ("", 404)
    except Exception:
        try:
            db.session.rollback()
        except Exception:
            pass
        return ("", 404)


