                ('<a href="' + _esc(c.pdf_path) + '" target="_blank" style="display:inline-block;margin-top:8px;'
                 'background:#005BEA;color:#fff;padding:8px 14px;border-radius:980px;font-size:12px;text-decoration:none">Descargar PDF</a>')
