@app.route("/retencion", methods=["GET", "POST"])
@app.route("/soporte/retencion", methods=["GET", "POST"])
@app.route("/ventas/retencion", methods=["GET", "POST"])
def modulo_retencion():
    """
    Retención: cancelaciones, baja de plan, descuentos.
    Ventas/Soporte solo solicitan (PENDIENTE / EN_VALIDACION).
    Solo Retención o Gerencia aprueba y ejecuta (bajar plan, descuento, cancelar).
    """
    if not requiere_login() or not _puede_notas_cliente():
        return redirect("/login")
    try:
        db.create_all()
    except Exception:
        pass
    msg = error = ""
    es_ejecutor = _es_retencion_o_gerencia()
    rol = (rol_actual() or "").strip()

    if request.method == "POST":
        accion = (request.form.get("accion") or "solicitar").strip()
        if accion == "solicitar":
            inst_id = request.form.get("institucion_id") or ""
            try:
                inst_id = int(inst_id) if inst_id else None
            except ValueError:
                inst_id = None
            tipo = (request.form.get("tipo") or "").strip()
            motivo = (request.form.get("motivo_filtro") or "").strip()
            detalle = (request.form.get("detalle") or "").strip()
            plan_sol = (request.form.get("plan_solicitado") or "").strip()
            try:
                desc_pct = float(request.form.get("descuento_pct") or 0)
            except Exception:
                desc_pct = 0.0
            try:
                desc_meses = int(request.form.get("descuento_meses") or 0)
            except Exception:
                desc_meses = 0
            if not tipo or not motivo or not detalle:
                error = "Tipo, motivo y detalle son obligatorios."
            elif not inst_id:
                error = "Seleccione el colegio."
            else:
                inst = Institucion.query.get(inst_id)
                plan_act = (inst.plan if inst else "") or ""
                # Ventas/Soporte: siempre pasan a validación si es BAJA_PLAN, DESCUENTO o CANCELACION
                if tipo in ("BAJA_PLAN", "DESCUENTO", "CANCELACION") and not es_ejecutor:
                    estado = "EN_VALIDACION"
                else:
                    estado = "PENDIENTE" if not es_ejecutor else "PENDIENTE"
                try:
                    ts = ahora().strftime("%Y-%m-%d %H:%M:%S")
                except Exception:
                    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                caso = CasoRetencion(
                    institucion_id=inst_id,
                    tipo=tipo[:40],
                    motivo_filtro=motivo[:80],
                    detalle=detalle[:4000],
                    plan_actual=plan_act[:40],
                    plan_solicitado=plan_sol[:40],
                    descuento_pct=desc_pct,
                    descuento_meses=desc_meses,
                    estado=estado,
                    solicitado_por=session.get("usuario") or "",
                    solicitado_rol=rol[:40],
                    creado_en=ts,
                    contacto_nombre=(request.form.get("contacto_nombre") or "")[:160],
                    telefono=(request.form.get("telefono") or "")[:40],
                )
                db.session.add(caso)
                db.session.commit()
                registrar_auditoria("Retención solicitud", f"caso={caso.id} tipo={tipo} inst={inst_id} estado={estado}")
                if estado == "EN_VALIDACION":
                    msg = f"Caso #{caso.id} enviado a validación de Retención/Gerencia. No se aplica hasta aprobación."
                else:
                    msg = f"Caso #{caso.id} registrado ({ts})."

        elif accion in ("aprobar", "rechazar", "ejecutar") and es_ejecutor:
            try:
                cid = int(request.form.get("caso_id") or 0)
            except Exception:
                cid = 0
            caso = CasoRetencion.query.get(cid) if cid else None
            nota_v = (request.form.get("nota_validacion") or "").strip()
            if not caso:
                error = "Caso no encontrado."
            else:
                try:
                    ts = ahora().strftime("%Y-%m-%d %H:%M:%S")
                except Exception:
                    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                if accion == "rechazar":
                    caso.estado = "RECHAZADO"
                    caso.validado_por = session.get("usuario") or ""
                    caso.validado_en = ts
                    caso.nota_validacion = nota_v
                    db.session.commit()
                    msg = f"Caso #{caso.id} rechazado."
                elif accion == "aprobar":
                    caso.estado = "APROBADO"
                    caso.validado_por = session.get("usuario") or ""
                    caso.validado_en = ts
                    caso.nota_validacion = nota_v
                    db.session.commit()
                    msg = f"Caso #{caso.id} aprobado. Use «Ejecutar» para aplicar en el sistema."
                elif accion == "ejecutar":
                    if caso.estado not in ("APROBADO", "PENDIENTE") and not es_ejecutor:
                        error = "Solo se ejecutan casos aprobados."
                    else:
                        inst = Institucion.query.get(caso.institucion_id) if caso.institucion_id else None
                        if not inst:
                            error = "Institución no encontrada."
                        else:
                            if caso.tipo == "CANCELACION":
                                # Misma lógica: cuenta regresiva + corte facturas + prorrateo
                                _activar_cancelacion_servicio(
                                    inst,
                                    motivo=caso.detalle or caso.motivo_filtro or "Retención",
                                    solicitado_por=session.get("usuario") or "Retencion",
                                    canal="RETENCION",
                                    dias_anticipacion=5,
                                )
                            elif caso.tipo == "BAJA_PLAN":
                                nuevo = (caso.plan_solicitado or "Basico").strip()
                                if nuevo in PLANES_EDUTRACK:
                                    # aplicar a fecha de corte si hay, si no inmediato (solo retención)
                                    inst.plan = nuevo
                                    inst.plan_pendiente = ""
                                    inst.fecha_corte_plan = ""
                            elif caso.tipo == "DESCUENTO":
                                # registrar en notas / config descuentos si existe
                                try:
                                    path = os.path.join(app.root_path, "config", "descuentos.json")
                                    data = []
                                    if os.path.isfile(path):
                                        with open(path, "r", encoding="utf-8") as f:
                                            data = json.load(f) or []
                                    data.append({
                                        "institucion_id": inst.id,
                                        "codigo": inst.codigo,
                                        "pct": caso.descuento_pct,
                                        "meses": caso.descuento_meses,
                                        "caso_id": caso.id,
                                        "por": session.get("usuario"),
                                        "fecha": ts,
                                    })
                                    with open(path, "w", encoding="utf-8") as f:
                                        json.dump(data, f, ensure_ascii=False, indent=2)
                                except Exception as ex:
                                    print("descuento retencion:", ex)
                            elif caso.tipo == "RETENER":
                                pass  # solo registro de gestión
                            caso.estado = "EJECUTADO"
                            caso.validado_por = session.get("usuario") or caso.validado_por
                            caso.validado_en = ts
                            caso.nota_validacion = (caso.nota_validacion or "") + (" | " if caso.nota_validacion else "") + (nota_v or "Ejecutado")
                            db.session.commit()
                            registrar_auditoria("Retención ejecutar", f"caso={caso.id} tipo={caso.tipo} inst={inst.codigo}")
                            msg = f"Caso #{caso.id} ejecutado en el sistema."
        elif accion in ("aprobar", "rechazar", "ejecutar") and not es_ejecutor:
            error = "Solo Retención o Gerencia puede validar/ejecutar. Su solicitud queda en espera de validación."

    # listado + filtros
    f_estado = (request.args.get("estado") or "").strip()
    f_tipo = (request.args.get("tipo") or "").strip()
    f_motivo = (request.args.get("motivo") or "").strip()
    q = CasoRetencion.query
    if f_estado:
        q = q.filter(CasoRetencion.estado == f_estado)
    if f_tipo:
        q = q.filter(CasoRetencion.tipo == f_tipo)
    if f_motivo:
        q = q.filter(CasoRetencion.motivo_filtro == f_motivo)
    casos = q.order_by(CasoRetencion.id.desc()).limit(60).all()
    instituciones = Institucion.query.order_by(Institucion.nombre.asc()).limit(300).all()
    inst_map = {i.id: f"{i.codigo} — {i.nombre}" for i in instituciones}
    opts_inst = "".join(f'<option value="{i.id}">{i.codigo} — {i.nombre} (plan: {i.plan or "—"})</option>' for i in instituciones)

    motivos_ret = [
        "Costos / precio",
        "Daño o falla del sistema",
        "Competencia / otra plataforma",
        "Cierre del colegio",
        "Bajo uso",
        "Insatisfacción servicio",
        "Cambio de administración",
        "Presupuesto recortado",
        "Otro",
    ]
    filas = ""
    for c in casos:
        colegio = inst_map.get(c.institucion_id, c.institucion_id or "—")
        acciones = ""
        if es_ejecutor and c.estado in ("PENDIENTE", "EN_VALIDACION"):
            acciones = f"""
            <form method="POST" style="display:inline">
              <input type="hidden" name="caso_id" value="{c.id}">
              <input type="hidden" name="nota_validacion" value="">
              <button name="accion" value="aprobar" style="background:#15803d;color:#fff;border:0;padding:4px 8px;border-radius:6px;font-size:11px;cursor:pointer">Aprobar</button>
              <button name="accion" value="rechazar" style="background:#b91c1c;color:#fff;border:0;padding:4px 8px;border-radius:6px;font-size:11px;cursor:pointer">Rechazar</button>
            </form>"""
        if es_ejecutor and c.estado == "APROBADO":
            acciones += f"""
            <form method="POST" style="display:inline">
              <input type="hidden" name="caso_id" value="{c.id}">
              <button name="accion" value="ejecutar" style="background:#0B2D57;color:#fff;border:0;padding:4px 8px;border-radius:6px;font-size:11px;cursor:pointer"
                onclick="return confirm('¿Ejecutar en el sistema (plan/descuento/cancelación)?')">Ejecutar</button>
            </form>"""
        if not es_ejecutor and c.estado in ("EN_VALIDACION", "PENDIENTE"):
            acciones = "<span style='color:#b45309;font-size:11px'>En espera de validación</span>"
        filas += f"""<tr>
          <td>{c.id}</td>
          <td style="white-space:nowrap">{c.creado_en}</td>
          <td>{c.tipo}</td>
          <td>{c.motivo_filtro}</td>
          <td><b>{c.estado}</b></td>
          <td>{colegio}</td>
          <td>{c.plan_actual or '—'} → {c.plan_solicitado or '—'}</td>
          <td>{c.descuento_pct or 0}% / {c.descuento_meses or 0}m</td>
          <td>{c.solicitado_por} ({c.solicitado_rol})</td>
          <td style="max-width:200px">{(c.detalle or '')[:100]}</td>
          <td>{acciones}</td>
        </tr>"""

    aviso_rol = (
        "<p style='background:#eff6ff;border:1px solid #93c5fd;padding:10px;border-radius:10px;color:#1e40af;font-size:13px'>"
        "<b>Retención / Gerencia:</b> puede aprobar y ejecutar bajas de plan, descuentos y cancelaciones.</p>"
        if es_ejecutor else
        "<p style='background:#fff7ed;border:1px solid #fdba74;padding:10px;border-radius:10px;color:#9a3412;font-size:13px'>"
        "<b>Ventas / Soporte:</b> puede registrar el caso, pero <b>bajar plan, descuentos y cancelaciones</b> requieren "
        "validación de Retención o Gerencia.</p>"
    )

    body = f"""
<style>
.rt{{max-width:1100px;margin:0 auto;font-family:Segoe UI,system-ui,sans-serif;padding:16px}}
.rt h1{{color:#0B2D57;margin:0 0 8px}}
.rt .box{{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px;margin-bottom:14px}}
.rt label{{display:block;font-weight:700;font-size:12px;margin:8px 0 4px}}
.rt input,.rt select,.rt textarea{{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd5e1;border-radius:10px}}
.rt .row{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}
.rt .row3{{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}}
@media(max-width:700px){{.rt .row,.rt .row3{{grid-template-columns:1fr}}}}
.rt button{{background:#0B2D57;color:#fff;border:0;padding:11px 18px;border-radius:10px;font-weight:800;cursor:pointer;margin-top:10px}}
.rt table{{width:100%;border-collapse:collapse;font-size:12px}}
.rt th{{background:#7c2d12;color:#fff;padding:8px;text-align:left}}
.rt td{{padding:8px;border-bottom:1px solid #e2e8f0;vertical-align:top}}
.rt .ok{{background:#ecfdf5;color:#065f46;padding:10px;border-radius:10px;margin-bottom:10px}}
.rt .err{{background:#fef2f2;color:#991b1b;padding:10px;border-radius:10px;margin-bottom:10px}}
.rt a.btn{{display:inline-block;background:#e2e8f0;color:#0B2D57;padding:8px 12px;border-radius:8px;text-decoration:none;font-weight:700;font-size:13px}}
</style>
<div class="rt">
  <p><a class="btn" href="/notas-cliente">Notas de cliente</a>
     <a class="btn" href="/soporte_admin">Soporte</a>
     <a class="btn" href="/ventas/panel">Ventas</a>
     <a class="btn" href="/gerencia/hq">Gerencia</a></p>
  <h1>Retención de clientes</h1>
  <p style="color:#64748b;font-size:14px">Cancelaciones, baja de plan y descuentos. Filtros por motivo (costos, daño de sistema, etc.).
  Solo <b>Retención / Gerencia</b> aplica cambios reales; asesores de ventas o soporte pasan por validación.</p>
  {aviso_rol}
  {"<div class='ok'>"+msg+"</div>" if msg else ""}
  {"<div class='err'>"+error+"</div>" if error else ""}

  <div class="box">
    <h2 style="margin:0 0 10px;font-size:15px;color:#7c2d12">Nuevo caso</h2>
    <form method="POST">
      <input type="hidden" name="accion" value="solicitar">
      <div class="row">
        <div>
          <label>Colegio *</label>
          <select name="institucion_id" required><option value="">— Seleccione —</option>{opts_inst}</select>
        </div>
        <div>
          <label>Tipo de caso *</label>
          <select name="tipo" required>
            <option value="RETENER">Retener (gestión / seguimiento)</option>
            <option value="CANCELACION">Cancelación de servicio</option>
            <option value="BAJA_PLAN">Baja de plan (downgrade)</option>
            <option value="DESCUENTO">Descuento especial</option>
          </select>
        </div>
      </div>
      <div class="row3">
        <div>
          <label>Motivo (filtro) *</label>
          <select name="motivo_filtro" required>
            {''.join(f'<option>{m}</option>' for m in motivos_ret)}
          </select>
        </div>
        <div>
          <label>Plan solicitado (si baja de plan)</label>
          <select name="plan_solicitado">
            <option value="">—</option>
            <option>Basico</option>
            <option>Institucional</option>
            <option>Premium</option>
          </select>
        </div>
        <div>
          <label>Descuento % / meses</label>
          <div style="display:flex;gap:8px">
            <input name="descuento_pct" type="number" step="0.1" min="0" max="100" placeholder="%" style="width:50%">
            <input name="descuento_meses" type="number" min="0" max="24" placeholder="meses" style="width:50%">
          </div>
        </div>
      </div>
      <div class="row">
        <div>
          <label>Contacto en el colegio</label>
          <input name="contacto_nombre">
        </div>
        <div>
          <label>Teléfono</label>
          <input name="telefono">
        </div>
      </div>
      <label>Detalle de la conversación / razón *</label>
      <textarea name="detalle" required rows="3" placeholder="Qué dijo el cliente, oferta planteada, próximo paso…"></textarea>
      <button type="submit">Registrar caso de retención</button>
    </form>
  </div>

  <div class="box">
    <h2 style="margin:0 0 10px;font-size:15px;color:#7c2d12">Casos · filtros</h2>
    <form method="GET" style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px">
      <select name="estado">
        <option value="">Estado: todos</option>
        {''.join(f'<option {"selected" if f_estado==s else ""}>{s}</option>' for s in ("PENDIENTE","EN_VALIDACION","APROBADO","RECHAZADO","EJECUTADO"))}
      </select>
      <select name="tipo">
        <option value="">Tipo: todos</option>
        {''.join(f'<option {"selected" if f_tipo==t else ""}>{t}</option>' for t in ("RETENER","CANCELACION","BAJA_PLAN","DESCUENTO"))}
      </select>
      <select name="motivo">
        <option value="">Motivo: todos</option>
        {''.join(f'<option {"selected" if f_motivo==m else ""}>{m}</option>' for m in motivos_ret)}
      </select>
      <button type="submit">Filtrar</button>
    </form>
    <div style="overflow-x:auto">
      <table>
        <tr>
          <th>ID</th><th>Fecha/hora</th><th>Tipo</th><th>Motivo</th><th>Estado</th>
          <th>Colegio</th><th>Plan</th><th>Desc.</th><th>Solicitó</th><th>Detalle</th><th>Acciones</th>
        </tr>
        {filas or '<tr><td colspan="11">Sin casos</td></tr>'}
      </table>
    </div>
  </div>
</div>
"""
    return page("Retención", body)



