def _plan_features(p):
    """features_json del plan (dict o lista) -> dict normalizado."""
    out = {
        "incluidos": [], "excluidos": [], "modulos": [],
        "soporte": "", "vigencia": "", "badge": "", "nota_qr": "", "tagline": "", "linea": "",
    }
    raw = getattr(p, "features_json", None) or ""
    try:
        d = json.loads(raw) if raw else {}
    except Exception:
        d = {}
    if isinstance(d, list):
        d = {"incluidos": [str(x) for x in d]}
    if not isinstance(d, dict):
        d = {}
    for k in ("incluidos", "excluidos", "modulos"):
        v = d.get(k) or []
        out[k] = [str(x).strip() for x in v if str(x).strip()] if isinstance(v, list) else []
    for k in ("soporte", "vigencia", "badge", "nota_qr", "tagline", "linea"):
        out[k] = str(d.get(k) or "").strip()
    return out


def _plan_nombre_vista(nombre):
    """'EDUTRACK 2.5 FC BASICO' -> 'EduTrack 2.5 FC Basico' (solo si viene todo en mayúsculas)."""
    n = (nombre or "").strip()
    if not n or n != n.upper():
        return n
    out = []
    for w in n.split():
        if w == "EDUTRACK":
            out.append("EduTrack")
        elif any(c.isdigit() for c in w) or len(w) <= 2:
            out.append(w)
        else:
            out.append(w.capitalize())
    return " ".join(out)


def _fmt_cop(v):
    try:
        return "$ " + "{:,.0f}".format(float(v or 0)).replace(",", ".")
    except Exception:
        return "$ 0"


def _fmt_num(v):
    try:
        return "{:,.0f}".format(float(v or 0)).replace(",", ".")
    except Exception:
        return "0"


def _plan_precios(p, promo=None):
    """Valores para la tarjeta: precio lista, precio con descuento, % y duración."""
    try:
        pleno = float(getattr(p, "precio_lista", 0) or 0) or float(getattr(p, "precio_mensual", 0) or 0)
    except Exception:
        pleno = 0.0
    try:
        pct = float(getattr(p, "descuento_pct", 0) or 0)
    except Exception:
        pct = 0.0
    try:
        meses = int(getattr(p, "descuento_meses", 0) or 0)
    except Exception:
        meses = 0
    neto = pleno
    duracion = ""
    promo_nombre = ""
    hasta = ""
    if pct > 0:
        try:
            neto = float(getattr(p, "precio_mensual", 0) or 0) or round(pleno * (1 - pct / 100.0))
        except Exception:
            neto = pleno
        duracion = ("Mes 1 al %d" % meses) if meses > 0 else "Descuento vigente"
    elif promo is not None and pleno > 0:
        try:
            pv = _calcular_promo_valores(pleno, promo)
            if float(pv.get("porcentaje") or 0) > 0:
                pct = float(pv.get("porcentaje") or 0)
                neto = float(pv.get("valor_descuento") or pleno)
                promo_nombre = pv.get("nombre_promo") or ""
                hasta = pv.get("fecha_caducidad_texto") or ""
                if (pv.get("duracion_unidad") or "") == "MESES" and int(pv.get("duracion_valor") or 0) > 0:
                    duracion = "Mes 1 al %d" % int(pv.get("duracion_valor") or 0)
                else:
                    duracion = ("Durante " + str(pv.get("tiempo_promo"))) if pv.get("tiempo_promo") else "Promoción vigente"
        except Exception:
            pct = 0.0
            neto = pleno
    tiene = pct > 0 and pleno > neto
    return {
        "lista": pleno, "neto": neto, "pct": pct, "meses": meses, "duracion": duracion,
        "tiene": tiene, "promo_nombre": promo_nombre, "hasta": hasta,
    }


def _plan_chips(f, max_n=3):
    """Fichas 'Incluye:' de la tarjeta: módulos activos o, si no hay, los beneficios listados."""
    chips = []
    mods = set(f.get("modulos") or [])
    for clave, lab in _PLAN_MODULOS_CORTO:
        if clave in mods and lab not in chips:
            chips.append(lab)
    if not chips:
        for x in (f.get("incluidos") or []):
            x = str(x).strip()
            if x:
                chips.append(x if len(x) <= 24 else x[:23].rstrip() + "…")
    extra = max(0, len(chips) - max_n)
    chips = chips[:max_n]
    if extra:
        chips.append("+%d" % extra)
    return chips


def _plan_card_html(p, promo=None, politicas=True):
    """Tarjeta visual del plan (diseño 'plan con descuento') con los datos reales de EduTrack."""
    f = _plan_features(p)
    pr = _plan_precios(p, promo)
    activo = bool(getattr(p, "activo", True))
    cod = (getattr(p, "codigo", "") or "").strip()
    mod = (getattr(p, "modalidad", None) or "presencial").strip().lower()
    es_qr = (f["linea"] == "qr") or cod.lower().startswith("qr")
    sub = "Online Virtual" if mod == "online" else ("Acceso QR" if es_qr else "Presencial")
    if not activo:
        pill = '<span class="ec-pill off">Suspendido</span>'
    elif pr["tiene"]:
        pill = '<span class="ec-pill">Plan con descuento</span>'
    else:
        etiqueta = (f["badge"] or "Plan").title().replace("Qr", "QR")
        pill = '<span class="ec-pill">%s</span>' % _esc(etiqueta)

    try:
        me = int(getattr(p, "max_estudiantes", 0) or 0)
    except Exception:
        me = 0
    if me <= 0 or me >= 99999:
        grande = '<div class="ec-big txt">Ilimitado</div>'
    else:
        grande = '<div class="ec-big">%s</div>' % _fmt_num(me)
    chips_html = "".join('<span class="ec-chip">%s</span>' % _esc(c) for c in _plan_chips(f)) \
        or '<span class="ec-chip">Plataforma EduTrack</span>'
    try:
        ms = int(getattr(p, "max_sedes", 0) or 0)
    except Exception:
        ms = 0
    sedes_txt = str(ms) if ms > 0 else "—"
    try:
        n_doc = int(getattr(p, "max_docentes", 0) or 0)
    except Exception:
        n_doc = 0
    try:
        n_adm = int(getattr(p, "max_admin", 0) or 0)
    except Exception:
        n_adm = 0
    usuarios_txt = "<b>%d</b> docentes · <b>%d</b> admin." % (n_doc, n_adm)
    soporte_txt = _esc(f["soporte"] or "Soporte estándar")
    vigencia_txt = _esc(f["vigencia"] or "Mensual")

    if pr["tiene"]:
        pct_txt = ("%g" % round(pr["pct"], 2))
        izq = ("Valor", _fmt_cop(pr["lista"]), "a", "")
        der = ("Valor con dcto.", _fmt_cop(pr["neto"]), "b",
               '<span class="ec-nota">%s%% · %s</span>' % (pct_txt, _esc(pr["duracion"])))
    else:
        try:
            fee = float(getattr(p, "fee_implementacion", 0) or 0)
        except Exception:
            fee = 0.0
        izq = ("Valor mensual", _fmt_cop(pr["lista"]), "a", "")
        der = ("Implementación", _fmt_cop(fee) if fee > 0 else "Sin costo", "c",
               '<span class="ec-nota">Pago único</span>' if fee > 0 else "")
    precios = (
        '<div class="ec-prices">'
        '<div><span class="ec-lab">%s</span><div class="ec-p %s">%s</div></div>'
        '<div><span class="ec-lab">%s</span><div class="ec-p %s">%s</div>%s</div>'
        '</div>'
    ) % (izq[0], izq[2], _esc(izq[1]), der[0], der[2], _esc(der[1]), der[3])

    if politicas and cod:
        pol = (
            '<a class="ec-pol" href="/planes/politicas/%s">%s<span>Ver políticas</span></a>'
            % (quote(cod, safe=""), _EC_ICO["doc"])
        )
    else:
        pol = ""

    return (
        '<article class="ec-card" aria-label="Plan %s">'
        '<div class="ec-top"><div class="ec-brand">%s<div><div class="ec-logo">Edu<b>Track</b><sup>®</sup></div>'
        '<div class="ec-sub">%s</div></div></div>%s</div>'
        '<div class="ec-title"><div class="ec-name">%s</div>'
        '<div class="ec-code">Código único: <b>%s</b></div></div>'
        '<div class="ec-data"><div class="ec-data-h">%s<span>Estudiantes incluidos</span></div>%s'
        '<div class="ec-bar"><span>Incluye:</span>%s</div>'
        '<div class="ec-share"><span>%s Sedes incluidas:</span>'
        '<div class="ec-box"><small>Hasta</small><b>%s</b></div></div></div>'
        '<div class="ec-blk"><div class="ec-blk-h">%s<span>Usuarios de la plataforma</span></div>'
        '<div class="ec-blk-b">%s</div></div>'
        '<div class="ec-blk"><div class="ec-blk-h">%s<span>Soporte y vigencia</span></div>'
        '<div class="ec-blk-b">%s <small>(%s)</small></div></div>'
        '%s%s'
        '<div class="ec-foot"><i></i>%s<span>Conecta, estudia y avanza</span><i></i></div>'
        '</article>'
    ) % (
        _esc(getattr(p, "nombre", "") or cod),
        _EC_ICO["cap"], _esc(sub), pill,
        _esc(_plan_nombre_vista(getattr(p, "nombre", "") or cod)), _esc(cod),
        _EC_ICO["users"], grande, chips_html,
        _EC_ICO["sedes"], _esc(sedes_txt),
        _EC_ICO["users"], usuarios_txt,
        _EC_ICO["soporte"], soporte_txt, vigencia_txt,
        precios, pol,
        _EC_ICO["star"],
    )


def _plan_acciones_html(p, next_url="/gerencia/planes"):
    """Botones de Gerencia bajo la tarjeta: editar, beneficios y activar / suspender."""
    activo = bool(getattr(p, "activo", True))
    nu = _esc(next_url)
    if activo:
        estado_btn = (
            '<form method="POST" action="/gerencia/planes/%d/estado" '
            'onsubmit="return confirm(\'¿Suspender este plan? Deja de ofrecerse en ventas y en el catálogo. '
            'Los colegios que ya lo tienen no se afectan.\')">'
            '<input type="hidden" name="accion" value="suspender">'
            '<input type="hidden" name="next" value="%s">'
            '<button type="submit" class="ec-btn off">Suspender</button></form>' % (p.id, nu)
        )
    else:
        estado_btn = (
            '<form method="POST" action="/gerencia/planes/%d/estado">'
            '<input type="hidden" name="accion" value="activar">'
            '<input type="hidden" name="next" value="%s">'
            '<button type="submit" class="ec-btn on">Activar plan</button></form>' % (p.id, nu)
        )
    return (
        '<div class="ec-act">'
        '<a class="ec-btn pri" href="/gerencia/planes/editar/%d">Editar plan</a>'
        '<a class="ec-btn" href="/gerencia/beneficios/%d">Beneficios</a>%s</div>' % (p.id, p.id, estado_btn)
    )


def _next_seguro(nxt, default):
    """Solo rutas internas de planes (evita redirecciones abiertas)."""
    nxt = (nxt or "").strip()
    permitidos = ("/gerencia/planes", "/gerencia/beneficios", "/planes/buscar")
    if nxt.startswith("/") and not nxt.startswith("//") and "\\" not in nxt and nxt.startswith(permitidos):
        return nxt
    return default


def _msg_html(msg, err=""):
    out = ""
    if msg:
        out += '<div class="ec-okmsg" role="status">%s</div>' % _esc(msg)
    if err:
        out += '<div class="ec-errmsg" role="alert">%s</div>' % _esc(err)
    return out


@app.route("/gerencia/planes/<int:pid>/estado", methods=["POST"])
def gerencia_plan_estado(pid):
    """Gerencia activa o suspende un plan del catálogo (no afecta a colegios que ya lo tienen)."""
    _g = _guard_gerencia()
    if _g is not None:
        return _g
    dest = _next_seguro(request.form.get("next"), "/gerencia/planes")
    accion = (request.form.get("accion") or "").strip().lower()
    p = PlanComercial.query.get_or_404(pid)
    if accion not in ("activar", "suspender"):
        msg = "Acción no válida."
    else:
        try:
            p.activo = (accion == "activar")
            db.session.commit()
            try:
                registrar_auditoria(
                    "Plan activado" if p.activo else "Plan suspendido",
                    "%s · %s" % (p.codigo or p.id, p.nombre or ""),
                )
            except Exception:
                pass
            msg = "Plan «%s» %s." % (p.nombre or p.codigo, "activado" if p.activo else "suspendido")
        except Exception as ex:
            try:
                db.session.rollback()
            except Exception:
                pass
            msg = "No se pudo cambiar el estado: %s" % str(ex)[:100]
    return redirect(dest + ("&" if "?" in dest else "?") + "msg=" + quote(msg))


@app.route("/gerencia/planes", methods=["GET", "POST"])
def gerencia_planes():
    """Planes activos: tarjetas con activar / suspender. Edición y alta van a páginas separadas."""
    _g = _guard_gerencia()
    if _g is not None:
        return _g
    try:
        _ensure_plan_comercial_cols()
        _seed_planes_comerciales()
    except Exception:
        pass
    msg = (request.args.get("msg") or "").strip()
    edit_id = request.args.get("edit")
    if edit_id:
        return redirect("/gerencia/planes/editar/%s" % edit_id)
    q = (request.args.get("q") or "").strip()
    estado = (request.args.get("estado") or "todos").strip().lower()
    if estado not in ("todos", "activos", "suspendidos"):
        estado = "todos"
    todos = PlanComercial.query.order_by(PlanComercial.orden, PlanComercial.id).all()
    n_act = sum(1 for p in todos if p.activo)
    n_sus = len(todos) - n_act
    nq = _norm_txt(q)
    vistos = []
    for p in todos:
        if estado == "activos" and not p.activo:
            continue
        if estado == "suspendidos" and p.activo:
            continue
        if nq and nq not in _norm_txt(p.codigo) and nq not in _norm_txt(p.nombre):
            continue
        vistos.append(p)
    promo = None
    try:
        promo = _promo_activa_global()
    except Exception:
        promo = None
    next_url = "/gerencia/planes?estado=%s&q=%s" % (estado, quote_plus(q))
    items = "".join(
        '<div class="ec-item%s">%s%s</div>' % (
            "" if p.activo else " ec-off", _plan_card_html(p, promo), _plan_acciones_html(p, next_url)
        )
        for p in vistos
    )
    if not items:
        items = (
            '<div class="ec-empty" style="grid-column:1/-1">No hay planes con ese filtro. '
            'Cambie el estado o cree un plan nuevo.</div>'
        )

    def _chip(clave, texto, n):
        href = "/gerencia/planes?estado=%s&q=%s" % (clave, quote_plus(q))
        return '<a class="ec-fchip%s" href="%s">%s (%d)</a>' % (" on" if estado == clave else "", href, texto, n)

    chips = _chip("todos", "Todos", len(todos)) + _chip("activos", "Activos", n_act) + _chip("suspendidos", "Suspendidos", n_sus)
    addons = AddonComercial.query.filter_by(activo=True).all()
    add_html = "".join(
        '<li style="display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-top:1px solid #e6edf7">'
        '<span><b>%s</b><br><small style="color:#64748b">%s</small></span><b style="color:#15803d;white-space:nowrap">%s / mes</b></li>'
        % (_esc(a.nombre), _esc(a.descripcion), _fmt_cop(a.precio_mensual))
        for a in addons
    )
    content = f"""
{_PLAN_CARD_CSS}
<header class="role-hero"><div>
  <h1>Planes activos</h1>
  <p>Active o suspenda planes del catálogo. Un plan suspendido deja de ofrecerse en ventas; los colegios que ya lo tienen siguen igual.</p>
</div>
<div style="display:flex;flex-wrap:wrap;gap:8px">
  <a class="btn" href="/gerencia/planes/nuevo">+ Crear plan nuevo</a>
  <a class="btn" href="/gerencia/beneficios">Beneficios</a>
  <a class="btn" href="/planes/buscar">Buscar plan</a>
</div></header>
{_msg_html(msg)}
<section class="role-panel">
  <form method="GET" class="ec-search" role="search">
    <input type="hidden" name="estado" value="{_esc(estado)}">
    <input type="search" name="q" value="{_esc(q)}" placeholder="Filtrar por código o nombre" aria-label="Filtrar planes por código o nombre" autocomplete="off">
    <button type="submit" class="btn">Filtrar</button>
  </form>
  <div class="ec-fchips">{chips}</div>
</section>
<div class="ec-grid">{items}</div>
<section class="role-panel">
  <h2 style="margin:0 0 6px;font-size:17px;color:#0a2a7a">Add-ons</h2>
  <ul style="list-style:none;margin:0;padding:0">{add_html or '<li style="color:#64748b">Sin add-ons</li>'}</ul>
</section>
"""
    return page("Planes gerencia", shell(content))


@app.route("/planes/politicas/<codigo>")
def planes_politicas(codigo):
    """'Ver políticas': beneficios, límites y condiciones que trae cada plan (uso interno)."""
    if not requiere_login():
        return redirect("/login")
    rol = rol_actual()
    if rol not in _ROLES_VER_PLANES:
        return acceso_denegado()
    _marcar_layout_staff()
    try:
        _ensure_plan_comercial_cols()
    except Exception:
        pass
    cod = (codigo or "").strip()
    p = PlanComercial.query.filter_by(codigo=cod).first()
    if p is None:
        p = PlanComercial.query.filter(func.lower(PlanComercial.codigo) == cod.lower()).first()
    if p is None:
        body = (
            '<header class="role-hero"><div><h1>Plan no encontrado</h1>'
            '<p>No existe un plan con el código «%s».</p></div>'
            '<a class="btn" href="/planes/buscar">← Buscar planes</a></header>' % _esc(cod)
        )
        return page("Plan no encontrado", shell(body))
    promo = None
    try:
        promo = _promo_activa_global()
    except Exception:
        promo = None
    f = _plan_features(p)
    pr = _plan_precios(p, promo)
    es_ger = rol in _ROLES_GERENCIA_PLANES
    activo = bool(p.activo)

    incluidos = f["incluidos"] or [_PLAN_MODULOS_LARGO.get(m, m) for m in f["modulos"]]
    sec_incl = ""
    if incluidos:
        sec_incl = (
            '<section class="ec-sec"><h2>Beneficios que trae el plan</h2><ul class="ec-list">%s</ul></section>'
            % "".join("<li>%s</li>" % _esc(x) for x in incluidos)
        )
    sec_mods = ""
    if f["modulos"] and f["incluidos"]:
        sec_mods = (
            '<section class="ec-sec"><h2>Funciones activas</h2><div class="ec-chipset">%s</div></section>'
            % "".join("<span>%s</span>" % _esc(_PLAN_MODULOS_LARGO.get(m, m)) for m in f["modulos"])
        )
    sec_no = ""
    if f["excluidos"]:
        sec_no = (
            '<section class="ec-sec"><h2>No incluye</h2><ul class="ec-list no">%s</ul></section>'
            % "".join("<li>%s</li>" % _esc(x) for x in f["excluidos"])
        )
    titulo = (getattr(p, "titulo_comercial", None) or "").strip()
    wa = (getattr(p, "mensaje_whatsapp", None) or "").strip()
    cta = (getattr(p, "cta_comercial", None) or "").strip()
    sec_copy = ""
    if titulo or wa or cta:
        sec_copy = '<section class="ec-sec"><h2>Mensaje comercial</h2>'
        if titulo:
            sec_copy += '<p style="margin:0 0 8px;font-weight:700;color:#0a2a7a">%s</p>' % _esc(titulo)
        if wa:
            sec_copy += '<pre class="ec-msg">%s</pre>' % _esc(wa)
        if cta:
            sec_copy += '<p style="margin:8px 0 0;font-weight:700;color:#0a3aa5">%s</p>' % _esc(cta)
        sec_copy += "</section>"
    me = int(getattr(p, "max_estudiantes", 0) or 0)
    fee = float(getattr(p, "fee_implementacion", 0) or 0)
    if pr["tiene"]:
        pct_txt = "%g" % round(pr["pct"], 2)
        desc_txt = "%s%% de descuento · %s. Pasa de %s a %s al mes." % (
            pct_txt, pr["duracion"].lower() if pr["duracion"] else "vigente", _fmt_cop(pr["lista"]), _fmt_cop(pr["neto"]))
        if pr["promo_nombre"]:
            desc_txt += " Promoción: %s." % pr["promo_nombre"]
    else:
        desc_txt = "Sin descuento vigente."
    filas = [
        ("Estado del plan", "Activo" if activo else "Suspendido (no se ofrece en ventas)"),
        ("Modalidad", "Online / virtual" if (getattr(p, "modalidad", "") or "").lower() == "online" else "Presencial"),
        ("Estudiantes", "Ilimitados" if (me <= 0 or me >= 99999) else _fmt_num(me)),
        ("Sedes", (str(int(getattr(p, "max_sedes", 0) or 0)) if int(getattr(p, "max_sedes", 0) or 0) > 0 else "—")),
        ("Usuarios administrativos", str(int(getattr(p, "max_admin", 0) or 0))),
        ("Docentes", str(int(getattr(p, "max_docentes", 0) or 0))),
        ("Soporte", f["soporte"] or "Soporte estándar"),
        ("Vigencia", f["vigencia"] or "Mensual"),
        ("Valor mensual", _fmt_cop(pr["lista"])),
        ("Implementación", (_fmt_cop(fee) + " (pago único)") if fee > 0 else "Sin costo"),
        ("Descuento", desc_txt),
    ]
    dl = "".join("<dt>%s</dt><dd>%s</dd>" % (_esc(k), _esc(v)) for k, v in filas)
    nota = ('<section class="ec-sec"><h2>Nota</h2><p style="margin:0;font-size:14px;color:#334155">%s</p></section>' % _esc(f["nota_qr"])) if f["nota_qr"] else ""
    acciones_ger = ""
    if es_ger:
        acciones_ger = (
            '<a class="btn" href="/gerencia/beneficios/%d">Editar beneficios</a>'
            '<a class="btn" href="/gerencia/planes/editar/%d">Editar plan</a>' % (p.id, p.id)
        )
    content = f"""
{_PLAN_CARD_CSS}
<header class="role-hero"><div>
  <h1>Políticas · {_esc(_plan_nombre_vista(p.nombre) or p.codigo)}</h1>
  <p>Lo que trae este plan: beneficios, límites y condiciones comerciales.</p>
</div>
<div style="display:flex;flex-wrap:wrap;gap:8px">{acciones_ger}<a class="btn" href="/planes/buscar">← Buscar planes</a></div></header>
<div class="ec-pol-grid">
  <div class="{'ec-off' if not activo else ''}">{_plan_card_html(p, promo, politicas=False)}</div>
  <div class="role-panel">
    {sec_incl}{sec_mods}{sec_no}{sec_copy}
    <section class="ec-sec"><h2>Condiciones del plan</h2><dl class="ec-dl">{dl}</dl></section>
    {nota}
  </div>
</div>
"""
    return page("Políticas del plan", shell(content))


def _plan_form_fields(p=None, crear=False):
    """HTML de campos compartidos crear/editar plan (familia + funciones)."""
    p = p or PlanComercial()
    feats_raw = getattr(p, "features_json", None) or ""
    feats_dict = {}
    feats_pipe = ""
    try:
        parsed = json.loads(feats_raw) if feats_raw else None
        if isinstance(parsed, dict):
            feats_dict = parsed
            feats_pipe = "|".join(parsed.get("incluidos") or []) if isinstance(parsed.get("incluidos"), list) else ""
        elif isinstance(parsed, list):
            feats_pipe = "|".join(str(x) for x in parsed)
            feats_dict = {"incluidos": parsed}
    except Exception:
        feats_pipe = ""
    mods_on = set(feats_dict.get("modulos") or [])
    # Reportes export siempre activos por política comercial
    mods_on.add("reportes_basicos")
    mods_on.add("reportes_excel")
    linea = (feats_dict.get("linea") or ("qr" if str(getattr(p, "codigo", "") or "").startswith("qr") else "institucional")).lower()
    if linea not in ("qr", "institucional"):
        linea = "institucional"
    mod = (getattr(p, "modalidad", None) or "presencial").lower()
    precio_lista = int(float(getattr(p, "precio_lista", None) or getattr(p, "precio_mensual", 0) or 0))
    # checkboxes de módulos
    catalog = [
        ("reportes_basicos", "Reportes en pantalla"),
        ("reportes_excel", "Exportar Excel / PDF / Word"),
        ("estudiantes", "Estudiantes y grupos"),
        ("portal_docente", "Portal docente"),
        ("notas_basico", "Notas / SIEE básico"),
        ("notas_completo", "Planilla notas tipo Excel"),
        ("boletines_pdf", "Boletines PDF"),
        ("siee", "SIEE completo"),
        ("import_excel", "Import Excel + SIMAT"),
        ("novedades", "Convivencia / novedades"),
        ("citaciones", "Citaciones"),
        ("horarios", "Horarios"),
        ("reportes_padres", "Reportes a padres"),
        ("carnes", "Carnés digitales"),
        ("asistencia_qr", "Asistencia QR"),
        ("portal_porteria", "Portal portería / QR ingreso"),
        ("ingreso_manual", "Ingreso manual"),
        ("aviso_ingreso_whatsapp", "WhatsApp aviso ingreso"),
        ("calendario", "Calendario escolar"),
        ("multi_sede", "Multi-sede"),
        ("historial_padres", "Portal familiar asistencia viva"),
        ("alertas_impuntualidad", "Alertas de impuntualidad"),
        ("eduaura", "EduAura IA"),
        ("auditoria", "Auditoría de notas"),
        ("contacto", "PQR padres + PQR a PROCSIS"),
    ]
    boxes = []
    activos_chips = []
    for key, lab in catalog:
        forced = key in ("reportes_basicos", "reportes_excel")
        on = key in mods_on or forced
        chk = "checked" if on else ""
        dis = "disabled" if forced else ""
        boxes.append(
            '<label class="mod-item%s">'
            '<input type="checkbox" name="modulos" value="%s" %s %s onchange="planModsPreview()">'
            '<span>%s</span></label>'
            % (" is-on" if on else "", key, chk, dis, lab)
        )
        if forced:
            boxes.append('<input type="hidden" name="modulos" value="%s">' % key)
        if on:
            activos_chips.append('<span class="mod-chip">%s</span>' % lab)
    boxes_html = "".join(boxes)
    chips_html = "".join(activos_chips) or '<span class="mod-chip mute">Ninguna función extra (solo reportes base)</span>'
    return f"""
                <label>Nombre</label>
                <input name="nombre" value="{_esc(getattr(p,'nombre',None) or '')}" required placeholder="Ej: Básico">
                {"<label>Código (único, minúsculas)</label><input name='codigo' required placeholder='ej: basico_pro' pattern='[a-z0-9_]+'>" if crear else ""}
                <label style="margin-top:12px">Familia del plan</label>
                <div style="display:flex;gap:16px;margin:8px 0 12px;font-size:14px;flex-wrap:wrap">
                  <label style="font-weight:600;display:flex;align-items:center;gap:6px"><input type="radio" name="linea_plan" value="institucional" {"checked" if linea!="qr" else ""}> Institucional / Académico</label>
                  <label style="font-weight:600;display:flex;align-items:center;gap:6px"><input type="radio" name="linea_plan" value="qr" {"checked" if linea=="qr" else ""}> Solo QR (acceso / seguridad)</label>
                </div>
                <p class="hint">Define si el colegio ve módulos académicos o solo portería/asistencia.</p>
                <label style="margin-top:12px">Modalidad</label>
                <div style="display:flex;gap:16px;margin:8px 0 12px;font-size:14px">
                  <label style="font-weight:600;display:flex;align-items:center;gap:6px"><input type="radio" name="modalidad" value="presencial" {"checked" if mod!="online" else ""}> Presencial</label>
                  <label style="font-weight:600;display:flex;align-items:center;gap:6px"><input type="radio" name="modalidad" value="online" {"checked" if mod=="online" else ""}> Online / Virtual</label>
                </div>
                <div class="row2">
                  <div>
                    <label>Precio lista mensual (COP)</label>
                    <input name="precio" type="number" min="0" step="1" value="{precio_lista}">
                  </div>
                  <div>
                    <label>Fee implementación</label>
                    <input name="fee" type="number" min="0" step="1" value="{int(float(getattr(p,'fee_implementacion',0) or 0))}">
                  </div>
                </div>
                <div class="row2">
                  <div><label>Máx. estudiantes</label><input name="max_e" type="number" value="{int(getattr(p,'max_estudiantes',750) or 750)}"></div>
                  <div><label>Máx. sedes</label><input name="max_s" type="number" value="{int(getattr(p,'max_sedes',3) or 3)}"></div>
                </div>
                <div class="row2">
                  <div><label>Máx. usuarios administrativos</label><input name="max_admin" type="number" value="{int(getattr(p,'max_admin',10) or 10)}"></div>
                  <div><label>Máx. profesores / docentes</label><input name="max_docentes" type="number" value="{int(getattr(p,'max_docentes',30) or 30)}"></div>
                </div>
                <div class="row2">
                  <div><label>Descuento %</label><input name="descuento_pct" type="number" min="0" max="100" step="0.5" value="{float(getattr(p,'descuento_pct',0) or 0)}"></div>
                  <div><label>Duración descuento (meses)</label><input name="descuento_meses" type="number" min="0" max="36" value="{int(getattr(p,'descuento_meses',0) or 0)}"></div>
                </div>
                <label style="margin-top:18px;font-size:14px;color:#0B2D57">Funciones de este plan</label>
                <p class="hint">Active o desactive módulos. Excel/PDF/Word siempre incluidos. La vista previa abajo muestra lo que queda activo.</p>
                <div class="mod-grid">{boxes_html}</div>
                <div class="mod-preview">
                  <div class="mod-preview-title">Funciones activas en este plan</div>
                  <div id="mod-chips" class="mod-chips">{chips_html}</div>
                </div>
                <style>
                .mod-grid{{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0;max-height:320px;overflow:auto;padding:12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px}}
                .mod-item{{display:flex;align-items:flex-start;gap:10px;font-size:13px;font-weight:500;color:#1e293b;margin:0;padding:10px 12px;background:#fff;border:1px solid #e2e8f0;border-radius:10px;cursor:pointer;line-height:1.35}}
                .mod-item input{{margin-top:2px;flex-shrink:0;width:16px;height:16px}}
                .mod-item span{{flex:1;text-align:left}}
                .mod-item.is-on{{border-color:#93c5fd;background:#eff6ff}}
                .mod-preview{{margin:14px 0 8px;padding:14px;background:#0B2D57;border-radius:12px;color:#fff}}
                .mod-preview-title{{font-size:12px;font-weight:700;opacity:.85;margin-bottom:10px;letter-spacing:.02em}}
                .mod-chips{{display:flex;flex-wrap:wrap;gap:6px}}
                .mod-chip{{background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:5px 10px;border-radius:999px;font-size:12px;font-weight:600}}
                .mod-chip.mute{{opacity:.7;font-weight:500}}
                @media(max-width:640px){{.mod-grid{{grid-template-columns:1fr}}}}
                </style>
                <script>
                function planModsPreview(){{
                  var box=document.getElementById('mod-chips');
                  if(!box)return;
                  var labs=[];
                  document.querySelectorAll('.mod-item').forEach(function(lab){{
                    var inp=lab.querySelector('input[type=checkbox]');
                    if(inp && (inp.checked||inp.disabled)){{
                      lab.classList.add('is-on');
                      var t=(lab.querySelector('span')||{{}}).textContent||'';
                      if(t)labs.push('<span class="mod-chip">'+t+'</span>');
                    }}else{{lab.classList.remove('is-on');}}
                  }});
                  box.innerHTML=labs.length?labs.join(''):'<span class="mod-chip mute">Ninguna función extra</span>';
                }}
                </script>
                <label>Título comercial / eslogan</label>
                <input name="titulo_comercial" value="{_esc(getattr(p,'titulo_comercial',None) or '')}" placeholder="✨ Un plan que lo tiene todo ✨" maxlength="160">
                <label>Mensaje WhatsApp (beneficios)</label>
                <textarea name="mensaje_whatsapp" rows="4">{_esc(getattr(p,'mensaje_whatsapp',None) or '')}</textarea>
                <label>CTA comercial</label>
                <input name="cta_comercial" value="{_esc(getattr(p,'cta_comercial',None) or '')}" maxlength="255">
                <label>Features texto (opcional, separados por |)</label>
                <input name="features" value="{_esc(feats_pipe)}" placeholder="tagline|nota interna…">
                <p class="hint">Complemento libre; las funciones reales son los checks de arriba.</p>
                <label>Imagen del plan</label>
                <input type="file" name="imagen" accept="image/*">
"""


def _aplicar_campos_plan(p, form, crear=False):
    p.nombre = (form.get("nombre") or p.nombre or "")[:80]
    if crear:
        cod = (form.get("codigo") or "").strip().lower().replace(" ", "_")[:40]
        p.codigo = cod
    mod = (form.get("modalidad") or "presencial").strip().lower()
    p.modalidad = "online" if mod == "online" else "presencial"
    precio_base = float(form.get("precio") or 0)
    descuento_pct = max(0.0, min(100.0, float(form.get("descuento_pct") or 0)))
    p.precio_lista = precio_base
    p.descuento_pct = descuento_pct
    p.descuento_meses = max(0, int(form.get("descuento_meses") or 0))
    if descuento_pct > 0:
        p.precio_mensual = round(precio_base * (1 - descuento_pct / 100.0), 2)
    else:
        p.precio_mensual = precio_base
    p.fee_implementacion = float(form.get("fee") or 0)
    p.max_estudiantes = int(form.get("max_e") or 100)
    p.max_sedes = int(form.get("max_s") or 1)
    p.max_admin = int(form.get("max_admin") or 10)
    p.max_docentes = int(form.get("max_docentes") or 30)
    p.titulo_comercial = (form.get("titulo_comercial") or "")[:160]
    p.mensaje_whatsapp = (form.get("mensaje_whatsapp") or "")[:8000]
    p.cta_comercial = (form.get("cta_comercial") or "")[:255]
    feats_txt = (form.get("features") or "").strip()
    incluidos_txt = [x.strip() for x in feats_txt.split("|") if x.strip()]
    linea = (form.get("linea_plan") or "institucional").strip().lower()
    if linea not in ("qr", "institucional"):
        linea = "institucional"
    modulos = form.getlist("modulos") if hasattr(form, "getlist") else []
    if not isinstance(modulos, list):
        modulos = [modulos] if modulos else []
    modulos = [str(m).strip() for m in modulos if str(m).strip()]
    # Política: export Excel/PDF/Word en todos los planes
    for forced in ("reportes_basicos", "reportes_excel"):
        if forced not in modulos:
            modulos.append(forced)
    p.features_json = json.dumps({
        "linea": linea,
        "modulos": modulos,
        "incluidos": incluidos_txt,
        "tagline": incluidos_txt[0] if incluidos_txt else "",
    }, ensure_ascii=False)
    img = request.files.get("imagen")
    if img and img.filename:
        folder = os.path.join(app.root_path, "static", "uploads", "planes")
        os.makedirs(folder, exist_ok=True)
        fname = "plan_%s.jpg" % (p.id or p.codigo or "new")
        dest = os.path.join(folder, fname)
        try:
            from PIL import Image
            from io import BytesIO
            raw = img.read()
            im = Image.open(BytesIO(raw))
            if im.mode in ("RGBA", "P"):
                im = im.convert("RGB")
            im.thumbnail((480, 160), Image.Resampling.LANCZOS)
            canvas = Image.new("RGB", (480, 160), (11, 45, 87))
            x = (480 - im.width) // 2
            y = (160 - im.height) // 2
            canvas.paste(im, (x, y))
            canvas.save(dest, "JPEG", quality=85)
            p.imagen_path = "/static/uploads/planes/%s" % fname
        except Exception:
            try:
                img.stream.seek(0)
            except Exception:
                pass
            try:
                img.save(dest)
                p.imagen_path = "/static/uploads/planes/%s" % fname
            except Exception:
                pass


@app.route("/gerencia/planes/editar/<int:pid>", methods=["GET", "POST"])
def gerencia_planes_editar(pid):
    """Edición de un plan en página dedicada (sin listado debajo)."""
    _g = _guard_gerencia()
    if _g is not None:
        return _g
    try:
        _ensure_plan_comercial_cols()
    except Exception:
        pass
    p = PlanComercial.query.get_or_404(pid)
    err = msg = ""
    if request.method == "POST":
        try:
            _aplicar_campos_plan(p, request.form, crear=False)
            db.session.commit()
            try:
                registrar_auditoria("Gerencia plan editado", p.codigo or str(p.id))
            except Exception:
                pass
            return redirect("/gerencia/planes?msg=" + quote("Plan %s guardado." % (p.nombre or "")))
        except Exception as e:
            db.session.rollback()
            err = str(e)[:200]
    body = f"""
<style>
.gpages{{background:#f1f5f9;min-height:100vh;font-family:Segoe UI,system-ui,sans-serif;padding:20px 16px 40px}}
.gpages-in{{max-width:720px;margin:0 auto}}
.pedit{{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:22px}}
.pedit h1{{margin:0 0 6px;color:#0B2D57;font-size:20px}}
.pedit label{{display:block;font-size:12px;font-weight:700;color:#475569;margin:10px 0 4px}}
.pedit input,.pedit textarea{{width:100%;padding:11px;border:1px solid #e2e8f0;border-radius:8px;box-sizing:border-box;font-size:14px}}
.row2{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}
.hint{{font-size:11px;color:#64748b;margin:4px 0 0}}
.actions{{margin-top:18px;display:flex;gap:12px;align-items:center}}
.actions button{{background:#0B2D57;color:#fff;border:0;padding:12px 20px;border-radius:10px;font-weight:800;cursor:pointer}}
.actions a{{color:#64748b;font-size:13px}}
.msg{{padding:10px;border-radius:8px;margin-bottom:12px;font-weight:600}}
.ok{{background:#dcfce7;color:#166534}}.err{{background:#fee2e2;color:#991b1b}}
@media(max-width:640px){{.row2{{grid-template-columns:1fr}}}}
</style>
<div class="gpages"><div class="gpages-in">
  <a href="/gerencia/planes" style="color:#0B2D57;font-weight:700;text-decoration:none;font-size:13px">← Volver a planes</a>
  <div class="pedit" style="margin-top:12px">
    <h1>Editar: {_esc(p.nombre)}</h1>
    <p style="color:#64748b;font-size:13px;margin:0 0 12px">Código <b>{_esc(p.codigo)}</b> · los cambios se reflejan en ventas y portal público al instante.</p>
    {"<div class='msg err'>"+_esc(err)+"</div>" if err else ""}
    <form method="POST" enctype="multipart/form-data">
      {_plan_form_fields(p, crear=False)}
      <div class="actions">
        <button type="submit">Guardar plan</button>
        <a href="/gerencia/planes">Cancelar</a>
      </div>
    </form>
  </div>
</div></div>
"""
    return page("Editar plan", body)


@app.route("/gerencia/planes/nuevo", methods=["GET", "POST"])
def gerencia_planes_nuevo():
    """Alta de un plan comercial nuevo (módulo dedicado)."""
    # Desarrollador: puede crear estructura técnica del plan (módulos/rutas), no editar precios de planes activos
    if rol_actual() in ("Desarrollador", "Developer"):
        if not requiere_login():
            return redirect("/dev-console-login")
    else:
        _g = _guard_gerencia()
        if _g is not None:
            return _g
    try:
        _ensure_plan_comercial_cols()
    except Exception:
        pass
    err = ""
    if request.method == "POST":
        cod = (request.form.get("codigo") or "").strip().lower().replace(" ", "_")[:40]
        if not cod:
            err = "Código de plan obligatorio."
        elif PlanComercial.query.filter_by(codigo=cod).first():
            err = "Ya existe un plan con código %s." % cod
        else:
            try:
                p = PlanComercial(codigo=cod, activo=True, orden=int(request.form.get("orden") or 99))
                _aplicar_campos_plan(p, request.form, crear=True)
                db.session.add(p)
                db.session.commit()
                # renombrar imagen con id real si se subió
                try:
                    if p.imagen_path and "plan_new" in (p.imagen_path or ""):
                        pass
                except Exception:
                    pass
                try:
                    registrar_auditoria("Plan comercial creado", "%s · $%s" % (cod, p.precio_mensual))
                except Exception:
                    pass
                return redirect("/gerencia/planes?msg=" + quote("Plan %s creado." % (p.nombre or cod)))
            except Exception as e:
                db.session.rollback()
                err = str(e)[:200]
