def _plan_label_estudiantes(max_e):
    try:
        n = int(max_e or 0)
    except Exception:
        n = 0
    if n <= 0 or n >= 99999:
        return "Estudiantes ilimitados"
    return f"Hasta {n:,}".replace(",", ".") + " estudiantes"


def _seed_planes_comerciales():
    try:
        _ensure_plan_comercial_cols()
    except Exception:
        try:
            db.session.rollback()
        except Exception:
            pass
    """Sincroniza los 5 planes oficiales (precios, sedes 12, módulos). Editar en Gerencia sobrescribe y el portal lee BD."""
    try:
        from sqlalchemy import text, inspect
        insp = inspect(db.engine)
        if 'planes_comerciales' in insp.get_table_names():
            cols = {c['name'] for c in insp.get_columns('planes_comerciales')}
            if 'imagen_path' not in cols:
                with db.engine.begin() as conn:
                    conn.execute(text("ALTER TABLE planes_comerciales ADD COLUMN imagen_path VARCHAR(255) DEFAULT ''"))
    except Exception as _ip:
        print('plan imagen col', _ip)

    defaults = _catalogo_planes_oficial()
    codigos_ok = {d["codigo"] for d in defaults}
    # force_sync una vez si precios aún son los antiguos (detecta Básico != 149950)
    force = False
    try:
        # Solo forzar estructura (features) si faltan planes QR o no hay basico.
        # NUNCA forzar solo por diferencia de precio (Gerencia edita precios en vivo).
        bas = PlanComercial.query.filter_by(codigo="basico").first()
        if not bas:
            force = True
        if PlanComercial.query.filter_by(codigo="qr_basico").first() is None:
            force = True
        if PlanComercial.query.count() < 3:
            force = True
    except Exception:
        force = True
    for d in defaults:
        cod = d["codigo"]
        p = PlanComercial.query.filter_by(codigo=cod).first()
        if not p:
            if cod == "demo":
                p = PlanComercial.query.filter_by(codigo="piloto").first()
            if not p:
                p = PlanComercial(codigo=cod)
                db.session.add(p)
                force_this = True
            else:
                p.codigo = cod
                force_this = force
        else:
            force_this = force
        _es_nuevo = p.id is None  # solo un plan recién creado nace activo; después decide Gerencia
        feats = {
            "incluidos": d["incluidos"],
            "excluidos": d.get("excluidos") or [],
            "tagline": d.get("tagline") or "",
            "soporte": d.get("soporte") or "",
            "vigencia": d.get("vigencia") or "",
            "nota_qr": d.get("nota_qr") or "",
            "badge": d.get("badge") or "PLAN",
            "linea": d.get("linea") or ("qr" if str(d.get("codigo") or "").startswith("qr") else ""),
        }
        if force_this or not p.features_json:
            p.nombre = d["nombre"] or p.nombre
            # NO pisar precios/fee editados en Gerencia (ventas en vivo)
            try:
                _pm = float(p.precio_mensual or 0)
            except Exception:
                _pm = 0.0
            try:
                _fee = float(p.fee_implementacion or 0)
            except Exception:
                _fee = 0.0
            if _pm <= 0 and float(d.get("precio") or 0) > 0:
                p.precio_mensual = float(d["precio"])
            if _fee <= 0 and float(d.get("fee") or 0) > 0:
                p.fee_implementacion = float(d["fee"])
            # solo completar max si vacío
            if not p.max_estudiantes:
                p.max_estudiantes = int(d["max_e"] or 0)
            if not p.max_sedes or int(p.max_sedes or 0) < 1:
                p.max_sedes = int(d["max_s"] or 20)
            if not p.features_json:
                p.features_json = json.dumps(feats, ensure_ascii=False)
            elif force_this and not _pm:
                # solo features si no hay precio comercial
                try:
                    import json as _j
                    cur = _j.loads(p.features_json or "{}")
                    if not cur or (isinstance(cur, dict) and not cur.get("incluidos")):
                        p.features_json = json.dumps(feats, ensure_ascii=False)
                except Exception:
                    p.features_json = json.dumps(feats, ensure_ascii=False)
            if not p.orden:
                p.orden = int(d["orden"])
        # Alta nueva: sí aplicar catálogo completo
        if p.id is None or (force_this and float(p.precio_mensual or 0) <= 0 and float(d.get("precio") or 0) >= 0 and not p.nombre):
            p.nombre = d["nombre"]
            if float(p.precio_mensual or 0) <= 0:
                p.precio_mensual = float(d.get("precio") or 0)
            if float(p.fee_implementacion or 0) <= 0:
                p.fee_implementacion = float(d.get("fee") or 0)
        if _es_nuevo or p.activo is None:
            p.activo = True
        if not p.max_sedes:
            p.max_sedes = 20
        try:
            _cod = (p.codigo or "").lower()
            if _cod.startswith("qr") or (d.get("linea") or "") == "qr":
                import json as _j2
                _fx = {}
                try:
                    _fx = _j2.loads(p.features_json or "{}") or {}
                except Exception:
                    _fx = {}
                if not isinstance(_fx, dict):
                    _fx = {}
                if _fx.get("linea") != "qr":
                    _fx["linea"] = "qr"
                    if not _fx.get("badge"):
                        _fx["badge"] = d.get("badge") or "SOLO QR"
                    p.features_json = _j2.dumps(_fx, ensure_ascii=False)
        except Exception:
            pass
    # Los planes creados en Gerencia (p. ej. los online) conservan el estado que Gerencia les dé.
    # Antes se desactivaban aquí en cada visita por no estar en el catálogo oficial.
    # Sincronizar catálogo de add-ons (sin sede extra; sedes incluidas en plan)
    try:
        for cod_off in ("sede_extra", "sede"):
            a = AddonComercial.query.filter_by(codigo=cod_off).first()
            if a:
                a.activo = False
        def _upsert_addon(codigo, nombre, precio, desc, activo=True):
            a = AddonComercial.query.filter_by(codigo=codigo).first()
            if not a:
                a = AddonComercial(codigo=codigo)
                db.session.add(a)
            a.nombre = nombre
            a.precio_mensual = precio
            a.descripcion = desc
            a.activo = activo
        _upsert_addon("ia", "Asistente Pedagógico con IA (Varita Mágica)", 30000,
                      "Asistente pedagógico con inteligencia artificial", True)
        _upsert_addon("migracion_historico", "Migración de histórico completo", 150000,
                      "Migración e ingesta de datos históricos (años anteriores) — pago único", True)
        _upsert_addon("soporte_247", "Soporte prioritario 24/7", 50000,
                      "Mesa de ayuda prioritaria fines de semana y 24/7", True)
    except Exception as _ad:
        print("seed addons:", _ad)
    try:
        db.session.commit()
    except Exception as _e:
        db.session.rollback()
        print("seed planes:", _e)


