@app.route("/feature_flags", methods=["GET", "POST"])
def feature_flags():
    """Solo Gerencia/Dueño: no debe estar en manos de soporte técnico."""
    if not requiere_login() or rol_actual() not in ("Gerencia", "Gerente", "Administrador", "Superadmin"):
        return acceso_denegado("Feature flags solo los gestiona Gerencia / Dueño.")
    mensaje = ""
    inst_id = request.values.get("institucion_id") or ""
    try:
        inst_id_int = int(inst_id) if inst_id else None
    except ValueError:
        inst_id_int = None

    # Asegurar filas del catálogo
    for clave, desc, plan in FLAGS_CATALOGO:
        existe = FeatureFlag.query.filter_by(clave=clave, institucion_id=inst_id_int).first()
        if not existe:
            db.session.add(FeatureFlag(
                institucion_id=inst_id_int,
                clave=clave,
                activo=(plan == "Basico"),
                descripcion=desc,
                plan_minimo=plan,
            ))
    db.session.commit()

    if request.method == "POST":
        for clave, desc, plan in FLAGS_CATALOGO:
            f = FeatureFlag.query.filter_by(clave=clave, institucion_id=inst_id_int).first()
            if f:
                f.activo = request.form.get(f"flag_{clave}") == "on"
        db.session.commit()
        registrar_auditoria("Feature flags", f"Actualizó flags tenant={inst_id_int or 'GLOBAL'}")
