@app.route("/horarios/pdf")
def horarios_pdf():
    """PDF planilla institucional del horario del día."""
    if not requiere_login():
        return redirect("/login")
    if not puede_horarios():
        return acceso_denegado()
    dia = request.args.get("dia") or dia_semana_hoy()
    if dia not in DIAS_SEMANA:
        dia = dia_semana_hoy()
    fecha_horario = fecha_para_dia_semana(dia)
    iid = institucion_id_actual()
    cfg = config()
    # Reutilizar lógica de grados
    grados_filas = _grados_horario(institucion_id_actual())
    bloques = HorarioBloque.query.filter_by(institucion_id=iid, dia=dia).all() if iid is not None else HorarioBloque.query.filter_by(dia=dia).all()

    def clase_de_hora(hi):
        mapa = {"07:00": 1, "07:55": 2, "09:10": 3, "10:05": 4, "11:10": 5, "12:05": 6}
        return mapa.get((hi or "")[:5], 0)

    def get_mat(grado, cn):
        for b in bloques:
            bg = (b.grado or "").replace("°", "")
            gg = grado.replace("°", "")
            if bg == gg or b.grado == grado:
                if clase_de_hora(b.hora_inicio) == cn:
                    return (b.asignatura or "").upper()
        return "—"

    b = BytesIO()
    pdf = canvas.Canvas(b, pagesize=landscape(letter))
    width, height = landscape(letter)
    # Membrete
    pdf.setFillColor(colors.HexColor("#0B2D57"))
    pdf.rect(0, height - 48, width, 48, fill=1, stroke=0)
    try:
        pdf.drawImage(logo_fs(), 24, height - 42, width=30, height=30, preserveAspectRatio=True, mask="auto")
    except Exception:
        pass
    pdf.setFillColor(colors.white)
    pdf.setFont("Helvetica-Bold", 11)
    pdf.drawString(62, height - 26, (cfg.inst_nombre or INST_NOMBRE)[:65])
    pdf.setFont("Helvetica", 7)
    pdf.drawString(62, height - 38, f"{cfg.inst_resolucion or INST_RESOLUCION} · DANE {cfg.inst_dane or INST_DANE} · NIT {cfg.inst_nit or INST_NIT}")
    y = height - 62
    pdf.setFillColor(colors.HexColor("#0f172a"))
    pdf.setFont("Helvetica-Bold", 12)
    pdf.drawCentredString(width/2, y, f"HORARIO DE CLASE {dia.upper()} {fecha_horario}")
    y -= 14
    data = [["GRUPO", "CLASE 1", "CLASE 2", "CLASE 3", "CLASE 4", "CLASE 5", "CLASE 6"]]
    for grado in grados_filas:
        data.append([grado] + [get_mat(grado, cn) for cn in range(1, 7)])
    if len(data) == 1:
        data.append(["—"] + ["—"] * 6)
    col_w = [55] + [105] * 6
    table = Table(data, colWidths=col_w)
    table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#0B2D57")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 7.5),
        ("FONTNAME", (0, 1), (-1, -1), "Helvetica"),
        ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#64748B")),
        ("BACKGROUND", (0, 1), (0, -1), colors.HexColor("#F1F5F9")),
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
    ]))
    tw, th = table.wrap(width - 40, y - 80)
    table.drawOn(pdf, 20, max(55, y - th))
    # Notas
    notas = _notas_horario()
    pdf.setFont("Helvetica", 7)
    pdf.setFillColor(colors.HexColor("#334155"))
    pdf.drawString(24, 40, "LIBRE / XXXXX = clase libre · ACOMP: Nombre = acompañamiento docente")
    if notas:
        pdf.drawString(24, 28, (notas.replace("\n", " | "))[:140])
    pdf.setFont("Helvetica", 6.5)
    pdf.drawCentredString(width/2, 14, f"{APP_NAME} · Documento institucional · {DESARROLLADOR}")
    pdf.save()
    b.seek(0)
    return send_file(b, as_attachment=True, download_name=f"horario_{dia}_{fecha_horario}.pdf")


@app.route("/horarios/imagen")
def horarios_imagen():
    """Vista lista para guardar como imagen/foto o imprimir."""
    if not requiere_login():
        return redirect("/login")
    if not puede_horarios():
        return acceso_denegado()
    dia = request.args.get("dia") or dia_semana_hoy()
    if dia not in DIAS_SEMANA:
        dia = dia_semana_hoy()
    fecha_horario = fecha_para_dia_semana(dia)
    iid = institucion_id_actual()
    grados_filas = _grados_horario(iid)
    bloques = HorarioBloque.query.filter_by(institucion_id=iid, dia=dia).all() if iid else []

    def clase_de_hora(hi):
        mapa = {"06:30": 1, "07:25": 2, "08:20": 3, "09:15": 4, "10:30": 5, "11:25": 6,
                "07:00": 1, "07:55": 2, "08:50": 3, "09:45": 4, "10:40": 5, "11:35": 6}
        return mapa.get((hi or "")[:5], 0)

    def get_mat(grado, cn):
        for b in bloques:
            bg = (b.grado or "").replace("°", "")
            gg = grado.replace("°", "")
            if bg == gg or b.grado == grado:
                if clase_de_hora(b.hora_inicio) == cn:
                    return (b.asignatura or "").upper()
        return ""

    rows = ""
    for grado in grados_filas:
        tds = "".join(f"<td>{get_mat(grado, cn) or '—'}</td>" for cn in range(1, 7))
        rows += f"<tr><td class='g'>{grado}</td>{tds}</tr>"
    notas = _notas_horario()
    notas_p = "".join(f"<p>{line.strip()}</p>" for line in (notas or "").splitlines() if line.strip())
    cfg = config()
    nombre_inst = (cfg.inst_nombre if cfg else "") or APP_NAME
    logo = logo_actual()
    html = f"""<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8"><title>Horario {dia}</title>
<style>
body{{font-family:Segoe UI,Arial,sans-serif;background:#e2e8f0;margin:0;padding:20px;color:#0f172a}}
.sheet{{max-width:960px;margin:0 auto;background:#fff;padding:24px 28px;box-shadow:0 8px 30px rgba(0,0,0,.12)}}
.head{{text-align:center;border-bottom:2px solid #0B2D57;padding-bottom:12px;margin-bottom:16px;display:flex;align-items:center;justify-content:center;gap:14px}}
.head img{{width:56px;height:56px;object-fit:contain}}
.head h1{{margin:0;font-size:20px;color:#0B2D57;letter-spacing:.03em}}
.head p{{margin:4px 0 0;font-size:12px;color:#64748b}}
table{{width:100%;border-collapse:collapse;font-size:13px}}
th{{background:#0B2D57;color:#fff;padding:10px 6px;border:1px solid #0B2D57;font-size:11px}}
td{{border:1px solid #64748b;padding:9px 5px;text-align:center;font-weight:600;text-transform:uppercase}}
td.g{{background:#e8eef6;font-weight:800;color:#0B2D57}}
.notes{{margin-top:18px;font-size:13px;font-style:italic;line-height:1.5}}
.notes h3{{font-style:normal;font-size:13px;color:#0B2D57;text-decoration:underline;margin:0 0 6px}}
.foot{{margin-top:16px;font-size:10px;color:#94a3b8;text-align:center}}
.bar{{text-align:center;margin-bottom:14px}}
.bar button{{padding:10px 16px;margin:4px;border:0;border-radius:8px;background:#0B2D57;color:#fff;font-weight:700;cursor:pointer}}
@media print{{.bar{{display:none}} body{{background:#fff;padding:0}} .sheet{{box-shadow:none;max-width:none}}}}
</style></head><body>
<div class="bar">
  <button onclick="window.print()">Imprimir / Guardar como PDF</button>
  <button onclick="descargarPng()">Descargar como imagen PNG</button>
  <button onclick="window.close()" style="background:#64748b">Cerrar</button>
</div>
<div class="sheet" id="sheet">
  <div class="head">
    <img src="{logo}" alt="">
    <div>
      <h1>HORARIO DE CLASE {dia.upper()} {fecha_horario}</h1>
      <p>{nombre_inst}</p>
    </div>
  </div>
  <table>
    <tr><th>GRUPO</th><th>CLASE 1</th><th>CLASE 2</th><th>CLASE 3</th><th>CLASE 4</th><th>CLASE 5</th><th>CLASE 6</th></tr>
    {rows or '<tr><td colspan="7">Sin grupos</td></tr>'}
  </table>
  <div class="notes"><h3>Notas / acompañamiento</h3>{notas_p or '<p>Sin notas.</p>'}</div>
  <div class="foot">{APP_NAME} · Documento institucional · PROCSIS</div>
</div>
<script src="https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js"></script>
<script>
async function descargarPng(){{
  const el=document.getElementById('sheet');
  const canvas=await html2canvas(el,{{scale:2,backgroundColor:'#ffffff'}});
  const a=document.createElement('a');
  a.download='horario_{dia}_{fecha_horario}.png';
  a.href=canvas.toDataURL('image/png');
  a.click();
}}
</script>
</body></html>"""
    return html






