@app.route("/notas/logros", methods=["GET", "POST"])
def notas_logros():
    if not requiere_login():
        return redirect("/login")
    iid = institucion_id_actual()
    mensaje = ""
    if request.method == "POST":
        codigo = (request.form.get("codigo") or "").strip()
        desc = (request.form.get("descripcion") or "").strip()
        if codigo and desc:
            db.session.add(LogroAcademico(
                institucion_id=iid,
                codigo=codigo,
                descripcion=desc,
                asignatura=(request.form.get("asignatura") or "").strip(),
                grado=(request.form.get("grado") or "").strip(),
                periodo=periodo_actual(),
            ))
            db.session.commit()
            mensaje = "Logro guardado."
        elif request.form.get("eliminar_id"):
            try:
                lid = int(request.form.get("eliminar_id"))
                L = LogroAcademico.query.get(lid)
                if L and (L.institucion_id == iid or rol_actual() == "Soporte"):
                    db.session.delete(L)
                    db.session.commit()
                    mensaje = "Logro eliminado."
            except Exception:
                pass
    lista = LogroAcademico.query.filter_by(institucion_id=iid).order_by(LogroAcademico.codigo.asc()).all()
    filas = "".join(
        f"<tr><td><b>{l.codigo}</b></td><td>{_esc(l.descripcion)}</td><td>{l.asignatura or '—'}</td><td>{l.grado or '—'}</td>"
        f"<td><form method='POST' style='display:inline' onsubmit=\"return confirm('¿Eliminar?')\">"
        f"<input type='hidden' name='eliminar_id' value='{l.id}'><button class='btn-red' style='padding:4px 8px;font-size:11px'>Eliminar</button></form></td></tr>"
        for l in lista
    ) or "<tr><td colspan='5'>Aún no hay logros. Crea el primero abajo.</td></tr>"
    content = f"""
<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:8px">
  <div><h1 style="margin:0;font-size:20px">Banco de logros</h1>
  <p class="mini-text" style="margin:4px 0 0">Códigos cortos para planilla y boletines</p></div>
  <a class="btn" href="/docente-escritorio">← Inicio panel</a>
</div>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
<section class="role-panel" style="margin-bottom:14px">
<form method="POST" class="form-row" style="display:grid;grid-template-columns:100px 1fr 120px 80px auto;gap:8px;align-items:end">
  <div><label><b>Código</b></label><input name="codigo" placeholder="L01" required></div>
  <div><label><b>Descripción</b></label><input name="descripcion" placeholder="Identifica las partes de la célula" required></div>
  <div><label><b>Asignatura</b></label><input name="asignatura" placeholder="Biología"></div>
  <div><label><b>Grado</b></label><input name="grado" placeholder="8"></div>
  <button>Agregar</button>
</form>
</section>
<section class="table-card">
<table><tr><th>Código</th><th>Descripción</th><th>Asignatura</th><th>Grado</th><th></th></tr>{filas}</table>
</section>
"""
    return page("Logros", shell(content))


@app.route("/notas/refuerzos", methods=["GET", "POST"])
def notas_refuerzos():
    if not requiere_login():
        return redirect("/login")
    iid = institucion_id_actual()
    mensaje = ""
    if request.method == "POST":
        codigo = (request.form.get("codigo_est") or "").strip()
        est = q_estudiantes().filter(func.lower(Estudiante.codigo) == codigo.lower()).first() if codigo else None
        if est:
            try:
                nota = float(request.form.get("nota_actual") or 0)
            except Exception:
                nota = None
            db.session.add(RefuerzoAcademico(
                institucion_id=iid,
                estudiante_id=est.id,
                asignatura=(request.form.get("asignatura") or "").strip(),
                periodo=periodo_actual(),
                nota_actual=nota,
                actividad=(request.form.get("actividad") or "").strip(),
                fecha=fecha_hoy(),
                estado=(request.form.get("estado") or "Pendiente").strip(),
                registrado_por=session.get("usuario", ""),
            ))
            db.session.commit()
            mensaje = f"Refuerzo registrado para {est.nombre} {est.apellido}."
        else:
            mensaje = "Estudiante no encontrado (usa el código)."
    regs = RefuerzoAcademico.query.filter_by(institucion_id=iid).order_by(RefuerzoAcademico.id.desc()).limit(100).all()
    filas = ""
    for r in regs:
        e = Estudiante.query.get(r.estudiante_id)
        nom = f"{e.apellido} {e.nombre}" if e else "—"
        filas += f"<tr><td>{r.fecha}</td><td>{e.codigo if e else '—'}</td><td>{nom}</td><td>{r.asignatura}</td><td>{r.nota_actual if r.nota_actual is not None else '—'}</td><td>{r.actividad}</td><td>{r.estado}</td></tr>"
    if not filas:
        filas = "<tr><td colspan='7'>Sin refuerzos registrados.</td></tr>"
    content = f"""
<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:8px">
  <div><h1 style="margin:0;font-size:20px">Refuerzos académicos</h1>
  <p class="mini-text" style="margin:4px 0 0">Seguimiento de recuperación</p></div>
  <a class="btn" href="/docente-escritorio">← Inicio panel</a>
</div>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje and 'registrado' in mensaje else ""}
{"<div class='msg danger'>"+mensaje+"</div>" if mensaje and 'registrado' not in mensaje else ""}
<section class="role-panel" style="margin-bottom:14px">
<form method="POST">
  <div class="form-row">
    <div><label><b>Código estudiante</b></label><input name="codigo_est" required placeholder="2024001"></div>
    <div><label><b>Asignatura</b></label><input name="asignatura" placeholder="Matemáticas"></div>
    <div><label><b>Nota actual</b></label><input name="nota_actual" type="number" step="0.01" min="0" max="5" placeholder="2.8"></div>
    <div><label><b>Estado</b></label><select name="estado"><option>Pendiente</option><option>En curso</option><option>Cerrado</option></select></div>
  </div>
  <label><b>Actividad de refuerzo</b></label>
  <textarea name="actividad" rows="2" placeholder="Taller de fracciones, refuerzo sábado..."></textarea>
  <button>Registrar refuerzo</button>
</form>
</section>
<section class="table-card">
<table><tr><th>Fecha</th><th>Código</th><th>Estudiante</th><th>Asignatura</th><th>Nota</th><th>Actividad</th><th>Estado</th></tr>{filas}</table>
</section>
"""
    return page("Refuerzos", shell(content))


@app.route("/notas/informes")
def notas_informes():
    if not requiere_login():
        return redirect("/login")
    if rol_actual() == "Docente":
        return acceso_denegado("Los boletines PDF los genera Secretaría / Coordinación / Rectoría.")
    grado = (request.args.get("grado") or "").strip()
    opts = "".join(f'<option value="{g}" {"selected" if g==grado else ""}>{g}</option>' for g in grados_disponibles())
    ests = q_estudiantes()
    if grado:
        ests = ests.filter(Estudiante.grado == grado)
    ests = ests.order_by(Estudiante.apellido.asc()).limit(150).all()
    filas = "".join(
        f"<tr><td>{e.codigo}</td><td>{e.apellido} {e.nombre}</td><td>{e.grado}</td>"
        f"<td><a class='btn small-action' href='/notas/boletin/{e.id}' target='_blank'>PDF boletín</a> "
        f"<a class='btn small-action' href='/notas/ficha?est={e.id}'>Ficha</a></td></tr>"
        for e in ests
    ) or "<tr><td colspan='4'>Sin estudiantes</td></tr>"
    content = f"""
<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:8px">
  <div><h1 style="margin:0;font-size:20px">Boletines e informes</h1>
  <p class="mini-text" style="margin:4px 0 0">PDF listo para imprimir o guardar</p></div>
  <a class="btn" href="/docente-escritorio">← Inicio panel</a>
</div>
<form method="GET" style="margin-bottom:12px;display:flex;gap:8px;align-items:end">
  <div><label><b>Grado</b></label><select name="grado" onchange="this.form.submit()"><option value="">Todos</option>{opts}</select></div>
</form>
<section class="table-card">
<table><tr><th>Código</th><th>Estudiante</th><th>Grado</th><th>Acciones</th></tr>{filas}</table>
</section>
"""
    return page("Boletines", shell(content))





@app.route("/notas/boletin/<int:id>")
def notas_boletin_pdf(id):
    """Boletín académico informativo — diseño institucional (landscape)."""
    if not requiere_login() and not session.get("familia"):
        return redirect("/login")
    # Portal familiar: solo su(s) estudiante(s)
    if session.get("familia"):
        allowed = session.get("familia_est_ids") or [session.get("familia_est_id")]
        if id not in allowed and int(id) not in [int(x) for x in allowed if x]:
            return acceso_denegado("Solo puede descargar el boletín de su(s) hijo(s).")
    elif rol_actual() == "Docente":
        return acceso_denegado("La descarga de boletines PDF es para Secretaría, Coordinación o Rectoría.")
    e = Estudiante.query.get_or_404(id)
    iid = institucion_id_actual() or e.institucion_id
    if not session.get("familia"):
        if iid is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid):
            return acceso_denegado()

    periodo = request.args.get("periodo") or periodo_actual()
    # Map periodo to P1/P2/P3
    per_key = "P1"
    if "2" in periodo:
        per_key = "P2"
    elif "3" in periodo:
        per_key = "P3"
    elif "4" in periodo or "Final" in periodo:
        per_key = "P4"
    peso_periodo = {"P1": 30.0, "P2": 30.0, "P3": 40.0, "P4": 0.0}.get(per_key, 30.0)

    regs = NotaRegistro.query.filter_by(estudiante_id=e.id, institucion_id=iid).all()

    # Catálogo completo del grado + cualquier materia con notas (todas deben aparecer)
    try:
        catalogo = [m for m in (materias_para_grado(e.grado) or []) if m and m != "General"]
    except Exception:
        catalogo = []
    if not catalogo:
        catalogo = [
            "Matemáticas", "Humanidades / Lengua Castellana", "Idioma Extranjero (Inglés)",
            "Ciencias Naturales", "Ciencias Sociales", "Educación Física, Recreación y Deportes",
            "Educación Artística y Cultural", "Educación Ética y en Valores Humanos",
            "Educación Religiosa", "Tecnología e Informática",
        ]
    con_notas = sorted({(r.asignatura or "").strip() for r in regs if (r.asignatura or "").strip() and r.asignatura != "General"})
    asignaturas = []
    seen = set()
    for a in catalogo + con_notas:
        key = a.lower()
        if key not in seen:
            asignaturas.append(a)
            seen.add(key)

    def _match_asig(a, asig):
        a = (a or "").strip().upper()
        b = (asig or "").strip().upper()
        if not a or not b:
            return False
        if a == b:
            return True
        # coincidencia flexible: "Humanidades / Lengua Castellana" vs "Lengua Castellana"
        return a in b or b in a

    def nota_materia_periodo(asig, per_name):
        # Usar criterios de ESA materia (no los de General)
        try:
            dim_slots_m, _ = ensure_siee_schema(iid, asig)
        except Exception:
            dim_slots_m = []
        nmap = {}
        vals_simple = []
        for r in regs:
            if r.valor is None:
                continue
            if (r.periodo or "") != per_name:
                continue
            if not _match_asig(r.asignatura, asig):
                continue
            try:
                fv = float(r.valor)
            except Exception:
                continue
            vals_simple.append(fv)
            if r.criterio_id:
                nmap[(e.id, r.criterio_id)] = fv
        n = None
        if dim_slots_m and nmap:
            n, _, _cerrado_tmp, _forzado_tmp = calc_nota_periodo(e.id, dim_slots_m, nmap)
        if n is None and vals_simple:
            n = sum(vals_simple) / len(vals_simple)
        return n

    def des_txt(n):
        lab, _ = desempeno_label(n)
        return lab

    # Intensidad horaria estimada por materia (IH)
    IH_DEFAULT = {
        "MATEMÁTICAS": 5, "MATEMATICAS": 5,
        "LENGUA CASTELLANA": 5, "HUMANIDADES": 5, "ESPAÑOL": 5,
        "INGLÉS": 3, "INGLES": 3, "IDIOMA EXTRANJERO": 3,
        "CIENCIAS NATURALES": 4, "BIOLOGÍA": 4, "BIOLOGIA": 4, "FÍSICA": 3, "FISICA": 3, "QUÍMICA": 3, "QUIMICA": 3,
        "CIENCIAS SOCIALES": 4, "HISTORIA": 3, "GEOGRAFÍA": 2,
        "EDUCACIÓN FÍSICA": 2, "EDUCACION FISICA": 2,
        "EDUCACIÓN ARTÍSTICA": 2, "EDUCACION ARTISTICA": 2,
        "EDUCACIÓN RELIGIOSA": 1, "EDUCACION RELIGIOSA": 1,
        "ÉTICA": 1, "ETICA": 1, "TECNOLOGÍA": 2, "TECNOLOGIA": 2, "INFORMÁTICA": 2,
        "EMPRENDIMIENTO": 1, "FILOSOFÍA": 2, "FILOSOFIA": 2,
    }

    def ih_for(asig):
        u = (asig or "").upper()
        for k, v in IH_DEFAULT.items():
            if k in u:
                return v
        return 2

    # Faltas (simplificado: no justificadas = No llegó; justificadas no tipificadas → 0)
    try:
        nj = IngresoPorteria.query.filter_by(estudiante_id=e.id, estado="No llegó").count()
    except Exception:
        nj = 0
    fj = 0
    llegadas_tarde = 0
    try:
        llegadas_tarde = IngresoPorteria.query.filter_by(estudiante_id=e.id, estado="Tarde").count()
    except Exception:
        pass

    # Docente por materia (asignaciones)
    docente_map = {}
    try:
        for ad in AsignacionDocente.query.filter_by(institucion_id=iid, activa=True).all():
            if ad.grado and e.grado:
                if str(ad.grado).strip() != str(e.grado).strip() and str(ad.grado).strip() not in str(e.grado):
                    continue
            u = Usuario.query.get(ad.usuario_id)
            if u and ad.asignatura:
                docente_map[ad.asignatura.strip().upper()] = (u.usuario or "").strip()
    except Exception:
        docente_map = {}

    def docente_de(asig):
        u = (asig or "").strip().upper()
        if u in docente_map:
            return docente_map[u]
        for k, v in docente_map.items():
            if k in u or u in k:
                return v
        return ""

    # Filas de materias
    rows_data = []
    for asig in asignaturas:
        p1 = nota_materia_periodo(asig, "Periodo 1")
        p2 = nota_materia_periodo(asig, "Periodo 2")
        p3 = nota_materia_periodo(asig, "Periodo 3")
        # nota del periodo solicitado
        if per_key == "P1":
            p_act = p1
        elif per_key == "P2":
            p_act = p2
        elif per_key == "P3":
            p_act = p3
        else:
            p_act = nota_materia_periodo(asig, periodo)

        # acumulado parcial ponderado con lo disponible
        partes = []
        if p1 is not None:
            partes.append((p1, 30.0))
        if p2 is not None:
            partes.append((p2, 30.0))
        if p3 is not None:
            partes.append((p3, 40.0))
        if partes:
            acum = sum(n * w for n, w in partes) / sum(w for _, w in partes)
        else:
            acum = p_act

        # NM = mínimo necesario en próximos periodos para aprobar año (>= 3.0)
        # Si falta peso, calcula nota mínima requerida en el resto
        nm = None
        peso_hecho = sum(w for _, w in partes)
        if peso_hecho < 100 and acum is not None:
            peso_rest = 100 - peso_hecho
            # queremos nota final >= 3.0 → (acum*peso_hecho + nm*peso_rest)/100 >= 3
            # nm >= (3*100 - acum*peso_hecho) / peso_rest
            if peso_rest > 0:
                nm = max(0.0, min(5.0, (3.0 * 100 - acum * peso_hecho) / peso_rest))
        elif acum is not None:
            nm = 0.0 if acum >= 3.0 else 3.0

        # faltas planilla de esa materia
        nj_m, fj_m = "", ""
        try:
            fps = FaltaPlanilla.query.filter_by(
                estudiante_id=e.id, institucion_id=iid, periodo=periodo
            ).all()
            for fp in fps:
                if _match_asig(fp.asignatura, asig):
                    nj_m, fj_m = str(fp.nj or 0), str(fp.fj or 0)
                    break
        except Exception:
            pass
        rows_data.append({
            "asig": asig,
            "docente": docente_de(asig),
            "ih": ih_for(asig),
            "p_act": p_act,
            "des_p": des_txt(p_act) if p_act is not None else "—",
            "acum": acum,
            "des_acum": des_txt(acum) if acum is not None else "—",
            "nm": nm,
            "nj": nj_m,
            "fj": fj_m,
            "ac": "",
        })

    total_ih = sum(r["ih"] for r in rows_data) or 0
    notas_act = [r["p_act"] for r in rows_data if r["p_act"] is not None]
    prom_alumno = sum(notas_act) / len(notas_act) if notas_act else None

    # Promedio de grupo (mismo grado)
    prom_grupo = None
    try:
        compas = q_estudiantes().filter(Estudiante.grado == e.grado).limit(80).all()
        if compas:
            vals_g = []
            for c in compas:
                regs_c = NotaRegistro.query.filter_by(estudiante_id=c.id, institucion_id=iid, periodo=periodo).all()
                if not regs_c:
                    continue
                vv = [float(r.valor) for r in regs_c if r.valor is not None]
                if vv:
                    vals_g.append(sum(vv) / len(vv))
            if vals_g:
                prom_grupo = sum(vals_g) / len(vals_g)
    except Exception:
        prom_grupo = None

    # % rendimiento (sobre 5.0)
    pct_alum = (prom_alumno / 5.0 * 100) if prom_alumno is not None else None
    pct_grupo = (prom_grupo / 5.0 * 100) if prom_grupo is not None else None


    # PDF — Informe de Evaluación estilo planilla escolar clásica (como imagen de referencia)
    page_size = letter  # vertical, tipo boletín escolar
    w, h = page_size
    buf = BytesIO()
    pdf = canvas.Canvas(buf, pagesize=page_size)

    inst = None
    try:
        inst = Institucion.query.get(e.institucion_id) if e.institucion_id else None
    except Exception:
        inst = None
    if not inst and iid:
        try:
            inst = Institucion.query.get(iid)
        except Exception:
            inst = None
    mun = (getattr(inst, "municipio", None) or "") if inst else ""
    dane = (getattr(inst, "dane", None) or "") if inst else ""
    nit = (getattr(inst, "nit", None) or "") if inst else ""
    dir_inst = (getattr(inst, "direccion", None) or "") if inst else ""
    tel_inst = (getattr(inst, "telefono", None) or getattr(inst, "cel", None) or "") if inst else ""
    resol_raw = (getattr(inst, "resolucion", None) or "") if inst else ""
    # No mostrar datos comerciales (Asesor de ventas / plan) en documentos educativos
    _rr = (resol_raw or "").strip().lower()
    if (not _rr) or "asesor" in _rr or _rr.startswith("|"):
        resol = ""
    else:
        resol = resol_raw
    sede = (getattr(e, "sede", None) or (getattr(inst, "sede", None) if inst else None) or "Principal")
    grupo = (getattr(e, "grupo", None) or "—")
    nom_inst = ((inst.nombre if inst else None) or "INSTITUCIÓN EDUCATIVA").strip()
    lema_raw = getattr(inst, "lema", None) if inst else None
    if not lema_raw or (isinstance(lema_raw, str) and lema_raw.strip().lower().startswith("asesor")):
        lema = "Ciencia · Virtud · Disciplina"
    else:
        lema = lema_raw
    if isinstance(lema, str) and len(lema) > 60:
        lema = lema[:57] + "…"
    anio = ahora().year
    per_label = periodo if periodo else per_key
    doc_est = (getattr(e, "documento", None) or "—")
    cod_est = (e.codigo or "—")

    def _fmt(v):
        if v is None or v == "":
            return "—"
        try:
            return f"{float(v):.1f}"
        except Exception:
            return str(v)[:6]

    # —— Encabezado institucional ——
    ml, mr = 36, w - 36
    y = h - 40
    try:
        pdf.drawImage(logo_fs(), 40, h - 88, width=52, height=52, preserveAspectRatio=True, mask="auto")
    except Exception:
        pdf.setStrokeColor(colors.black)
        pdf.rect(40, h - 88, 52, 52, fill=0, stroke=1)
        pdf.setFont("Helvetica", 7)
        pdf.drawCentredString(66, h - 64, "LOGO")

    # Encabezado institucional (texto centrado; foto SOLO a la derecha, como boletín físico)
    pdf.setFillColor(colors.black)
    pdf.setFont("Helvetica-Bold", 11)
    pdf.drawCentredString(w / 2, h - 42, nom_inst.upper()[:70])
    pdf.setFont("Helvetica", 8)
    pdf.drawCentredString(w / 2, h - 54, str(lema)[:70])
    pdf.setFont("Helvetica", 7)
    linea_dane = f"Código Dane: {dane or '—'}  ·  Resolución: {resol or '—'}  ·  NIT: {nit or '—'}"
    pdf.drawCentredString(w / 2, h - 66, linea_dane[:95])
    pdf.drawCentredString(w / 2, h - 76, f"{dir_inst or '—'}  ·  Tel: {tel_inst or '—'}"[:95])
    if mun:
        pdf.drawCentredString(w / 2, h - 86, f"Municipio de {mun}"[:60])

    # FOTO del estudiante: esquina SUPERIOR DERECHA (mismo lado que boletín físico impreso)
    foto_p = (getattr(e, "foto_path", None) or "").strip()
    if foto_p:
        try:
            import os as _os
            local_foto = foto_p
            if local_foto.startswith("/"):
                local_foto = _os.path.join(app.root_path, local_foto.lstrip("/"))
            if _os.path.isfile(local_foto):
                fx = w - 88   # derecha
                fy = h - 100  # arriba
                fw, fh = 58, 70
                pdf.setStrokeColor(colors.black)
                pdf.setLineWidth(0.9)
                pdf.setFillColor(colors.white)
                pdf.rect(fx - 3, fy - 3, fw + 6, fh + 6, fill=1, stroke=1)
                pdf.drawImage(local_foto, fx, fy, width=fw, height=fh, preserveAspectRatio=True, mask="auto")
        except Exception:
            pass

    y = h - 100
    pdf.setStrokeColor(colors.black)
    pdf.setLineWidth(1.2)
    pdf.line(ml, y, mr, y)
    y -= 14
    pdf.setFont("Helvetica-Bold", 11)
    pdf.drawCentredString(w / 2, y, f"Informe de Evaluación - Periodo: {per_label} - Año: {anio}")
    y -= 13
    pdf.setFont("Helvetica-Bold", 9)
    pdf.drawCentredString(w / 2, y, f"Nombre: {estudiante_nombre(e)}")
    y -= 11
    pdf.setFont("Helvetica", 7)
    pdf.drawString(ml, y, "Juicios de Valoración: F: Fortaleza, D: Debilidad, R: Recomendación")
    y -= 10
    pdf.setFont("Helvetica", 7.5)
    prom_txt = f"{prom_alumno:.3f}" if prom_alumno is not None else "—"
    pdf.drawString(ml, y, f"Documento: {doc_est}   Promedio: {prom_txt}   Grado: {e.grado or '—'}   Salón: {grupo}   Sede: {sede}   Cod: {cod_est}")
    y -= 8
    pdf.setLineWidth(0.8)
    pdf.line(ml, y, mr, y)
    y -= 4

    # —— Tabla: columnas estilo imagen ——
    # AREA | IH | HISTORICO (N F x periodos simplificado) | Prom | NOTA | DESEMPEÑO | FALLAS
    # Anchos aproximados en puntos (carta ~540 útiles)
    x0 = ml
    cols = [
        ("AREA/ASIGNATURA", 168),
        ("IH", 22),
        ("N", 28), ("F", 18),
        ("N", 28), ("F", 18),
        ("N", 28), ("F", 18),
        ("N", 28), ("F", 18),
        ("Prom", 32),
        ("NOTA", 36),
        ("DESEMPEÑO", 58),
        ("FALLAS", 36),
    ]
    # Recalcular si sobra/falta
    total_cw = sum(c[1] for c in cols)
    scale = (mr - ml) / total_cw if total_cw else 1
    cols = [(n, w_ * scale) for n, w_ in cols]

    def draw_header_row(y_top):
        pdf.setFillColor(colors.HexColor("#e5e5e5"))
        pdf.rect(x0, y_top - 28, mr - ml, 28, fill=1, stroke=1)
        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica-Bold", 6)
        # fila superior HISTORICO
        xa = x0 + cols[0][1] + cols[1][1]
        hist_w = sum(c[1] for c in cols[2:10])
        pdf.drawCentredString(xa + hist_w / 2, y_top - 10, "HISTORICO")
        # etiquetas inferiores
        x = x0
        labels_bottom = ["AREA/ASIGNATURA", "IH", "N", "F", "N", "F", "N", "F", "N", "F", "Prom", "NOTA", "DESEMPEÑO", "FALLAS"]
        for i, (lab, cw) in enumerate(cols):
            pdf.setFont("Helvetica-Bold", 5.5)
            pdf.drawCentredString(x + cw / 2, y_top - 22, labels_bottom[i] if i < len(labels_bottom) else lab)
            pdf.setStrokeColor(colors.black)
            pdf.setLineWidth(0.4)
            pdf.line(x, y_top, x, y_top - 28)
            x += cw
        pdf.line(mr, y_top, mr, y_top - 28)
        return y_top - 28

    y = draw_header_row(y)

    for idx, r in enumerate(rows_data):
        # bloque materia: fila principal + 3 juicios + docente
        block_h = 52
        if y - block_h < 70:
            pdf.showPage()
            y = h - 40
            pdf.setFont("Helvetica-Bold", 9)
            pdf.drawCentredString(w / 2, y, f"Informe de Evaluación (cont.) — {estudiante_nombre(e)[:40]}")
            y -= 16
            y = draw_header_row(y)

        nota = r.get("p_act")
        acum = r.get("acum")
        des = (r.get("des_p") or r.get("des_acum") or "—")[:12]
        nj = r.get("nj", "") or "0"
        fj = r.get("fj", "") or "0"
        # Histórico: usar p1/p2/p3 si están en rows — recalcular rápido
        p1 = nota_materia_periodo(r["asig"], "Periodo 1")
        p2 = nota_materia_periodo(r["asig"], "Periodo 2")
        p3 = nota_materia_periodo(r["asig"], "Periodo 3")
        p4 = nota_materia_periodo(r["asig"], "Periodo 4")
        hist_vals = [p1, p2, p3, p4]
        prom_hist = None
        hv = [float(v) for v in hist_vals if v is not None]
        if hv:
            prom_hist = sum(hv) / len(hv)

        # fila principal sombreada
        pdf.setFillColor(colors.HexColor("#f3f4f6"))
        pdf.rect(x0, y - 14, mr - ml, 14, fill=1, stroke=1)
        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica-Bold", 7)
        vals_row = [
            (r.get("asig") or "")[:34],
            str(r.get("ih") or ""),
            _fmt(p1), " ",
            _fmt(p2), " ",
            _fmt(p3), " ",
            _fmt(p4), " ",
            _fmt(prom_hist if prom_hist is not None else acum),
            _fmt(nota),
            des,
            str(nj) if str(nj) != "" else "0",
        ]
        x = x0
        for i, cw in enumerate([c[1] for c in cols]):
            txt = vals_row[i] if i < len(vals_row) else ""
            if i == 0:
                pdf.setFont("Helvetica-Bold", 7)
                pdf.drawString(x + 3, y - 10, str(txt))
            else:
                pdf.setFont("Helvetica", 7)
                pdf.drawCentredString(x + cw / 2, y - 10, str(txt))
            pdf.setStrokeColor(colors.black)
            pdf.setLineWidth(0.3)
            pdf.line(x, y, x, y - 14)
            x += cw
        pdf.line(mr, y, mr, y - 14)
        y -= 14

        # Juicios (texto tipo Cognitivo / R)
        juicios = [
            ("Cognitivo", "Desarrolla procesos con operaciones básicas"),
            ("Cognitivo R", "No cumple con todas las tareas y algunas las desarrolla incorrectamente"),
            ("Cognitivo R", "Algunas veces incumple con frecuencia los horarios establecidos"),
        ]
        # Si hay observación en planilla, usarla
        try:
            obs_r = [rr for rr in regs if _match_asig(rr.asignatura, r["asig"]) and (rr.observacion or "").strip()]
            if obs_r:
                juicios = [("Observación", (obs_r[0].observacion or "")[:90])]
        except Exception:
            pass

        for j_lab, j_txt in juicios[:3]:
            pdf.setStrokeColor(colors.black)
            pdf.setLineWidth(0.3)
            pdf.rect(x0, y - 11, mr - ml, 11, fill=0, stroke=1)
            pdf.setFont("Helvetica", 6)
            pdf.drawString(x0 + 4, y - 8, f"{j_lab}   {j_txt}"[:110])
            y -= 11

        # Docente al margen derecho del bloque
        docn = (r.get("docente") or "").strip()
        if docn:
            pdf.setFont("Helvetica-Oblique", 6.5)
            pdf.drawRightString(mr - 4, y + 2, docn[:36])

        y -= 4

    # Pie: promedios y firma
    if y < 90:
        pdf.showPage()
        y = h - 50
    y -= 6
    pdf.setLineWidth(0.8)
    pdf.line(ml, y, mr, y)
    y -= 12
    pdf.setFont("Helvetica-Bold", 8)
    pdf.drawString(ml, y, f"Promedio alumno periodo: {prom_alumno:.2f}" if prom_alumno is not None else "Promedio alumno periodo: —")
    pdf.drawString(ml + 200, y, f"Promedio de grupo: {prom_grupo:.2f}" if prom_grupo is not None else "Promedio de grupo: —")
    if pct_alum is not None:
        pdf.drawString(ml + 360, y, f"% rendimiento: {pct_alum:.0f}%")
    y -= 14
    pdf.setFont("Helvetica", 8)
    pdf.drawString(ml, y, f"Director de grupo: {(e.director or '—')[:45]}")
    y -= 22
    pdf.line(ml, y, ml + 160, y)
    pdf.line(mr - 160, y, mr, y)
    y -= 10
    pdf.setFont("Helvetica", 7)
    pdf.drawString(ml, y, "Firma director de grupo")
    pdf.drawRightString(mr, y, "Firma acudiente")
    y -= 16
    pdf.setFont("Helvetica", 6)
    pdf.setFillColor(colors.HexColor("#555555"))
    pdf.drawCentredString(w / 2, 28, f"EduTrack · PROCSIS  ·  Generado {ahora().strftime('%d/%m/%Y %H:%M')}  ·  Documento informativo institucional")

    pdf.save()
    buf.seek(0)
    return send_file(
        buf, as_attachment=True,
        download_name=f"boletin_{e.codigo}_{periodo.replace(' ', '_')}.pdf",
        mimetype="application/pdf",
    )


@app.route("/notas/boletin/<int:id>/final")
def notas_informe_final_pdf(id):
    """Informe final de desempeño (último periodo / cierre de año)."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() == "Docente":
        return acceso_denegado("Informe final disponible para Secretaría, Coordinación o Rectoría.")
    e = Estudiante.query.get_or_404(id)
    iid = institucion_id_actual()
    if iid is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid):
        return acceso_denegado()
    # Reutiliza lógica del boletín con periodo Final / P3
    periodo = request.args.get("periodo") or "Periodo 3"
    # Forzar consulta al mismo generador con estilo final
    from flask import redirect as _redir
    # Generar PDF propio consolidado
    inst = Institucion.query.get(iid) if iid else None
    mun = (getattr(inst, "municipio", None) or "") if inst else ""
    dane = (getattr(inst, "dane", None) or "") if inst else ""
    nit = (getattr(inst, "nit", None) or "") if inst else ""
    nom_inst = (inst.nombre if inst else None) or INST_NOMBRE or "INSTITUCIÓN EDUCATIVA"
    sede = getattr(e, "sede", None) or (getattr(inst, "sede", None) if inst else None) or "PRINCIPAL"
    jornada = getattr(e, "jornada", None) or "MAÑANA"
    grupo = getattr(e, "grupo", None) or "01"
    modelo = getattr(e, "modelo_educativo", None) or "POSTPRIMARIA"

    try:
        catalogo = [m for m in (materias_para_grado(e.grado) or []) if m and m != "General"]
    except Exception:
        catalogo = []
    if not catalogo:
        catalogo = ["Matemáticas", "Lengua Castellana", "Inglés", "Ciencias Naturales", "Ciencias Sociales",
                    "Educación Física", "Educación Artística", "Ética", "Religión", "Tecnología"]

    periodos_try = ["Periodo 1", "Periodo 2", "Periodo 3", "1", "2", "3", periodo_actual()]
    # Collect grades per subject from NotaRegistro
    regs = NotaRegistro.query.filter_by(estudiante_id=e.id).all()
    if iid is not None:
        regs = [r for r in regs if r.institucion_id is None or int(r.institucion_id) == int(iid)]

    def _des(n):
        if n is None:
            return "—"
        if n >= 4.6:
            return "SUPERIOR"
        if n >= 4.0:
            return "ALTO"
        if n >= 3.0:
            return "BÁSICO"
        return "BAJO"

    def _prom_asig(asig):
        vals = []
        for r in regs:
            if (r.asignatura or "").strip().lower() == (asig or "").strip().lower():
                try:
                    if r.valor is not None and float(r.valor) > 0:
                        vals.append(float(r.valor))
                except Exception:
                    pass
        if not vals:
            return None
        return sum(vals) / len(vals)

    page_size = landscape(letter)
    w, h = page_size
    buf = BytesIO()
    pdf = canvas.Canvas(buf, pagesize=page_size)
    y = h - 24
    try:
        pdf.drawImage(logo_fs(), 24, y - 20, width=40, height=40, preserveAspectRatio=True, mask="auto")
    except Exception:
        pass
    pdf.setStrokeColor(colors.HexColor("#0B2D57"))
    pdf.rect(20, y - 28, w - 40, 50, fill=0, stroke=1)
    pdf.setFont("Helvetica-Bold", 9)
    pdf.drawCentredString(w / 2, y + 12, (f"MUNICIPIO DE {mun}" if mun else "INSTITUCIÓN EDUCATIVA").upper()[:50])
    pdf.setFont("Helvetica-Bold", 11)
    pdf.drawCentredString(w / 2, y - 2, nom_inst.upper()[:55])
    pdf.setFont("Helvetica", 7)
    pdf.drawCentredString(w / 2, y - 14, f"Código DANE: {dane or '—'}  ·  NIT: {nit or '—'}")
    pdf.setFont("Helvetica-Bold", 9)
    pdf.drawCentredString(w / 2, y - 26, f"INFORME FINAL DE DESEMPEÑO  ·  Año lectivo {ahora().year}")
    y -= 58

    pdf.rect(20, y - 40, w - 40, 44, fill=0, stroke=1)
    pdf.setFont("Helvetica", 8)
    pdf.drawString(24, y - 12, f"Estudiante: {e.codigo}   {e.apellido.upper()} {e.nombre.upper()}")
    pdf.drawString(24, y - 24, f"Sede: {sede}   Modelo: {modelo}   Grado: {e.grado}   Grupo: {grupo}   Jornada: {jornada}")
    pdf.drawString(24, y - 36, f"N° matrícula: {getattr(e,'nro_matricula',None) or '—'}   Folio matrícula: {getattr(e,'folio_matricula',None) or '—'}   Documento: {getattr(e,'documento',None) or '—'}")
    y -= 52

    # Table consolidado
    headers = ["ÁREA / ASIGNATURA", "PROMEDIO", "DESEMPEÑO", "SITUACIÓN"]
    widths = [320, 70, 90, 110]
    x0 = 20
    pdf.setFillColor(colors.HexColor("#1e3a8a"))
    pdf.rect(x0, y - 14, sum(widths), 16, fill=1, stroke=0)
    pdf.setFillColor(colors.white)
    pdf.setFont("Helvetica-Bold", 8)
    x = x0
    for lab, ww in zip(headers, widths):
        pdf.drawString(x + 4, y - 10, lab)
        x += ww
    y -= 16
    pdf.setFillColor(colors.black)

    perdidas = 0
    proms = []
    for i, asig in enumerate(catalogo):
        if y < 70:
            pdf.showPage()
            y = h - 40
        prom = _prom_asig(asig)
        des = _des(prom)
        sit = "APROBADA" if (prom is not None and prom >= 3.0) else ("REPROBADA" if prom is not None else "SIN NOTA")
        if prom is not None and prom < 3.0:
            perdidas += 1
        if prom is not None:
            proms.append(prom)
        bg = colors.HexColor("#f8fafc") if i % 2 == 0 else colors.white
        pdf.setFillColor(bg)
        pdf.rect(x0, y - 14, sum(widths), 14, fill=1, stroke=0)
        pdf.setStrokeColor(colors.HexColor("#94a3b8"))
        pdf.rect(x0, y - 14, sum(widths), 14, fill=0, stroke=1)
        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica", 8)
        pdf.drawString(x0 + 4, y - 10, (asig or "")[:48])
        pdf.drawCentredString(x0 + widths[0] + widths[1] / 2, y - 10, f"{prom:.1f}" if prom is not None else "—")
        pdf.drawCentredString(x0 + widths[0] + widths[1] + widths[2] / 2, y - 10, des)
        pdf.drawCentredString(x0 + widths[0] + widths[1] + widths[2] + widths[3] / 2, y - 10, sit)
        y -= 14

    prom_gen = sum(proms) / len(proms) if proms else None
    if perdidas == 0 and prom_gen is not None and prom_gen >= 3.0:
        sit_final = "PROMOVIDO / APROBADO"
    elif perdidas > 0:
        sit_final = f"PENDIENTE / ÁREAS REPROBADAS: {perdidas}"
    else:
        sit_final = "SIN CALIFICAR"

    y -= 16
    pdf.setFont("Helvetica-Bold", 9)
    pdf.drawString(24, y, f"Consolidado general de calificaciones: {prom_gen:.2f}" if prom_gen is not None else "Consolidado general: —")
    y -= 14
    pdf.drawString(24, y, f"Situación académica final: {sit_final}")
    y -= 14
    pdf.setFont("Helvetica", 8)
    pdf.drawString(24, y, f"Director de grupo: {(e.director or '—')[:50]}")
    y -= 28
    pdf.drawString(24, y, "_________________________")
    pdf.drawString(280, y, "_________________________")
    y -= 12
    pdf.drawString(24, y, "Firma director de grupo")
    pdf.drawString(280, y, "Firma rectoría")
    pdf.setFont("Helvetica", 6)
    pdf.drawCentredString(w / 2, 16, "EduTrack · Informe final de desempeño · PROCSIS")
    pdf.save()
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name=f"informe_final_{e.codigo}_{ahora().year}.pdf", mimetype="application/pdf")


@app.route("/ficha_estudiante/<int:id>/pdf")
def ficha_estudiante_pdf(id):
    """Ficha del estudiante multipágina (portada, datos, historial, seguimiento, anotaciones)."""
    if not requiere_login():
        return redirect("/login")
    if not puede_ver_historial():
        return acceso_denegado()
    e = estudiante_del_tenant_or_404(id)
    iid = institucion_id_actual()
    inst = Institucion.query.get(e.institucion_id or iid) if (e.institucion_id or iid) else None
    nom_inst = (inst.nombre if inst else None) or INST_NOMBRE or "INSTITUCIÓN EDUCATIVA"
    mun = getattr(inst, "municipio", None) or ""
    dane = getattr(inst, "dane", None) or ""
    nit = getattr(inst, "nit", None) or ""
    sede = getattr(e, "sede", None) or (getattr(inst, "sede", None) if inst else None) or "PRINCIPAL"

    try:
        hist = HistorialMatricula.query.filter_by(estudiante_id=e.id).order_by(HistorialMatricula.anio.desc()).all()
    except Exception:
        hist = []
    try:
        anots = AnotacionEstudiante.query.filter_by(estudiante_id=e.id).order_by(AnotacionEstudiante.id.desc()).limit(40).all()
    except Exception:
        anots = []

    buf = BytesIO()
    pdf = canvas.Canvas(buf, pagesize=letter)
    w, h = letter

    def header_box(title):
        y = h - 36
        try:
            pdf.drawImage(logo_fs(), 40, y - 8, width=36, height=36, preserveAspectRatio=True, mask="auto")
        except Exception:
            pass
        pdf.setFont("Helvetica-Bold", 11)
        pdf.drawCentredString(w / 2, y + 10, nom_inst.upper()[:50])
        pdf.setFont("Helvetica", 8)
        pdf.drawCentredString(w / 2, y - 4, f"{mun}  ·  DANE: {dane or '—'}  ·  NIT: {nit or '—'}")
        pdf.setFont("Helvetica-Bold", 12)
        pdf.drawCentredString(w / 2, y - 22, title)
        pdf.setStrokeColor(colors.HexColor("#0B2D57"))
        pdf.line(40, y - 30, w - 40, y - 30)
        return y - 48

    # ---- HOJA 1: Portada ----
    y = header_box("FICHA DEL ESTUDIANTE — PORTADA")
    pdf.setFont("Helvetica-Bold", 14)
    pdf.drawCentredString(w / 2, y - 20, f"{e.apellido.upper()} {e.nombre.upper()}")
    pdf.setFont("Helvetica", 10)
    pdf.drawCentredString(w / 2, y - 40, f"Código: {e.codigo}   ·   Grado: {e.grado}   ·   Grupo: {getattr(e,'grupo',None) or '—'}")
    # foto
    pdf.setStrokeColor(colors.HexColor("#0B2D57"))
    pdf.rect(w / 2 - 50, y - 180, 100, 120, fill=0, stroke=1)
    pdf.setFont("Helvetica", 8)
    pdf.drawCentredString(w / 2, y - 120, "FOTO DEL ESTUDIANTE")
    foto = getattr(e, "foto_path", None) or ""
    if foto and os.path.exists(foto.replace("/static/", "static/") if foto.startswith("/static/") else foto):
        try:
            path = foto
            if foto.startswith("/static/"):
                path = os.path.join(app.root_path, foto.lstrip("/"))
            pdf.drawImage(path, w / 2 - 48, y - 178, width=96, height=116, preserveAspectRatio=True, mask="auto")
        except Exception:
            pass
    pdf.setFont("Helvetica", 9)
    pdf.drawCentredString(w / 2, y - 200, f"Sede: {sede}")
    pdf.drawCentredString(w / 2, y - 216, f"Año lectivo: {ahora().year}")
    pdf.drawCentredString(w / 2, y - 240, "EduTrack · PROCSIS")
    pdf.showPage()

    # ---- HOJA 2: Información del estudiante ----
    y = header_box("INFORMACIÓN DEL ESTUDIANTE")
    pdf.setFont("Helvetica", 9)
    lines = [
        f"Apellidos y nombres: {e.apellido} {e.nombre}",
        f"Tipo y documento: {getattr(e,'tipo_doc',None) or 'TI'} {getattr(e,'documento',None) or '—'}",
        f"Fecha de nacimiento: {getattr(e,'fecha_nacimiento',None) or '—'}   Género: {getattr(e,'genero',None) or '—'}   RH: {getattr(e,'rh',None) or '—'}",
        f"Dirección: {getattr(e,'direccion',None) or '—'}   Barrio: {getattr(e,'barrio',None) or '—'}",
        f"Municipio / Depto residencia: {getattr(e,'mun_res',None) or '—'} / {getattr(e,'dep_res',None) or '—'}",
        f"Zona: {getattr(e,'zona',None) or '—'}   Estrato: {getattr(e,'estrato',None) or '—'}   EPS: {getattr(e,'eps',None) or '—'}",
        f"Sisbén: {getattr(e,'sisben_grupo',None) or '—'}   Etnia: {getattr(e,'etnia',None) or '—'}",
        f"Discapacidad: {getattr(e,'discapacidad',None) or 'Ninguna'}",
        f"Acudiente: {getattr(e,'acudiente',None) or '—'}   Doc: {getattr(e,'acudiente_doc',None) or '—'}",
        f"Teléfono: {getattr(e,'telefono_acudiente',None) or '—'}   Correo: {getattr(e,'correo_acudiente',None) or '—'}",
        f"Padre: {getattr(e,'padre',None) or '—'}   Madre: {getattr(e,'madre',None) or '—'}",
        f"Grado actual: {e.grado}   Grupo: {getattr(e,'grupo',None) or '—'}   Jornada: {getattr(e,'jornada',None) or '—'}",
        f"N° matrícula: {getattr(e,'nro_matricula',None) or '—'}   Folio: {getattr(e,'folio_matricula',None) or '—'}",
        f"Director de grupo: {e.director or '—'}   Estado: {e.estado or 'ACTIVO'}",
    ]
    for line in lines:
        pdf.drawString(50, y, line[:95])
        y -= 16
        if y < 60:
            pdf.showPage()
            y = h - 50
    pdf.showPage()

    # ---- HOJA 3: Historial de matrícula ----
    y = header_box("HISTORIAL DE MATRÍCULA POR GRADO / AÑO")
    pdf.setFont("Helvetica-Bold", 8)
    pdf.drawString(50, y, "AÑO")
    pdf.drawString(100, y, "GRADO")
    pdf.drawString(160, y, "GRUPO")
    pdf.drawString(220, y, "SEDE")
    pdf.drawString(320, y, "ESTADO")
    pdf.drawString(400, y, "OBSERVACIÓN")
    y -= 4
    pdf.line(50, y, w - 50, y)
    y -= 14
    pdf.setFont("Helvetica", 8)
    if not hist:
        # fila actual
        pdf.drawString(50, y, str(ahora().year))
        pdf.drawString(100, y, str(e.grado))
        pdf.drawString(160, y, str(getattr(e, "grupo", None) or "—"))
        pdf.drawString(220, y, str(sede)[:16])
        pdf.drawString(320, y, str(e.estado or "ACTIVO"))
        pdf.drawString(400, y, "Registro actual")
        y -= 14
        pdf.setFont("Helvetica", 8)
        pdf.setFillColor(colors.HexColor("#64748b"))
        pdf.drawString(50, y - 10, "Puede registrar historial adicional desde la ficha del estudiante (próximas versiones / soporte).")
        pdf.setFillColor(colors.black)
    else:
        for hrow in hist:
            pdf.drawString(50, y, str(hrow.anio or ""))
            pdf.drawString(100, y, str(hrow.grado or ""))
            pdf.drawString(160, y, str(hrow.grupo or ""))
            pdf.drawString(220, y, str(hrow.sede or "")[:16])
            pdf.drawString(320, y, str(hrow.estado or "")[:12])
            pdf.drawString(400, y, str(hrow.observacion or "")[:28])
            y -= 14
            if y < 60:
                pdf.showPage()
                y = h - 50
    pdf.showPage()

    # ---- HOJA 4: Informe periódico / seguimiento matrícula ----
    y = header_box("INFORME DE SEGUIMIENTO DE MATRÍCULA")
    pdf.setFont("Helvetica", 9)
    for line in [
        f"Institución: {nom_inst}",
        f"Municipio: {mun}   DANE: {dane or '—'}   NIT: {nit or '—'}",
        f"Sede: {sede}   Año lectivo: {ahora().year}",
        f"Estudiante: {e.apellido} {e.nombre}   Código: {e.codigo}",
        f"Grado / Grupo: {e.grado} / {getattr(e,'grupo',None) or '—'}   Jornada: {getattr(e,'jornada',None) or '—'}",
        f"N° matrícula: {getattr(e,'nro_matricula',None) or '—'}   Folio: {getattr(e,'folio_matricula',None) or '—'}",
        f"Estado de matrícula: {e.estado or 'ACTIVO'}",
        "",
        "Seguimiento: el estudiante se encuentra registrado en el sistema EduTrack.",
        "Este informe sirve como constancia de seguimiento de matrícula y permanencia.",
        "",
        f"Generado: {ahora().strftime('%d/%m/%Y %H:%M')}",
    ]:
        pdf.drawString(50, y, line[:90])
        y -= 16
    y -= 30
    pdf.drawString(50, y, "___________________________          ___________________________")
    y -= 12
    pdf.drawString(50, y, "Secretaría                              Rectoría")
    pdf.showPage()

    # ---- HOJA 5: Registro de anotaciones ----
    y = header_box("REGISTRO DE ANOTACIONES")
    pdf.setFont("Helvetica-Bold", 8)
    pdf.drawString(50, y, "FECHA")
    pdf.drawString(110, y, "TIPO")
    pdf.drawString(180, y, "DESCRIPCIÓN")
    pdf.drawString(480, y, "REGISTRÓ")
    y -= 4
    pdf.line(50, y, w - 50, y)
    y -= 14
    pdf.setFont("Helvetica", 8)
    if not anots:
        obs = (getattr(e, "observacion", None) or "").strip()
        if obs:
            pdf.drawString(50, y, "—")
            pdf.drawString(110, y, "OBS.")
            pdf.drawString(180, y, obs[:50])
            y -= 14
        else:
            pdf.drawString(50, y, "Sin anotaciones registradas.")
    else:
        for a in anots:
            pdf.drawString(50, y, str(a.fecha or "")[:12])
            pdf.drawString(110, y, str(a.tipo or "")[:12])
            pdf.drawString(180, y, str(a.descripcion or "")[:48])
            pdf.drawString(480, y, str(a.registrado_por or "")[:14])
            y -= 14
            if y < 60:
                pdf.showPage()
                y = h - 50
    pdf.setFont("Helvetica", 7)
    pdf.drawCentredString(w / 2, 30, "EduTrack · Ficha del estudiante · PROCSIS")
    pdf.save()
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name=f"ficha_{e.codigo}.pdf", mimetype="application/pdf")



@app.route("/notas/ficha", methods=["GET", "POST"])
def notas_ficha():
    """Ficha de seguimiento: lista por grado + detalle del estudiante al abrir."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Docente", "Coordinación", "Rectoría", "Rector", "Secretaría", "Administrador", "Soporte"]:
        return acceso_denegado()
    from urllib.parse import quote as _q
    rol = rol_actual()
    es_doc = rol == "Docente"
    back = "/docente-escritorio" if es_doc else "/notas"
    msg = ""

    if request.method == "POST":
        try:
            est_id = int(request.form.get("estudiante_id") or 0)
            tipo = (request.form.get("tipo") or "observacion").strip()[:40]
            texto = (request.form.get("texto") or "").strip()[:2000]
            meta = (request.form.get("meta") or "").strip()[:500]
            falencia = (request.form.get("falencia") or "").strip()[:500]
            grado_post = (request.form.get("grado") or "").strip()
            if est_id and (texto or meta or falencia):
                cuerpo = texto
                if meta:
                    cuerpo = (cuerpo + " | Meta: " + meta).strip()
                if falencia:
                    cuerpo = (cuerpo + " | Falencia: " + falencia).strip()
                try:
                    obs = ObservacionBoletin(
                        estudiante_id=est_id,
                        institucion_id=institucion_id_actual(),
                        periodo=periodo_actual() or "Periodo 1",
                        texto=("[" + tipo.upper() + "] ") + cuerpo,
                        docente=session.get("usuario") or "",
                        actualizado=fecha_hoy() + " " + hora_actual(),
                        generado_auto=False,
                    )
                    db.session.add(obs)
                    db.session.commit()
                    msg = "Registro de seguimiento guardado."
                except Exception as ex_s:
                    try:
                        db.session.rollback()
                    except Exception:
                        pass
                    print("ficha save:", ex_s)
                    msg = "No se pudo guardar: " + str(ex_s)[:100]
                return redirect("/notas/ficha?grado=" + _q(grado_post) + "&est=" + str(est_id) + "&ok=1")
            else:
                msg = "Seleccione estudiante y escriba el seguimiento."
        except Exception as ex:
            msg = "Error: " + str(ex)[:100]

    if request.args.get("ok"):
        msg = msg or "Registro de seguimiento guardado."

    grado = (request.args.get("grado") or "").strip()
    est_id = request.args.get("est")
    e = None
    if est_id:
        try:
            e = Estudiante.query.get(int(est_id))
        except Exception:
            e = None
        if e is None:
            try:
                e = q_estudiantes().filter(Estudiante.id == int(est_id)).first()
            except Exception:
                e = None

    try:
        if es_doc:
            grs = list(grados_docente_actual() or []) or grados_disponibles()
        else:
            grs = grados_disponibles()
    except Exception:
        grs = grados_disponibles()

    lista = []
    if grado:
        try:
            g_norm = str(grado).replace("°", "").replace("º", "").strip()
            if g_norm.isdigit():
                g_norm = str(int(g_norm))
            from sqlalchemy import or_
            lista = (
                q_estudiantes()
                .filter(
                    or_(
                        Estudiante.grado == grado,
                        Estudiante.grado == g_norm,
                        Estudiante.grado.like(g_norm + "%"),
                        Estudiante.grado.like(g_norm + "°%"),
                    )
                )
                .order_by(Estudiante.apellido.asc(), Estudiante.nombre.asc())
                .limit(300)
                .all()
            )
        except Exception as _lf:
            print("ficha lista:", _lf)
            lista = []

    def _h(s):
        return str(s or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    opts_g = "".join(
        '<option value="' + _h(g) + '"' + (" selected" if str(g) == grado else "") + ">" + _h(g) + "</option>"
        for g in (grs or [])
    )

    filas = []
    for st in lista:
        link = "/notas/ficha?grado=" + _q(grado) + "&est=" + str(st.id)
        filas.append(
            "<tr><td>" + _h(st.apellido) + " " + _h(st.nombre) + "</td><td>" + _h(st.codigo)
            + "</td><td>" + _h(st.grado) + "</td>"
            + "<td><a class='btn' style='padding:4px 10px;font-size:12px' href='" + link + "'>Abrir ficha</a></td></tr>"
        )
    if grado and not filas:
        filas = ["<tr><td colspan='4'>No hay estudiantes en este grado.</td></tr>"]
    if not grado:
        filas = ["<tr><td colspan='4'>Seleccione un grado para listar el grupo.</td></tr>"]

    detalle = ""
    if e:
        try:
            regs = NotaRegistro.query.filter_by(estudiante_id=e.id).order_by(NotaRegistro.id.desc()).limit(40).all()
        except Exception:
            regs = []
        try:
            ingresos = IngresoPorteria.query.filter_by(estudiante_id=e.id).order_by(IngresoPorteria.id.desc()).limit(20).all()
        except Exception:
            ingresos = []
        try:
            obs_list = ObservacionBoletin.query.filter_by(estudiante_id=e.id).order_by(ObservacionBoletin.id.desc()).limit(15).all()
        except Exception:
            obs_list = []
        filas_n = "".join(
            "<tr><td>" + _h(r.periodo) + "</td><td>" + _h(r.asignatura or "—") + "</td><td>"
            + _h(r.valor if r.valor is not None else "—") + "</td></tr>"
            for r in regs
        ) or "<tr><td colspan='3'>Sin notas aún</td></tr>"
        filas_a = "".join(
            "<tr><td>" + _h(i.fecha) + "</td><td>" + _h(i.hora) + "</td><td>" + _h(i.estado) + "</td></tr>"
            for i in ingresos
        ) or "<tr><td colspan='3'>Sin ingresos QR</td></tr>"
        filas_o = "".join(
            "<tr><td>" + _h(getattr(o, "actualizado", None) or getattr(o, "periodo", "") or "")
            + "</td><td>" + _h((getattr(o, "texto", None) or "")[:220]) + "</td></tr>"
            for o in obs_list
        ) or "<tr><td colspan='2'>Sin registros de seguimiento</td></tr>"

        detalle = (
            '<section id="ficha-detalle" class="role-panel" style="margin:14px 0;border:2px solid #0B2D57;border-radius:14px;padding:16px">'
            "<h2 style=\"margin-top:0\">" + _h(e.apellido) + " " + _h(e.nombre) + "</h2>"
            "<p>Código <b>" + _h(e.codigo) + "</b> · Grado <b>" + _h(e.grado) + "</b></p>"
            "<h3>Registrar seguimiento (disciplinario / meta / falencia)</h3>"
            '<form method="POST" style="display:grid;gap:8px;max-width:640px">'
            '<input type="hidden" name="estudiante_id" value="' + str(e.id) + '">'
            '<input type="hidden" name="grado" value="' + _h(grado or e.grado or "") + '">'
            '<div><label><b>Tipo</b></label><select name="tipo">'
            '<option value="disciplinario">Proceso disciplinario</option>'
            '<option value="meta">Meta de mejora</option>'
            '<option value="falencia">Falencia / dificultad</option>'
            '<option value="observacion">Como le va (observacion)</option>'
            "</select></div>"
            '<div><label><b>Descripcion</b></label><textarea name="texto" rows="3" style="width:100%" placeholder="Detalle del seguimiento"></textarea></div>'
            '<div><label><b>Meta (opcional)</b></label><input name="meta" style="width:100%"></div>'
            '<div><label><b>Falencia (opcional)</b></label><input name="falencia" style="width:100%"></div>'
            '<button type="submit">Guardar en ficha</button></form></section>'
            '<section class="table-card" style="margin-bottom:12px"><h2>Historial de seguimiento</h2>'
            "<table><tr><th>Fecha</th><th>Registro</th></tr>" + filas_o + "</table></section>"
            '<section class="table-card" style="margin-bottom:12px"><h2>Notas recientes</h2>'
            "<table><tr><th>Periodo</th><th>Materia</th><th>Nota</th></tr>" + filas_n + "</table></section>"
            '<section class="table-card"><h2>Asistencia (ingresos)</h2>'
            "<table><tr><th>Fecha</th><th>Hora</th><th>Estado</th></tr>" + filas_a + "</table></section>"
        )

    content = (
        '<header class="role-hero"><div><h1>Ficha de seguimiento</h1>'
        "<p>Filtre por grado, abra un estudiante y registre procesos, metas o falencias.</p></div>"
        '<a class="btn" href="' + back + '">← Inicio panel</a></header>'
    )
    if msg:
        content += '<div class="msg ok">' + _h(msg) + "</div>"
    # Detalle PRIMERO al abrir estudiante
    content += detalle
    content += (
        '<div class="role-panel"><form method="GET" style="display:flex;gap:8px;flex-wrap:wrap;align-items:end">'
        '<div><label><b>Grado / grupo</b></label>'
        '<select name="grado"><option value="">— Seleccionar —</option>' + opts_g + "</select></div>"
        '<button type="submit">Ver estudiantes</button></form></div>'
        '<div class="table-card" style="margin-top:12px"><table>'
        "<tr><th>Estudiante</th><th>Código</th><th>Grado</th><th></th></tr>"
        + "".join(filas) + "</table></div>"
    )
    if e:
        content += '<script>try{document.getElementById("ficha-detalle").scrollIntoView({behavior:"smooth",block:"start"});}catch(e){}</script>'
    return page("Ficha de seguimiento", shell(content))



@app.route("/notas/faltas", methods=["GET", "POST"])
def notas_faltas():
    """Faltas: filtro por grado + marcar Presente / Ausente / Tarde / Excusa."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Docente", "Coordinación", "Rectoría", "Rector", "Secretaría", "Administrador", "Soporte"]:
        return acceso_denegado()
    msg = ""
    fecha = (request.form.get("fecha") or request.args.get("fecha") or fecha_hoy()).strip()
    grado = (request.form.get("grado") or request.args.get("grado") or "").strip()

    if request.method == "POST" and request.form.get("accion") == "guardar":
        try:
            ids = request.form.getlist("est_id")
            for sid in ids:
                try:
                    eid = int(sid)
                except Exception:
                    continue
                estado = (request.form.get("estado_%s" % eid) or "").strip()
                obs = (request.form.get("obs_%s" % eid) or "").strip()[:200]
                if not estado or estado == "—":
                    continue
                # Map UI -> IngresoPorteria
                mapa = {
                    "Presente": "Temprano",
                    "Ausente": "No llegó",
                    "Tarde": "Tarde",
                    "Excusa": "Excusa",
                    "Temprano": "Temprano",
                    "No llegó": "No llegó",
                }
                est_db = mapa.get(estado, estado)
                ing = IngresoPorteria.query.filter_by(estudiante_id=eid, fecha=fecha).first()
                if not ing:
                    try:
                        h = hora_actual()
                    except Exception:
                        h = "00:00"
                    try:
                        from datetime import datetime as _dt
                        dia = _dt.strptime(fecha, "%Y-%m-%d").strftime("%A")
                    except Exception:
                        dia = ""
                    ing = IngresoPorteria(
                        estudiante_id=eid,
                        fecha=fecha,
                        hora=h,
                        dia=dia or "—",
                        estado=est_db,
                        periodo=periodo_actual() or "Periodo 1",
                        registrado_por=session.get("usuario") or "Docente",
                    )
                    db.session.add(ing)
                else:
                    ing.estado = est_db
                    try:
                        ing.registrado_por = session.get("usuario") or ing.registrado_por
                    except Exception:
                        pass
                if estado == "Excusa":
                    try:
                        e = Estudiante.query.get(eid)
                        if e:
                            db.session.add(Excusa(
                                estudiante_id=eid,
                                fecha=fecha,
                                motivo=obs or "Excusa registrada por docente",
                                registrado_por=session.get("usuario") or "",
                                periodo=periodo_actual() or "",
                            ))
                    except Exception as ex_e:
                        print("excusa faltas:", ex_e)
            db.session.commit()
            msg = "Asistencia / faltas guardadas para " + fecha
            try:
                registrar_auditoria("Faltas docente", "Guardó estados " + fecha)
            except Exception:
                pass
        except Exception as ex:
            try:
                db.session.rollback()
            except Exception:
                pass
            msg = "Error al guardar: " + str(ex)[:120]

    # Grados (docente: los suyos)
    try:
        if rol_actual() == "Docente":
            grs = list(grados_docente_actual() or []) or grados_disponibles()
        else:
            grs = grados_disponibles()
    except Exception:
        grs = grados_disponibles()

    opts = "".join(
        '<option value="%s"%s>%s</option>' % (g, " selected" if str(g) == grado else "", g)
        for g in (grs or [])
    )

    ests_q = q_estudiantes()
    if grado:
        g_norm = str(grado).replace("°", "").replace("º", "").strip()
        try:
            g_norm = str(int(g_norm)) if g_norm.isdigit() else g_norm
        except Exception:
            pass
        from sqlalchemy import or_
        ests_q = ests_q.filter(
            or_(
                Estudiante.grado == grado,
                Estudiante.grado == g_norm,
                Estudiante.grado.like(g_norm + "%"),
                Estudiante.grado.like(g_norm + "°%"),
            )
        )
    ests = ests_q.order_by(Estudiante.apellido.asc()).limit(400).all()

    filas = []
    for e in ests:
        ing = IngresoPorteria.query.filter_by(estudiante_id=e.id, fecha=fecha).first()
        actual = "—"
        if ing:
            if ing.estado in ("Temprano", "Presente"):
                actual = "Presente"
            elif ing.estado in ("No llegó", "Ausente"):
                actual = "Ausente"
            elif ing.estado == "Tarde":
                actual = "Tarde"
            elif ing.estado == "Excusa":
                actual = "Excusa"
            else:
                actual = ing.estado or "—"
        opts_e = ""
        for op in ("—", "Presente", "Ausente", "Tarde", "Excusa"):
            sel = " selected" if op == actual else ""
            opts_e += '<option value="%s"%s>%s</option>' % (op, sel, op)
        bg = " style='background:#fef2f2'" if actual in ("Ausente", "Sin registro") else ""
        filas.append(
            "<tr%s><td>%s</td><td>%s %s</td><td>%s</td>"
            "<td><input type='hidden' name='est_id' value='%s'>"
            "<select name='estado_%s'>%s</select></td>"
            "<td><input name='obs_%s' placeholder='Obs.' style='width:100%%;min-width:90px'></td></tr>"
            % (bg, e.codigo or "", e.apellido or "", e.nombre or "", e.grado or "", e.id, e.id, opts_e, e.id)
        )
    if not filas:
        filas = ["<tr><td colspan='5'>Sin estudiantes (elija grado o verifique que existan en el colegio).</td></tr>"]

    back = "/docente-escritorio" if rol_actual() == "Docente" else "/notas"
    content = (
        '<div style="display:flex;justify-content:space-between;margin-bottom:14px;flex-wrap:wrap;gap:8px">'
        '<div><h1 style="margin:0;font-size:20px">Faltas de asistencia</h1>'
        '<p class="mini-text">Marque Presente, Ausente, Tarde o Excusa · Filtro por grado</p></div>'
        '<a class="btn" href="' + back + '">← Inicio panel</a></div>'
    )
    if msg:
        content += '<div class="msg ok">' + msg.replace("<", "") + "</div>"
    content += (
        '<form method="GET" style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:end">'
        '<div><label><b>Grado</b></label><select name="grado"><option value="">Todos</option>' + opts + "</select></div>"
        '<div><label><b>Fecha</b></label><input type="date" name="fecha" value="' + fecha + '"></div>'
        "<button>Ver</button></form>"
        '<form method="POST">'
        '<input type="hidden" name="accion" value="guardar">'
        '<input type="hidden" name="fecha" value="' + fecha + '">'
        '<input type="hidden" name="grado" value="' + (grado or "") + '">'
        '<section class="table-card">'
        "<table><tr><th>Código</th><th>Estudiante</th><th>Grado</th><th>Estado</th><th>Obs.</th></tr>"
        + "".join(filas)
        + "</table>"
        '<p style="margin-top:12px"><button type="submit">Guardar faltas / asistencia</button></p>'
        "</section></form>"
    )
    return page("Faltas", shell(content))



@app.route("/notas/descargar")
def notas_descargar():
    if not requiere_login():
        return redirect("/login")
    if rol_actual() == "Docente":
        return acceso_denegado("La descarga Excel de notas es para Secretaría, Coordinación, Rectoría o Administración.")
    iid = institucion_id_actual()
    periodo = (request.args.get("periodo") or periodo_actual()).strip()
    if request.args.get("xlsx"):
        wb = Workbook()
        ws = wb.active
        ws.title = "Notas"
        ws.append(["codigo", "estudiante", "grado", "criterio", "asignatura", "periodo", "nota", "docente", "actualizado"])
        regs = NotaRegistro.query.filter_by(institucion_id=iid, periodo=periodo).limit(5000).all()
        for r in regs:
            e = Estudiante.query.get(r.estudiante_id)
            c = SieeCriterio.query.get(r.criterio_id) if r.criterio_id else None
            ws.append([
                e.codigo if e else "", f"{e.apellido} {e.nombre}" if e else "", e.grado if e else "",
                c.nombre if c else "", r.asignatura, r.periodo, r.valor, r.docente, r.actualizado
            ])
        bio = BytesIO()
        wb.save(bio)
        bio.seek(0)
        return send_file(bio, as_attachment=True, download_name=f"notas_{periodo.replace(' ','_')}.xlsx")
    content = f"""
<div style="display:flex;justify-content:space-between;margin-bottom:14px">
  <h1 style="margin:0;font-size:20px">Descargar notas</h1>
  <a class="btn" href="/docente-escritorio">← Inicio panel</a>
</div>
<section class="role-panel">
  <p>Periodo actual: <b>{periodo}</b></p>
  <a class="btn btn-green" href="/notas/descargar?xlsx=1&periodo={periodo}">Descargar Excel</a>
</section>
"""
    return page("Descargar notas", shell(content))


