@app.route("/secretaria/retirar-estudiante", methods=["GET", "POST"])
def secretaria_retirar_estudiante():
    """Retiro de estudiantes con filtros por sede, grado/grupo y motivos SIMAT."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ("Secretaría", "Soporte", "Administrador", "Rectoría"):
        return acceso_denegado("Solo Secretaría / Rectoría pueden retirar estudiantes.")
    iid = institucion_id_actual()
    msg = err = ""

    MOTIVOS_SIMAT = [
        "Traslado a otra institución",
        "Deserción (Dejó de asistir)",
        "Falta de recursos económicos",
        "Cambio de domicilio",
        "Problemas de convivencia",
        "Enfermedad / condición de salud",
        "Cambio de jornada o modalidad",
        "Otro (especificar)",
    ]
    try:
        _cfgp = os.path.join(app.root_path, "config", "listas_dinamicas.json")
        if os.path.isfile(_cfgp):
            with open(_cfgp, "r", encoding="utf-8") as _f:
                _data = json.load(_f)
            if isinstance(_data.get("lista:motivos_retiro"), list) and _data["lista:motivos_retiro"]:
                MOTIVOS_SIMAT = list(_data["lista:motivos_retiro"])
                if "Otro (especificar)" not in MOTIVOS_SIMAT:
                    MOTIVOS_SIMAT.append("Otro (especificar)")
    except Exception:
        pass

    # Sedes del colegio
    sedes_opts = []
    try:
        if iid is not None:
            sedes_opts = SedeInstitucion.query.filter_by(institucion_id=iid, activa=True).order_by(SedeInstitucion.nombre.asc()).all()
        else:
            sedes_opts = SedeInstitucion.query.filter_by(activa=True).order_by(SedeInstitucion.nombre.asc()).limit(40).all()
    except Exception:
        sedes_opts = []

    grados = []
    try:
        grados = grados_disponibles() or []
    except Exception:
        grados = []

    q = (request.values.get("q") or "").strip()
    sede_f = (request.values.get("sede") or "").strip()
    grado_f = (request.values.get("grado") or "").strip()
    grupo_f = (request.values.get("grupo") or "").strip()

    if request.method == "POST" and request.form.get("accion") == "retirar":
        try:
            eid = int(request.form.get("estudiante_id") or 0)
        except Exception:
            eid = 0
        e = Estudiante.query.get(eid)
        if not e:
            err = "Estudiante no encontrado."
        elif iid and e.institucion_id and int(e.institucion_id) != int(iid):
            err = "No puede retirar estudiantes de otro colegio."
        else:
            motivo = (request.form.get("motivo") or "").strip()
            motivo_otro = (request.form.get("motivo_otro") or "").strip()
            if motivo == "Otro (especificar)" and motivo_otro:
                motivo = f"Otro: {motivo_otro}"
            if not motivo or len(motivo) < 3:
                err = "Seleccione un motivo de retiro válido (SIMAT)."
            else:
                if hasattr(e, "estado"):
                    e.estado = "RETIRADO"
                if hasattr(e, "observacion"):
                    prev = (e.observacion or "").strip()
                    nota = f"RETIRO SIMAT: {motivo}"
                    e.observacion = (prev + " | " + nota if prev else nota)[:500]
                db.session.commit()
                registrar_auditoria("Retiro estudiante", f"{e.codigo} {estudiante_nombre(e)} | {motivo[:160]}")
                msg = f"Estudiante <b>{estudiante_nombre(e)}</b> ({e.codigo}) marcado como RETIRADO. Motivo: {motivo}"
                q = sede_f = grado_f = grupo_f = ""

    resultados = []
    if q or sede_f or grado_f or grupo_f:
        query = Estudiante.query
        if iid is not None:
            query = query.filter(Estudiante.institucion_id == iid)
        if q:
            like = f"%{q}%"
            query = query.filter(or_(
                Estudiante.codigo.ilike(like),
                Estudiante.documento.ilike(like),
                Estudiante.nombre.ilike(like),
                Estudiante.apellido.ilike(like),
            ))
        if grado_f:
            g_norm = grado_f.replace("°", "").strip()
            query = query.filter(or_(
                Estudiante.grado == grado_f,
                Estudiante.grado == g_norm,
                Estudiante.grado.like(g_norm + "%"),
            ))
        if grupo_f and hasattr(Estudiante, "grupo"):
            query = query.filter(Estudiante.grupo.ilike(f"%{grupo_f}%"))
        if sede_f:
            if hasattr(Estudiante, "sede"):
                query = query.filter(or_(
                    Estudiante.sede.ilike(f"%{sede_f}%"),
                    Estudiante.sede == sede_f,
                ))
        for e in query.order_by(Estudiante.apellido.asc()).limit(80).all():
            est = (getattr(e, "estado", None) or "").upper()
            if est not in ("RETIRADO", "RETIRADA", "INACTIVO"):
                resultados.append(e)

    # Options HTML
    opt_sedes = '<option value="">Todas las sedes</option>' + "".join(
        f'<option value="{_esc(s.nombre)}" {"selected" if sede_f == (s.nombre or "") else ""}>{_esc(s.nombre)}</option>'
        for s in sedes_opts
    )
    if not sedes_opts:
        opt_sedes = '<option value="">Todas las sedes</option><option value="Principal" ' + ('selected' if sede_f=="Principal" else '') + '>Principal</option>'

    opt_grados = '<option value="">Todos los grados</option>' + "".join(
        f'<option value="{_esc(g)}" {"selected" if grado_f == g else ""}>{_esc(g)}</option>'
        for g in grados
    )
    opt_motivos = "".join(f'<option value="{m}">{m}</option>' for m in MOTIVOS_SIMAT)

    filas = ""
    for e in resultados:
        filas += f"""<tr>
          <td>{_esc(e.codigo)}</td>
          <td>{_esc(estudiante_nombre(e))}</td>
          <td>{_esc(e.documento)}</td>
          <td>{_esc(e.grado)}{(' · ' + _esc(getattr(e,'grupo','') or '')) if getattr(e,'grupo',None) else ''}</td>
          <td>{_esc(getattr(e,'sede',None) or '—')}</td>
          <td>
            <form method="POST" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"
              onsubmit="return confirm('¿Confirmar retiro de {_esc(estudiante_nombre(e))}?');">
              <input type="hidden" name="accion" value="retirar">
              <input type="hidden" name="estudiante_id" value="{e.id}">
              <select name="motivo" required style="padding:8px;border:1px solid #cbd5e1;border-radius:8px;min-width:200px">
                <option value="">Motivo SIMAT *</option>
                {opt_motivos}
              </select>
              <input name="motivo_otro" placeholder="Detalle si eligió Otro" style="padding:8px;border:1px solid #cbd5e1;border-radius:8px;min-width:140px">
              <button type="submit" style="background:#b91c1c;color:#fff;border:0;padding:8px 14px;border-radius:8px;font-weight:700">Retirar</button>
            </form>
          </td>
        </tr>"""

    content = f"""
<header class="role-hero"><div>
  <h1>⛔ Retirar estudiante</h1>
  <p>Busque con filtros (sede, grado, grupo) y marque retiro con motivos oficiales SIMAT. Se conserva historial y notas.</p>
</div>
<a class="btn" href="/estudiantes/retirados">Ver retirados</a>
<a class="btn" href="/secretaria/editar-estudiante">Editar estudiante</a></header>
{"<div class='msg ok'>"+msg+"</div>" if msg else ""}
{"<div class='msg danger'>"+err+"</div>" if err else ""}
<section class="role-panel">
  <form method="GET" class="filter-bar">
    <div class="form-row" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;align-items:end">
      <div>
        <label><b>Buscar</b> (código, documento o nombre)</label>
        <input name="q" value="{_esc(q)}" placeholder="Ej. Sebastián o 20220333" autofocus>
      </div>
      <div>
        <label><b>Sede</b></label>
        <select name="sede">{opt_sedes}</select>
      </div>
      <div>
        <label><b>Grado</b></label>
        <select name="grado">{opt_grados}</select>
      </div>
      <div>
        <label><b>Grupo</b></label>
        <input name="grupo" value="{_esc(grupo_f)}" placeholder="Ej. A, 11-A">
      </div>
      <div>
        <button type="submit" style="margin-top:18px">Filtrar / Buscar</button>
      </div>
    </div>
  </form>
  <div style="overflow-x:auto;margin-top:16px">
    <table>
      <tr><th>Código</th><th>Nombre</th><th>Documento</th><th>Grado / Grupo</th><th>Sede</th><th>Acción (motivo SIMAT)</th></tr>
      {filas or ('<tr><td colspan="6">Sin estudiantes activos con esos filtros.</td></tr>' if (q or sede_f or grado_f or grupo_f) else '<tr><td colspan="6">Use los filtros o el buscador. En colegios grandes filtre por sede y grado antes de buscar por nombre.</td></tr>')}
    </table>
  </div>
  <p class="mini-text" style="margin-top:12px;color:#64748b">Motivos alineados a novedades de matrícula SIMAT (MEN). El retiro no borra notas ni historial.</p>
</section>
"""
    return page("Retirar estudiante", shell(content))


