@app.route("/asignaciones_docente", methods=["GET", "POST"])
def asignaciones_docente():
    """Admin/Rectoria asigna materias y grados a cada docente."""
    if not requiere_login():
        return redirect("/login")
    if not puede_gestionar_docentes():
        return acceso_denegado("Solo Secretaría y dirección asignan materias y grupos a docentes.")
    iid = institucion_id_actual()
    mensaje = ""
    docentes_q = Usuario.query.filter_by(rol="Docente")
    if iid is not None:
        docentes_q = docentes_q.filter(Usuario.institucion_id == iid)
    docentes = docentes_q.order_by(Usuario.usuario.asc()).all()

    if request.method == "POST":
        accion = request.form.get("accion") or "crear"
        if accion == "crear":
            try:
                uid = int(request.form.get("usuario_id"))
            except Exception:
                uid = 0
            mat = (request.form.get("asignatura") or "").strip()
            grado = (request.form.get("grado") or "").strip()
            if uid and mat and grado:
                existe = AsignacionDocente.query.filter_by(
                    usuario_id=uid, asignatura=mat, grado=grado, institucion_id=iid
                ).first()
                if not existe:
                    db.session.add(AsignacionDocente(
                        institucion_id=iid,
                        usuario_id=uid,
                        asignatura=mat,
                        grado=grado,
                        activa=True,
                    ))
                    db.session.commit()
                    mensaje = "Asignacion creada."
                else:
                    mensaje = "Esa asignacion ya existia."
            else:
                mensaje = "Completa docente, materia y grado."
        elif accion == "eliminar":
            try:
                aid = int(request.form.get("asig_id"))
            except Exception:
                aid = 0
            a = AsignacionDocente.query.get(aid)
            if a and (a.institucion_id == iid or rol_actual() == "Soporte"):
                db.session.delete(a)
                db.session.commit()
                mensaje = "Asignacion eliminada."

    lista_q = AsignacionDocente.query
    if iid is not None:
        lista_q = lista_q.filter(AsignacionDocente.institucion_id == iid)
    lista = lista_q.order_by(AsignacionDocente.id.desc()).limit(200).all()

    doc_map = {u.id: u.usuario for u in docentes}
    for a in lista:
        if a.usuario_id not in doc_map:
            u = Usuario.query.get(a.usuario_id)
            if u:
                doc_map[u.id] = u.usuario

    filas = ""
    for a in lista:
        uname = doc_map.get(a.usuario_id, str(a.usuario_id))
        filas += "<tr><td><b>" + uname + "</b></td><td>" + a.asignatura + "</td><td>" + a.grado + "</td><td>"
        filas += "<form method='POST' style='display:inline' onsubmit=\"return confirm('Quitar?')\">"
        filas += "<input type='hidden' name='accion' value='eliminar'>"
        filas += "<input type='hidden' name='asig_id' value='" + str(a.id) + "'>"
        filas += "<button class='btn-red' style='padding:4px 8px;font-size:11px'>Quitar</button></form></td></tr>"
    if not filas:
        filas = "<tr><td colspan='4'>Sin asignaciones. Crea el usuario Docente y asignale materias aqui.</td></tr>"

    doc_opts = "".join("<option value='" + str(u.id) + "'>" + u.usuario + "</option>" for u in docentes)
    mat_opts = "".join("<option>" + m + "</option>" for m in todas_materias())
    grados_list = grados_disponibles() or [str(i) for i in range(1, 12)]
    grado_opts = "".join("<option value='" + str(g) + "'>" + str(g) + "</option>" for g in grados_list)

    ok_msg = ""
    err_msg = ""
    if mensaje and ("creada" in mensaje or "eliminada" in mensaje):
        ok_msg = "<div class='msg ok'>" + mensaje + "</div>"
    elif mensaje:
        err_msg = "<div class='msg danger'>" + mensaje + "</div>"

    content = (
        '<div style="max-width:900px;margin:0 auto">'
        '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:14px">'
        '<div><h1 style="margin:0;font-size:20px">Asignaciones docentes</h1>'
        '<p class="mini-text" style="margin:4px 0 0">Paso 2: asignar materia y grado/grupo al docente</p></div>'
        '<div style="display:flex;gap:8px"><a class="btn" href="/usuarios">Usuarios</a>'
        '<a class="btn" href="/notas/planilla">Planilla</a></div></div>'
        + ok_msg + err_msg +
        '<section class="role-panel" style="margin-bottom:14px">'
        '<form method="POST">'
        '<input type="hidden" name="accion" value="crear">'
        '<div class="form-row" style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px">'
        '<div><label><b>Docente</b></label><select name="usuario_id" required><option value="">Seleccione...</option>' + doc_opts + '</select></div>'
        '<div><label><b>Materia</b></label><select name="asignatura" required><option value="">Seleccione...</option>' + mat_opts + '</select></div>'
        '<div><label><b>Grado / grupo</b></label><select name="grado" required><option value="">Seleccione...</option>' + grado_opts + '</select></div>'
        '</div><button style="margin-top:12px">Asignar materia y grado</button></form></section>'
        '<section class="table-card"><table><tr><th>Docente</th><th>Materia</th><th>Grado</th><th></th></tr>'
        + filas + '</table></section></div>'
    )
    return page("Asignaciones docentes", shell(content))



