def _gen_radicado_matricula():
    from random import randint
    anio = ahora().strftime("%y")
    return f"MAT-{anio}-{randint(100000, 999999)}"


def _pdf_pre_matricula(pm, inst=None):
    """Genera PDF de constancia de radicación de pre-matrícula."""
    b = BytesIO()
    pdf = canvas.Canvas(b, pagesize=letter)
    w, h = letter
    y = h - 48
    nombre_inst = (inst.nombre if inst else None) or INST_NOMBRE
    try:
        logo = logo_fs()
        if logo:
            pdf.drawImage(logo, 40, y - 8, width=52, height=52, preserveAspectRatio=True, mask="auto")
    except Exception:
        pass
    pdf.setFont("Helvetica-Bold", 13)
    pdf.drawString(100, y + 22, (nombre_inst or "Institución educativa")[:52])
    pdf.setFont("Helvetica", 9)
    pdf.drawString(100, y + 8, "FORMULARIO DE MATRÍCULA · Constancia de radicación")
    pdf.drawString(100, y - 6, f"Radicado: {pm.radicado} · {pm.fecha} {pm.hora}")
    y -= 50
    pdf.setStrokeColor(colors.HexColor("#0B2D57"))
    pdf.setLineWidth(1.8)
    pdf.line(40, y, w - 40, y)
    y -= 24
    pdf.setFont("Helvetica-Bold", 11)
    pdf.setFillColor(colors.HexColor("#0B2D57"))
    pdf.drawString(40, y, "1. DATOS DEL ESTUDIANTE Y PROGRAMA")
    pdf.setFillColor(colors.black)
    y -= 16
    pdf.setFont("Helvetica", 10)
    lines = [
        f"Nombres: {pm.est_nombres}",
        f"Apellidos: {pm.est_apellidos}",
        f"Documento: {pm.est_documento_tipo} {pm.est_documento}",
        f"Fecha de nacimiento: {pm.est_fecha_nacimiento or '—'}",
        f"RH: {pm.est_rh or '—'} · Sexo: {pm.est_sexo or '—'}",
        f"Grado al que aspira: {pm.est_grado_aspira}",
        f"Jornada: {pm.est_jornada} · Sede: {pm.est_sede}",
        f"Colegio anterior: {pm.est_colegio_anterior or '—'}",
    ]
    for ln in lines:
        pdf.drawString(48, y, ln[:90])
        y -= 14
    y -= 8
    pdf.setFont("Helvetica-Bold", 11)
    pdf.setFillColor(colors.HexColor("#0B2D57"))
    pdf.drawString(40, y, "2. DATOS DEL ACUDIENTE")
    pdf.setFillColor(colors.black)
    y -= 16
    pdf.setFont("Helvetica", 10)
    for ln in [
        f"Nombres: {pm.acu_nombres} {pm.acu_apellidos}",
        f"Parentesco: {pm.acu_parentesco}",
        f"Documento: {pm.acu_documento_tipo} {pm.acu_documento}",
        f"Teléfono: {pm.acu_telefono}",
        f"Correo: {pm.acu_correo}",
        f"Dirección: {pm.acu_direccion}",
        f"Ocupación: {pm.acu_ocupacion or '—'}",
    ]:
        pdf.drawString(48, y, ln[:90])
        y -= 14
    y -= 12
    pdf.setFont("Helvetica-Bold", 10)
    pdf.drawString(40, y, f"Estado de la solicitud: {pm.estado}")
    y -= 18
    pdf.setFont("Helvetica", 9)
    pdf.drawString(40, y, "Conserve este documento. La institución se contactará para continuar el proceso.")
    y -= 14
    pdf.drawString(40, y, "Este radicado no garantiza cupo hasta la aprobación oficial de la institución.")
    y -= 40
    pdf.line(50, y, 220, y)
    pdf.line(320, y, 520, y)
    pdf.setFont("Helvetica", 8)
    pdf.drawString(50, y - 12, "Firma acudiente")
    pdf.drawString(320, y - 12, "Sello / Secretaría")
    pdf.setFont("Helvetica", 8)
    pdf.drawString(40, 36, "EduTrack · PROCSIS · Tecnología para una educación moderna y responsable")
    pdf.save()
    b.seek(0)
    return b


