@app.route("/pqr-colegio", methods=["GET", "POST"])
def pqr_colegio():
    """Bandeja institucional: PQR de padres. Solo RADICADA (responder) o CERRADA (solo consulta)."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Administrador", "Rectoría", "Coordinación", "Secretaría", "Soporte"]:
        return acceso_denegado()
    iid = institucion_id_actual()
    mensaje = ""
    if request.method == "POST" and iid:
        tid = request.form.get("id")
        accion = (request.form.get("accion") or "cerrar").strip()
        resp = (request.form.get("respuesta") or "").strip()[:3000]
        try:
            t = TicketPQR.query.get(int(tid))
            if not t or (t.institucion_id != iid and rol_actual() != "Soporte"):
                mensaje = "PQR no encontrada o de otro colegio."
            elif (t.estado or "").upper() in ("CERRADA", "CERRADO", "RESUELTA"):
                mensaje = "Esta PQR ya está cerrada. Solo se puede consultar."
            elif not resp:
                mensaje = "Escriba la respuesta antes de cerrar."
            else:
                # Al responder → queda CERRADA (definitiva, sin reedición)
                t.respuesta = resp
                t.descripcion_cierre = resp
                t.estado = "CERRADA"
                t.estado_cun = "CERRADO"
                t.fecha_respuesta = fecha_hoy()
                t.fecha_cierre = fecha_hoy()
                t.cerrado_por = session.get("usuario") or ""
                t.fecha_cierre = fecha_hoy()
                db.session.commit()
                try:
                    registrar_historial_pqr(t.id, "CIERRE_COLEGIO", resp[:200], "CERRADA")
                except Exception:
                    pass
                try:
                    registrar_auditoria("PQR padres cerrada", f"{t.radicado}")
                except Exception:
                    pass
                mensaje = f"PQR {t.radicado} respondida y cerrada. Ya no se puede modificar."
        except Exception as ex:
            mensaje = str(ex)[:150]

    q = TicketPQR.query
    if rol_actual() != "Soporte" and iid is not None:
        q = q.filter(TicketPQR.institucion_id == iid)
    q = q.filter(db.or_(TicketPQR.canal == "PADRES_COLEGIO", TicketPQR.institucion_id == iid))
    filtro = (request.args.get("estado") or "todas").strip().lower()
    if filtro == "abiertas":
        q = q.filter(~TicketPQR.estado.in_(["CERRADA", "CERRADO", "RESUELTA"]))
    elif filtro == "cerradas":
        q = q.filter(TicketPQR.estado.in_(["CERRADA", "CERRADO", "RESUELTA"]))
    rows = q.order_by(TicketPQR.id.desc()).limit(150).all()

    filas = ""
    for t in rows:
        est = (t.estado or "").upper()
        cerrada = est in ("CERRADA", "CERRADO", "RESUELTA")
        # Normalizar visualmente RESUELTA antigua → mostrar CERRADA
        est_mostrar = "CERRADA" if cerrada else "RADICADA"
        detalle_id = f"det{t.id}"
        hechos = (t.hechos or "").replace("<", "&lt;").replace(">", "&gt;")
        objeto = (t.objeto or "").replace("<", "&lt;").replace(">", "&gt;")
        respuesta_safe = (t.respuesta or "").replace("<", "&lt;").replace(">", "&gt;")
        detalle_html = f"""
        <div id="{detalle_id}" style="display:none;margin-top:8px;padding:10px;background:#f8fafc;border-radius:10px;border:1px solid #e2e8f0;font-size:13px;line-height:1.45">
          <p style="margin:0 0 6px"><b>Objeto / razón:</b><br>{objeto or '—'}</p>
          <p style="margin:0 0 6px"><b>Hechos / descripción:</b><br>{hechos or '—'}</p>
          <p style="margin:0 0 6px"><b>Prioridad:</b> {t.prioridad or '—'} · <b>Canal:</b> {t.canal or '—'}</p>
          <p style="margin:0"><b>Respuesta del colegio:</b><br>{respuesta_safe or 'Sin respuesta aún.'}</p>
          {"<p style='margin:8px 0 0;color:#64748b'><b>Cerrada por:</b> "+(t.cerrado_por or '—')+" · "+(t.fecha_cierre or t.fecha_respuesta or '')+"</p>" if cerrada else ""}
        </div>
        <button type="button" onclick="var e=document.getElementById('{detalle_id}');e.style.display=e.style.display==='none'?'block':'none';this.textContent=e.style.display==='none'?'Ver razón completa':'Ocultar detalle'"
          style="margin-top:6px;padding:4px 10px;font-size:11px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;cursor:pointer">Ver razón completa</button>
        """
        if cerrada:
            acciones = f"""
            <span style="display:inline-block;background:#ecfdf5;color:#065f46;font-weight:700;font-size:12px;padding:4px 10px;border-radius:999px">CERRADA · solo consulta</span>
            {detalle_html}
            """
        else:
            acciones = f"""
            <form method="POST" style="min-width:200px" onsubmit="return confirm('Al guardar la respuesta esta PQR quedará CERRADA y no se podrá editar. ¿Continuar?');">
              <input type="hidden" name="id" value="{t.id}">
              <input type="hidden" name="accion" value="cerrar">
              <textarea name="respuesta" rows="3" required placeholder="Respuesta oficial al acudiente (definitiva)"></textarea>
              <button style="margin-top:6px;padding:8px 12px;font-size:12px;background:#0B2D57;color:#fff;border:0;border-radius:8px;font-weight:700;cursor:pointer">Responder y cerrar</button>
            </form>
            {detalle_html}
            """
        filas += f"""
        <tr style="{'opacity:.92;background:#f8fafc' if cerrada else ''}">
          <td><b>{t.radicado}</b><br><span class="mini-text">{t.fecha} {t.hora}</span><br>
            <span style="font-size:11px;font-weight:800;color:{'#065f46' if cerrada else '#b45309'}">{est_mostrar}</span>
          </td>
          <td>{t.razon_social} {t.apellidos or ''}<br>
            <span class="mini-text">{t.tipo_documento} {t.numero_documento}<br>{t.email}</span>
          </td>
          <td><b>{t.tipo_pqr}</b><br>{t.subtipo}<br><span class="mini-text">{(t.objeto or '')[:90]}</span></td>
          <td>{acciones}</td>
        </tr>"""

    content = f"""
<header class="role-hero">
  <div>
    <h1>PQR de padres de familia</h1>
    <p>Solo dos estados: <b>RADICADA</b> (puede responderse) y <b>CERRADA</b> (solo consulta, sin editar).</p>
  </div>
  <a class="btn" href="/enlaces-publicos">Enlaces para compartir</a>
</header>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
<section class="role-panel" style="margin-bottom:12px">
  <a class="btn" href="/pqr-colegio?estado=abiertas">Abiertas (radicadas)</a>
  <a class="btn" href="/pqr-colegio?estado=cerradas">Cerradas</a>
  <a class="btn" href="/pqr-colegio">Todas</a>
</section>
<div class="table-card" style="overflow:auto">
<table>
<tr><th>Radicado</th><th>Acudiente</th><th>Motivo</th><th>Detalle / respuesta</th></tr>
{filas if filas else "<tr><td colspan='4'>Aún no hay PQR de padres.</td></tr>"}
</table>
</div>
"""
    return page("PQR colegio", shell(content))



def _gen_radicado_pqr(tipo_canal="11"):
    """Número de Radicado 100% numérico (12 dígitos), formato legal colombiano:
    AAAA (año) + TT (tipo de canal) + NNNNNN (consecutivo secuencial).
    tipo_canal: "11" = Padres de familia / canal público web · "22" = Soporte técnico (B2B/institucional).
    El consecutivo reinicia en 000001 cada 1 de enero y avanza de forma estricta por año+canal.
    (No usamos una tabla de secuencia con bloqueo dedicado; en tráfico concurrente muy alto
    podría saltarse algún número, pero nunca se repite — el sitio de llamada reintenta si
    detecta colisión, y el número siempre queda estrictamente creciente)."""
    from datetime import datetime
    anio = datetime.now().strftime("%Y")
    tipo_canal = "".join(c for c in str(tipo_canal or "11") if c.isdigit()).zfill(2)[:2]
    prefijo = f"{anio}{tipo_canal}"
    ultimo = (
        db.session.query(db.func.max(TicketPQR.radicado))
        .filter(TicketPQR.radicado.like(f"{prefijo}%"), db.func.length(TicketPQR.radicado) == 12)
        .scalar()
    )
    try:
        siguiente = int(ultimo[6:]) + 1 if ultimo else 1
    except Exception:
        siguiente = 1
    rad = f"{prefijo}{siguiente:06d}"
    intentos = 0
    while TicketPQR.query.filter_by(radicado=rad).first() and intentos < 50:
        siguiente += 1
        rad = f"{prefijo}{siguiente:06d}"
        intentos += 1
    import random
    tick = f"{random.randint(100000, 999999)}"
    tries = 0
    while TicketPQR.query.filter_by(ticket=tick).first() and tries < 20:
        tick = f"{random.randint(100000, 999999)}"
        tries += 1
    return rad, tick


def formatear_radicado(rad):
    """Solo para MOSTRAR en pantalla/PDF/correo: separa año-canal-consecutivo con
    guiones (ej. 2026-11-000452). La base de datos SIEMPRE guarda los 12 dígitos
    continuos (ej. 202611000452) — el guion es puramente visual."""
    rad = (rad or "").strip()
    if len(rad) == 12 and rad.isdigit():
        return f"{rad[:4]}-{rad[4:6]}-{rad[6:]}"
    return rad or "—"


