    def avg(attr):
        vals = [getattr(r, attr) or 0 for r in respondidas if (getattr(r, attr) or 0) > 0]
        return round(sum(vals) / len(vals), 2) if vals else 0.0

    n = len([r for r in respondidas if (getattr(r, "promedio", 0) or 0) > 0])
