@app.route("/soporte/pqr/<int:id>", methods=["GET", "POST"])
def soporte_pqr_detalle(id):
    if not requiere_login() or rol_actual() != "Soporte":
        return redirect("/soporte-login")
    try:
        t = TicketPQR.query.get_or_404(id)
    except Exception as e404:
        return page("Detalle PQR", shell(
            f"<div class='msg danger'>Ticket no encontrado ({_esc(str(e404)[:120])})</div>"
            "<p><a class='btn' href='/soporte/pqr'>← Centro PQR</a></p>"
        ))
    mensaje = ""
    cerrado = (t.estado or "").upper() in ("CERRADA", "CERRADO", "RESUELTA")
    if request.method == "POST":
        # Bloqueo total si ya está cerrada/resuelta (solo consulta)
        if cerrado and not es_gerente_pqr():
            mensaje = "Ticket cerrado/resuelto: no se permiten más cambios. Solo consulta."
        else:
            nuevo = (request.form.get("estado") or t.estado).strip()
            resp = (request.form.get("respuesta") or "").strip()
            t.estado = nuevo
            if resp:
                # Acumular respuesta (no borrar la anterior)
                prev = (t.respuesta or "").strip()
                stamp = f"[{fecha_hoy()} {hora_actual()} · {session.get('usuario','soporte')}]"
                t.respuesta = (prev + "\n\n" + stamp + "\n" + resp).strip() if prev else (stamp + "\n" + resp)
                t.fecha_respuesta = fecha_hoy()
                if resp:
                    t.descripcion_cierre = resp  # solución visible en consulta pública
            if nuevo.upper() in ("CERRADA", "CERRADO", "RESUELTA"):
                t.cerrado_por = session.get("usuario", "")
                t.fecha_cierre = fecha_hoy()
                t.estado_cun = "CERRADO"
                if resp:
                    t.descripcion_cierre = resp
            try:
                db.session.commit()
                cerrado = (t.estado or "").upper() in ("CERRADA", "CERRADO", "RESUELTA")
                try:
                    registrar_historial_pqr(t.id, "RESPUESTA" if resp else "ESTADO", resp or f"Estado → {nuevo}", nuevo)
                    db.session.commit()
                except Exception as ex:
                    db.session.rollback()
                    print("historial pqr:", ex)
                cierra_caso = nuevo.upper() in ("CERRADA", "CERRADO", "RESUELTA")
                encuesta_url = ""
                if cierra_caso:
                    try:
                        _enc, encuesta_url = _crear_encuesta_csat_para_ticket(t)
                        if encuesta_url:
                            mensaje = (mensaje + " " if mensaje else "") + f"Link encuesta CSAT: {encuesta_url}"
                    except Exception as _ce:
                        print("csat on resolve:", _ce)
                enviar_mail = (request.form.get("enviar_correo") or "") == "1" or cierra_caso
                mail_ok = False
                if resp and t.email and enviar_mail:
                    try:
                        # Al cerrar/resolver el caso se envía automáticamente el aviso
                        # estilo Tigo (link a la landing pública); en otros estados
                        # intermedios se manda el correo directo con la respuesta.
                        # Siempre diseño corporativo con botón VER RESPUESTA
                        # (no enviar el texto de la solución en el cuerpo del correo).
                        mail_ok = enviar_notificacion_pqr_estilo_tigo(t.email, t)
                        if not mail_ok:
                            # Reintento: canal soporte por si notificaciones falló
                            try:
                                mail_ok = enviar_notificacion_pqr_estilo_tigo(t.email, t)
                            except Exception:
                                mail_ok = False
                    except Exception as ex:
                        print("mail respuesta:", ex)
                if resp and t.email and enviar_mail:
                    mensaje = "Respuesta guardada. " + (
                        "Correo enviado al usuario (botón VER RESPUESTA)."
                        if mail_ok
                        else "No se pudo enviar el correo (configure RESEND_API_KEY en Railway o SOPORTE_PASSWORD en plan Pro)."
                    )
                else:
                    mensaje = "Respuesta y estado guardados correctamente."
            except Exception as ex:
                db.session.rollback()
                mensaje = f"Error al guardar: {ex}"
    try:
        hist = HistorialPQR.query.filter_by(ticket_id=t.id).order_by(HistorialPQR.id.desc()).limit(40).all()
    except Exception:
        hist = []
    htm = "".join(
        f"<li style='margin-bottom:8px'><b>{getattr(h,'fecha','')} {getattr(h,'hora','')}</b> · {getattr(h,'usuario','')}<br>"
        f"<span class='mini-text'>{getattr(h,'accion','')}</span><br>{(getattr(h,'detalle','') or '')[:500]}</li>"
        for h in hist
    )
    resp_html = (t.respuesta or "").replace("<", "&lt;").replace("\n", "<br>")
    form_block = ""
    if cerrado and not es_gerente_pqr():
        form_block = "<div class='msg' style='background:#fef3c7;color:#92400e;padding:12px;border-radius:10px'>Ticket <b>cerrado/resuelto</b>. Solo consulta. No se puede editar ni eliminar.</div>"
    else:
        form_block = f"""
  <form method="POST">
    <label>Nuevo estado</label>
    <select name="estado">
      <option {"selected" if (t.estado or "")=="RADICADA" else ""}>RADICADA</option>
      <option {"selected" if (t.estado or "")=="EN VALIDACIÓN" else ""}>EN VALIDACIÓN</option>
      <option {"selected" if (t.estado or "")=="ASIGNADA" else ""}>ASIGNADA</option>
      <option {"selected" if (t.estado or "")=="EN PROCESO" else ""}>EN PROCESO</option>
      <option {"selected" if (t.estado or "")=="PENDIENTE DEL CLIENTE" else ""}>PENDIENTE DEL CLIENTE</option>
      <option {"selected" if (t.estado or "")=="ESCALADA A DESARROLLO" else ""}>ESCALADA A DESARROLLO</option>
      <option {"selected" if (t.estado or "")=="RESUELTA" else ""}>RESUELTA</option>
      <option {"selected" if (t.estado or "")=="CERRADA" else ""}>CERRADA</option>
    </select>
    <label>Respuesta al usuario (se guarda y no se borra)</label>
    <textarea name="respuesta" rows="6" placeholder="Escriba la solución completa que verá el cliente (Descripción de cierre)..."></textarea>
    <label style="display:flex;align-items:center;gap:8px;margin:12px 0;font-weight:700">
      <input type="checkbox" name="enviar_correo" value="1" checked style="width:auto">
      Enviar correo al usuario (si el estado es Resuelta/Cerrada se envía automáticamente el aviso con link, aunque desmarques esto)
    </label>
    <button type="submit">Guardar respuesta / estado</button>
  </form>
  <div style="margin-top:14px;display:flex;flex-wrap:wrap;gap:8px">
    <a class="btn" href="/soporte/pqr/{t.id}/pdf" target="_blank">Descargar PDF de respuesta</a>
    <a class="btn" style="background:#0d9488" href="/pqr/consulta">Ver consulta pública</a>
  </div>
"""

    csat_box = ""
