@app.route("/exportar_simat")
def exportar_simat():
    """Exportación oficial SIMAT: columnas técnicas, IDs como texto."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Administrador", "Rectoría", "Coordinación", "Secretaría", "Soporte"]:
        return acceso_denegado()
    iid = institucion_id_actual()
    # Preferir pre-matrículas aprobadas/matriculadas + estudiantes del colegio
    cols = [
        "TIPO_DOC", "NRO_DOC", "EXP_DEPA", "EXP_MUNI",
        "APELLIDO1", "APELLIDO2", "NOMBRE1", "NOMBRE2",
        "FECHA_NACIMIENTO", "GENERO",
        "DIRECCION", "BARRIO", "ESTRATO", "ZONA", "RES_DEPA", "RES_MUNI",
        "SISBEN_GRUPO", "DISCAPACIDAD", "CAP_EXCEPCIONAL", "VICTIMA", "ETNIA",
        "SEDE", "JORNADA", "GRADO", "GRUPO",
        "ACU_NOMBRE", "ACU_DOC", "ACU_TEL", "ACU_CORREO",
        "ESTADO_MATRICULA", "RADICADO",
    ]
    wb = Workbook()
    ws = wb.active
    ws.title = "SIMAT"
    for i, c in enumerate(cols, 1):
        cell = ws.cell(1, i, c)
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="0B2D57")
    row_i = 2

    def put(r, values):
        for col, val in enumerate(values, 1):
            # Forzar texto para no perder ceros a la izquierda
            cell = ws.cell(r, col, "" if val is None else str(val))
            cell.number_format = "@"

    # Desde pre-matrículas del tenant
    q = PreMatricula.query
    if iid is not None and rol_actual() != "Soporte":
        q = q.filter_by(institucion_id=iid)
    for pm in q.order_by(PreMatricula.id.asc()).limit(5000).all():
        put(row_i, [
            pm.est_documento_tipo or "",
            pm.est_documento or "",
            pm.est_doc_dep_exp or "",
            pm.est_doc_mun_exp or "",
            pm.est_primer_apellido or (pm.est_apellidos or "").split(" ")[0] if pm.est_apellidos else "",
            pm.est_segundo_apellido or "",
            pm.est_primer_nombre or (pm.est_nombres or "").split(" ")[0] if pm.est_nombres else "",
            pm.est_segundo_nombre or "",
            pm.est_fecha_nacimiento or "",
            pm.est_genero or pm.est_sexo or "",
            pm.acu_direccion or "",
            pm.est_barrio or "",
            pm.est_estrato or "",
            pm.est_zona or "",
            pm.est_dep_res or "",
            pm.est_mun_res or "",
            pm.sisben_grupo or "",
            pm.discapacidad or "",
            pm.capacidad_excepcional or "",
            pm.victima_conflicto or "",
            pm.etnia or "",
            pm.est_sede or "",
            pm.est_jornada or "",
            pm.est_grado_aspira or "",
            pm.grupo_asignado or "",
            f"{pm.acu_nombres or ''} {pm.acu_apellidos or ''}".strip(),
            pm.acu_documento or "",
            pm.acu_telefono or "",
            pm.acu_correo or "",
            pm.estado or "",
            pm.radicado or "",
        ])
        row_i += 1

    # Complementar con estudiantes ya matriculados en el sistema
    eq = q_estudiantes() if iid is not None else Estudiante.query
    for e in eq.order_by(Estudiante.id.asc()).limit(5000).all():
        put(row_i, [
            "TI",
            e.documento or e.codigo or "",
            "",
            "",
            (e.apellido or "").split(" ")[0] if e.apellido else "",
            " ".join((e.apellido or "").split(" ")[1:]) if e.apellido and len((e.apellido or "").split(" ")) > 1 else "",
            (e.nombre or "").split(" ")[0] if e.nombre else "",
            " ".join((e.nombre or "").split(" ")[1:]) if e.nombre and len((e.nombre or "").split(" ")) > 1 else "",
            "",
            "",
            e.direccion or "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            INST_SEDE or "",
            "",
            e.grado or "",
            "",
            e.acudiente or "",
            "",
            e.telefono_acudiente or "",
            e.correo_acudiente or "",
            "MATRICULADO",
            e.codigo or "",
        ])
        row_i += 1

    for col in range(1, len(cols) + 1):
        ws.column_dimensions[get_column_letter(col)].width = 14
    bio = BytesIO()
    wb.save(bio)
    bio.seek(0)
    return send_file(
        bio, as_attachment=True,
        download_name=f"SIMAT_EduTrack_{fecha_hoy()}.xlsx",
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    )


@app.route("/admisiones", methods=["GET", "POST"])
def admisiones():
    """Panel interno CRM de pre-matrículas."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Administrador", "Rectoría", "Coordinación", "Secretaría", "Soporte"]:
        return acceso_denegado()
    iid = institucion_id_actual()
    mensaje = ""
    if request.method == "POST":
        try:
            pid = int(request.form.get("id"))
        except Exception:
            pid = 0
        pm = PreMatricula.query.get(pid)
        if pm and (iid is None or pm.institucion_id == iid or rol_actual() == "Soporte"):
            accion = request.form.get("accion")
            if accion in ["APROBADA", "RECHAZADA", "EN REVISION", "MATRICULADA"]:
                pm.estado = accion
                pm.revisado_por = session.get("usuario", "")
                pm.fecha_revision = f"{fecha_hoy()} {hora_actual()}"
                pm.observaciones = (request.form.get("observaciones") or pm.observaciones or "")[:500]
