@app.route("/api/procsis/plataforma", methods=["GET", "POST"])
def api_procsis_plataforma():
    """Marketing Procsis actualiza novedades/FAQ del login EduTrack."""
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    p = plataforma()
    if request.method == "GET":
        return jsonify({
            "ok": True,
            "version": getattr(p, "version_sistema", None) or getattr(p, "version", "") or "",
            "novedades": getattr(p, "novedades", "") or "",
            "faq": getattr(p, "faq", "") or "",
            "hero_titulo": getattr(p, "hero_titulo", "") or "",
            "hero_texto": getattr(p, "hero_texto", "") or getattr(p, "panel_derecho_texto", "") or "",
            "mantenimiento": getattr(p, "mensaje_mantenimiento", "") or "",
        })
    data = request.get_json(silent=True) or {}
    mapping = {
        "version": ["version_sistema", "version"],
        "novedades": ["novedades"],
        "faq": ["faq"],
        "hero_titulo": ["hero_titulo"],
        "hero_texto": ["hero_texto", "panel_derecho_texto"],
        "mantenimiento": ["mensaje_mantenimiento"],
    }
    for key, attrs in mapping.items():
        if key in data and data[key] is not None:
            val = data[key]
            for attr in attrs:
                if hasattr(p, attr):
                    setattr(p, attr, val)
                    break
    db.session.commit()
    return jsonify({"ok": True, "mensaje": "Plataforma actualizada"})


@app.route("/api/procsis/instituciones/<codigo>/detalle", methods=["GET", "PATCH"])
def api_procsis_inst_detalle(codigo):
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    inst = Institucion.query.filter_by(codigo=codigo).first()
    if not inst and str(codigo).isdigit():
        inst = Institucion.query.get(int(codigo))
    if not inst:
        return jsonify({"ok": False, "error": "No encontrada"}), 404
    if request.method == "GET":
        return jsonify({
            "ok": True,
            "id": inst.id,
            "codigo": inst.codigo,
            "nombre": inst.nombre,
            "sede": getattr(inst, "sede", "") or "",
            "nit": getattr(inst, "nit", "") or "",
            "estado": inst.estado,
            "plan": getattr(inst, "plan", None) or getattr(inst, "plan_contratado", "") or "",
            "logo": getattr(inst, "logo", "") or "",
        })
    data = request.get_json(silent=True) or {}
    for field in ("nombre", "sede", "nit", "estado"):
        if field in data and data[field] is not None and hasattr(inst, field):
            setattr(inst, field, data[field])
    if data.get("plan"):
        if hasattr(inst, "plan"):
            inst.plan = data["plan"]
        if hasattr(inst, "plan_contratado"):
            inst.plan_contratado = data["plan"]
    db.session.commit()
    return jsonify({"ok": True, "codigo": inst.codigo})



