def _puede_planillas_institucionales():
    """Rectoría, Coordinación, Secretaría (y Soporte) pueden descargar planillas."""
    if not requiere_login():
        return False
    rol = (rol_actual() or "").strip()
    if rol in ("Rector", "Rectoría", "Coordinador", "Coordinación", "Secretaria", "Secretaría",
               "Administrador", "Soporte", "Gerente", "Superadmin"):
        return True
    # alias comunes
    r = rol.lower()
    return any(x in r for x in ("rector", "coord", "secret", "admin", "soporte", "gerente"))


