    q = (request.args.get("q") or "").strip()
    insts = Institucion.query.order_by(Institucion.nombre.asc()).all()
    if q:
        like = f"%{q}%"
        insts = [i for i in insts if q.lower() in (i.nombre or "").lower() or q.lower() in (i.codigo or "").lower() or q in (i.nit or "")]
    filas = ""
