            f"<div style='height:100%;width:{bar}%;background:{'#c00' if bar>90 else '#000080'}'></div></div></td>"
            f"<td>{mora_txt}</td>"
            f"<td><a href='/gerencia/recursos-financieros/{inst.id}/historial'>Ver historial</a></td>"
