# Bloqueo visual al ingresar si la institución está SUSPENDIDA
@app.before_request
def _bloqueo_institucion_suspendida():
    try:
        if not session.get("usuario"):
            return None
        rol = (session.get("rol") or "").strip()
        if rol in ("Soporte", "Gerente", "Superadmin", "Comercial", "Marketing"):
            return None  # personal interno entra siempre
        path = request.path or ""
        if path.startswith("/static") or path in ("/login", "/logout", "/recuperar"):
            return None
        iid = session.get("institucion_id")
        if not iid:
            return None
        inst = Institucion.query.get(iid)
        if inst and (inst.estado or "").upper() == "SUSPENDIDA":
            if path.startswith("/bloqueado"):
                return None
            return redirect("/bloqueado")
    except Exception:
        return None




@app.route("/api/webhooks/wompi", methods=["POST", "GET"])
def api_webhook_wompi():
    """
    Webhook Wompi: cuando el pago es APPROVED marca la factura PAGADA y
    reactiva el colegio (sin borrar datos).
    Configure en Wompi: https://TU-DOMINIO/api/webhooks/wompi
    La referencia del pago debe ser el consecutivo del recibo (ej. REC-0002).
    """
    if request.method == "GET":
        return {"ok": True, "service": "EduTrack Wompi webhook", "hint": "POST events here"}, 200
    try:
        payload = request.get_json(force=True, silent=True) or {}
    except Exception:
        payload = {}
    # Aceptar body form también
    if not payload and request.form:
        payload = {k: request.form.get(k) for k in request.form}

    # Extraer transaction (formatos Wompi / genéricos)
    tx = {}
    if isinstance(payload.get("data"), dict):
        tx = payload["data"].get("transaction") or payload["data"]
    if not tx and isinstance(payload.get("transaction"), dict):
        tx = payload["transaction"]
    if not tx:
        tx = payload

    status = (
        (tx.get("status") or tx.get("estado") or payload.get("status") or "")
        .strip()
        .upper()
    )
    ref = (
        tx.get("reference")
        or tx.get("referencia")
        or tx.get("payment_link_id")
        or payload.get("reference")
        or ""
    )
    ref = str(ref).strip()
    tx_id = str(tx.get("id") or tx.get("transaction_id") or payload.get("id") or "")[:80]
    amount_cents = tx.get("amount_in_cents") or tx.get("amount") or payload.get("amount_in_cents")

    # Eventos no aprobados: ack sin error (Wompi reintenta si 5xx)
    if status and status not in ("APPROVED", "APPROVED_STATUS", "OK", "PAGADO", "COMPLETED", "SUCCESS"):
        try:
            registrar_auditoria("Wompi webhook ignorado", f"status={status} ref={ref}")
        except Exception:
            pass
        return {"ok": True, "processed": False, "status": status}, 200

    if not ref and not status:
        return {"ok": False, "error": "sin referencia ni estado"}, 400

    f = _buscar_factura_por_referencia(ref)
    if not f:
        # intentar por id en data.reference nested
        try:
            registrar_auditoria("Wompi sin factura", f"ref={ref} status={status}")
        except Exception:
            pass
        return {"ok": False, "error": f"factura no encontrada para ref={ref}"}, 404

    monto = None
    try:
        if amount_cents is not None:
            monto = float(amount_cents) / 100.0 if float(amount_cents) > 10000 else float(amount_cents)
    except Exception:
        monto = None

    ok, msg = _aplicar_pago_factura(f, fuente="wompi", ref_externa=tx_id or ref, monto=monto)
    if ok:
        return {
            "ok": True,
            "processed": True,
            "factura": msg,
            "institucion_id": f.institucion_id,
            "estado_factura": "PAGADO",
        }, 200
    return {"ok": False, "error": msg}, 400


@app.route("/api/webhooks/wompi/test-pago", methods=["POST"])
def api_webhook_wompi_test():
    """Prueba interna (Gerencia/Soporte): simula pago APPROVED sobre un REC-XXXX."""
    if not requiere_login() or rol_actual() not in ("Gerente", "Superadmin", "Soporte", "Administrador"):
        return {"ok": False, "error": "no autorizado"}, 403
    ref = (request.json or {}).get("reference") or request.form.get("reference") or ""
    f = _buscar_factura_por_referencia(ref)
    if not f:
        return {"ok": False, "error": "factura no encontrada"}, 404
    ok, msg = _aplicar_pago_factura(f, fuente="wompi-test", ref_externa="test")
    return {"ok": ok, "factura": msg, "institucion_id": f.institucion_id}, (200 if ok else 400)


