@app.route("/estudiante/portal")
def estudiante_portal():
    eid = session.get("est_portal_id")
    if not eid:
        return redirect("/estudiante-login")
    e = Estudiante.query.get(eid)
    if not e:
        session.pop("est_portal_id", None)
        return redirect("/estudiante-login")
    iid = e.institucion_id
    grado = (e.grado or "").strip()
    acts = ActividadAsignada.query.filter_by(activa=True)
    if iid:
        acts = acts.filter_by(institucion_id=iid)
    if grado:
        acts = acts.filter(
            or_(ActividadAsignada.grado == grado, ActividadAsignada.grado == "", ActividadAsignada.grado.is_(None))
        )
    docente_f = (session.get("est_portal_docente") or "").strip()
    if docente_f:
        acts = acts.filter(
            or_(
                ActividadAsignada.docente_nombre.ilike(f"%{docente_f}%"),
                ActividadAsignada.docente_usuario.ilike(f"%{docente_f}%"),
            )
        )
    lista = acts.order_by(ActividadAsignada.id.desc()).limit(40).all()
    cards = ""
    for a in lista:
        ya = EntregaEstudiante.query.filter_by(actividad_id=a.id, estudiante_id=e.id).first()
        est = f"<span style='color:#15803d;font-weight:700'>Entregada {ya.fecha} {ya.hora}</span>" if ya else "<span style='color:#b45309'>Pendiente de entrega</span>"
        cards += f"""
        <div style="background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px;margin-bottom:12px">
          <b style="color:#0B2D57">{a.titulo}</b>
          <div style="font-size:13px;color:#64748b;margin:6px 0">{a.asignatura} · Grado {a.grado or '—'} · Docente {a.docente_nombre or a.docente_usuario}</div>
          <p style="font-size:13px;color:#334155">{(a.descripcion or '')[:220]}</p>
          <div style="font-size:12px;margin:8px 0">{est} · Límite: {a.fecha_limite or '—'}</div>
          <a class="btn" href="/estudiante/entregar/{a.id}" style="font-size:13px;padding:8px 12px">{"Ver / actualizar entrega" if ya else "Subir entrega"}</a>
        </div>"""
    body = f"""
<div style="max-width:720px;margin:0 auto;padding:20px;font-family:Segoe UI,sans-serif">
  <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">
    <div>
      <h1 style="margin:0;color:#0B2D57">Hola, {session.get('est_portal_nombre') or e.nombre}</h1>
      <p style="color:#64748b;margin:4px 0 0;font-size:13px">Grado {e.grado or '—'} · Código {e.codigo or '—'} · Portal de actividades</p>
    </div>
    <a href="/estudiante/salir" style="font-weight:700;color:#b91c1c">Salir</a>
  </div>
  <h2 style="color:#0B2D57;font-size:18px;margin-top:22px">Actividades asignadas</h2>
  {cards or "<p style='color:#64748b'>No hay actividades publicadas para su grado por ahora.</p>"}
</div>
"""
    return page("Portal estudiante", body)


@app.route("/estudiante/salir")
def estudiante_salir():
    for k in list(session.keys()):
        if str(k).startswith("est_portal"):
            session.pop(k, None)
    return redirect("/estudiante-login")


@app.route("/estudiante/entregar/<int:aid>", methods=["GET", "POST"])
def estudiante_entregar(aid):
    eid = session.get("est_portal_id")
    if not eid:
        return redirect("/estudiante-login")
    e = Estudiante.query.get(eid)
    a = ActividadAsignada.query.get_or_404(aid)
    msg = error = ""
    if request.method == "POST":
        files = request.files.getlist("archivos")
        files = [f for f in files if f and f.filename]
        if len(files) > ENTREGA_MAX_FILES:
            error = f"Máximo {ENTREGA_MAX_FILES} archivos por entrega."
        else:
            ok_files = []
            for f in files:
                ext = os.path.splitext(f.filename)[1].lower()
                if ext not in ENTREGA_EXT_OK:
                    error = f"Tipo no permitido: {ext}. Use PDF, Office, imagen o video."
                    break
                f.seek(0, 2)
                size = f.tell()
                f.seek(0)
                if size > ENTREGA_MAX_BYTES:
                    error = f"{f.filename} supera 8 MB."
                    break
                ok_files.append((f, size, ext))
            if not error:
                ent = EntregaEstudiante.query.filter_by(actividad_id=a.id, estudiante_id=e.id).first()
                if not ent:
                    ent = EntregaEstudiante(
                        institucion_id=e.institucion_id or a.institucion_id,
                        actividad_id=a.id,
                        estudiante_id=e.id,
                    )
                    db.session.add(ent)
                ent.enviado_por = (request.form.get("enviado_por") or session.get("est_portal_nombre") or "").strip()[:160]
                ent.integrantes = (request.form.get("integrantes") or "").strip()[:2000]
                ent.comentario = (request.form.get("comentario") or "").strip()[:2000]
                ent.fecha = fecha_hoy()
                ent.hora = hora_actual()
                ent.estado = "ENTREGADA"
                db.session.flush()
                # guardar archivos nuevos
                folder = os.path.join(app.root_path, ENTREGAS_DIR, str(ent.id))
                os.makedirs(folder, exist_ok=True)
                for f, size, ext in ok_files:
                    safe = re.sub(r"[^a-zA-Z0-9._-]+", "_", f.filename)[:80]
                    fname = f"{int(datetime.utcnow().timestamp())}_{safe}"
                    path = os.path.join(folder, fname)
                    f.save(path)
                    db.session.add(EntregaArchivo(
                        entrega_id=ent.id,
                        nombre_original=f.filename[:255],
                        ruta=f"/static/uploads/entregas/{ent.id}/{fname}",
                        mime=f.mimetype or ext,
                        tamano=size,
                    ))
                db.session.commit()
                msg = "Entrega registrada con fecha y hora. El docente podrá revisarla."
    ent = EntregaEstudiante.query.filter_by(actividad_id=a.id, estudiante_id=e.id).first()
    archivos_html = ""
    if ent:
        for ar in EntregaArchivo.query.filter_by(entrega_id=ent.id).all():
            archivos_html += f'<li><a href="{ar.ruta}" target="_blank">{ar.nombre_original}</a> ({ar.tamano // 1024} KB)</li>'
    body = f"""
<div style="max-width:640px;margin:20px auto;font-family:Segoe UI,sans-serif;padding:16px">
  <a href="/estudiante/portal">← Volver</a>
  <h1 style="color:#0B2D57">{a.titulo}</h1>
  <p style="color:#64748b;font-size:13px">{a.asignatura} · {a.docente_nombre or a.docente_usuario} · Límite {a.fecha_limite or '—'}</p>
  <p>{a.descripcion or ''}</p>
  {"<div class='msg ok'>"+msg+"</div>" if msg else ""}
  {"<div class='msg danger'>"+error+"</div>" if error else ""}
  <form method="POST" enctype="multipart/form-data" style="background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px">
    <label>¿Quién envía?</label>
    <input name="enviado_por" value="{(ent.enviado_por if ent else session.get('est_portal_nombre') or '')}" required>
    <label>Integrantes del trabajo (si es grupal)</label>
    <textarea name="integrantes" rows="2" placeholder="Nombres de quienes participaron">{(ent.integrantes if ent else '')}</textarea>
    <label>Comentario para el docente</label>
    <textarea name="comentario" rows="2">{(ent.comentario if ent else '')}</textarea>
    <label>Archivos (máx. 3 · 8 MB c/u · PDF, Word, PowerPoint, imagen, video)</label>
    <input type="file" name="archivos" multiple accept=".pdf,.doc,.docx,.ppt,.pptx,.jpg,.jpeg,.png,.mp4,.mov,.zip">
    <button type="submit" class="btn" style="margin-top:12px">Enviar entrega</button>
  </form>
  {"<div style='margin-top:14px'><b>Archivos ya subidos</b><ul>"+archivos_html+"</ul></div>" if archivos_html else ""}
  {"<p style='font-size:12px;color:#64748b'>Última entrega: "+(ent.fecha or '')+" "+(ent.hora or '')+" · Estado: "+(ent.estado or '')+"</p>" if ent else ""}
</div>
"""
    return page("Entregar actividad", body)


