@app.route("/coordinacion/reportes/niveles")
def coord_reportes_niveles():
    """Porcentaje de reprobación por niveles — tabla como la imagen de referencia."""
    if not _rol_coord_reportes_ok():
        return redirect("/login")
    iid = _iid_sesion()
    periodo = (request.args.get("periodo") or "Periodo 1").strip()
    sede = (request.args.get("sede") or "").strip()
    jornada = (request.args.get("jornada") or "").strip()
    nivel = (request.args.get("nivel") or "").strip()  # Primaria / Bachillerato

    q = Estudiante.query
    if iid:
        q = q.filter_by(institucion_id=iid)
    if sede:
        try:
            q = q.filter(Estudiante.sede.ilike(f"%{sede}%"))
        except Exception:
            pass
    if jornada:
        try:
            q = q.filter(Estudiante.jornada.ilike(f"%{jornada}%"))
        except Exception:
            pass
    estudiantes = q.limit(3000).all()

    # Filtrar por nivel (heurística de grado)
    def _es_bachiller(g):
        g = (g or "").upper()
        return any(x in g for x in ("6", "7", "8", "9", "10", "11", "SEXTO", "SEPT", "OCTAV", "NOVENO", "DECIMO", "UNDÉC", "UNDEC"))

    def _es_primaria(g):
        g = (g or "").upper()
        return any(x in g for x in ("1", "2", "3", "4", "5", "TRANS", "PREES", "JARDIN", "PRIMERO", "SEGUNDO", "TERCERO", "CUARTO", "QUINTO"))

    if nivel.lower().startswith("bach"):
        estudiantes = [e for e in estudiantes if _es_bachiller(e.grado)]
    elif nivel.lower().startswith("prim"):
        estudiantes = [e for e in estudiantes if _es_primaria(e.grado)]

    # Agrupar por jornada + salón (grado-grupo)
    grupos = {}
    for e in estudiantes:
        jor = (getattr(e, "jornada", None) or "MAÑANA").upper()
        salon = f"{(e.grado or 'SIN').strip()}-{ (getattr(e,'grupo',None) or 'A').strip() }".upper()
        key = (jor, salon)
        grupos.setdefault(key, []).append(e)

    filas_html = ""
    sum_alumnos = sum_inv = 0
    sum_buckets = [0] * 6  # 1..5 y 6+

    for (jor, salon), lista in sorted(grupos.items()):
        n = len(lista)
        invictos = 0
        buckets = [0] * 6
        for e in lista:
            perdidas, n_asig = _areas_perdidas_estudiante(e.id, iid, periodo)
            if n_asig == 0:
                # sin notas: no cuenta como invicto ni reprobado
                continue
            if perdidas == 0:
                invictos += 1
            elif perdidas >= 6:
                buckets[5] += 1
            else:
                buckets[perdidas - 1] += 1
        sum_alumnos += n
        sum_inv += invictos
        for i in range(6):
            sum_buckets[i] += buckets[i]
        pct_inv = round(invictos * 100 / n) if n else 0

        def cell(num, total_n):
            pct = round(num * 100 / total_n) if total_n else 0
            return f"<td>{num}</td><td>{pct}</td>"

        cells = cell(invictos, n) + "".join(cell(buckets[i], n) for i in range(6))
        filas_html += f"<tr><td class='left'>{jor}</td><td class='left'>{salon}</td><td>{n}</td>{cells}</tr>"

    pct_inv_t = round(sum_inv * 100 / sum_alumnos) if sum_alumnos else 0

    def cell_t(num):
        pct = round(num * 100 / sum_alumnos) if sum_alumnos else 0
        return f"<td>{num}</td><td>{pct}</td>"

    sum_row = f"""<tr class="sum"><td class="left" colspan="2">SUMATORIA</td><td>{sum_alumnos}</td>
      {cell_t(sum_inv)}{''.join(cell_t(sum_buckets[i]) for i in range(6))}</tr>"""

    # Opciones filtros
    per_opts = "".join(
        f'<option value="Periodo {i}" {"selected" if periodo==f"Periodo {i}" else ""}>Periodo {i}</option>'
        for i in (1, 2, 3, 4)
    )
    inst_nombre = ""
    try:
        inst = Institucion.query.get(iid) if iid else None
        inst_nombre = (inst.nombre if inst else "") or "INSTITUCIÓN"
    except Exception:
        inst_nombre = "INSTITUCIÓN"

    inner = f"""
    <h1 style="font-size:18px">{inst_nombre.upper()}</h1>
    <h2>Porcentaje de Reprobación por Niveles — Periodo: {periodo} — Sede: {sede or "Todas"} — Jornada: {jornada or "Todas"}</h2>
    <form class="cr-filters" method="GET">
      <select name="periodo">{per_opts}</select>
      <select name="sede">
        <option value="">Todas las sedes</option>
        <option value="Principal" {"selected" if sede=="Principal" else ""}>Principal</option>
        <option value="Rural" {"selected" if sede=="Rural" else ""}>Rural</option>
      </select>
      <select name="jornada">
        <option value="">Todas las jornadas</option>
        <option value="MAÑANA" {"selected" if jornada.upper()=="MAÑANA" else ""}>Mañana</option>
        <option value="TARDE" {"selected" if jornada.upper()=="TARDE" else ""}>Tarde</option>
        <option value="UNICA" {"selected" if jornada.upper()=="UNICA" else ""}>Única</option>
      </select>
      <select name="nivel">
        <option value="">Todos los niveles</option>
        <option value="Primaria" {"selected" if nivel.lower().startswith("prim") else ""}>Primaria</option>
        <option value="Bachillerato" {"selected" if nivel.lower().startswith("bach") else ""}>Bachillerato</option>
      </select>
      <button type="submit">Mostrar</button>
    </form>
    <div style="overflow:auto">
    <table class="cr-table">
      <tr>
        <th rowspan="2">JORNADA</th><th rowspan="2">SALÓN</th><th rowspan="2">ALUMNOS</th>
        <th colspan="2">INVICTOS</th>
        <th colspan="2">1 ÁREA</th><th colspan="2">2 ÁREAS</th><th colspan="2">3 ÁREAS</th>
        <th colspan="2">4 ÁREAS</th><th colspan="2">5 ÁREAS</th><th colspan="2">6 o MÁS</th>
      </tr>
      <tr>
        <th>#</th><th>%</th><th>#</th><th>%</th><th>#</th><th>%</th><th>#</th><th>%</th>
        <th>#</th><th>%</th><th>#</th><th>%</th><th>#</th><th>%</th>
      </tr>
      {filas_html or "<tr><td colspan='17'>Sin estudiantes o sin notas en este filtro</td></tr>"}
      {sum_row if filas_html else ""}
    </table>
    </div>
    <p style="font-size:11px;color:#64748b;margin-top:10px;text-align:center">
      Invicto = 0 áreas perdidas (nota &lt; 3.0). Cálculo sobre asignaturas con notas en el periodo seleccionado.
    </p>
    """
    return page("Reprobación por niveles", _shell_coord_reportes("", inner, "niveles"))


@app.route("/coordinacion/reportes/mejores")
def coord_reportes_mejores():
    if not _rol_coord_reportes_ok():
        return redirect("/login")
    iid = _iid_sesion()
    periodo = (request.args.get("periodo") or "Periodo 1").strip()
    grado = (request.args.get("grado") or "").strip()
    q = Estudiante.query
    if iid:
        q = q.filter_by(institucion_id=iid)
    if grado:
        q = q.filter(Estudiante.grado.ilike(f"%{grado}%"))
    ranking = []
    for e in q.limit(800).all():
        p = _nota_final_estudiante(e.id, iid, periodo)
        if p is not None:
            ranking.append((p, e))
    ranking.sort(key=lambda x: -x[0])
    filas = ""
    for i, (p, e) in enumerate(ranking[:30], 1):
        filas += f"<tr><td>{i}</td><td class='left'>{e.apellido or ''} {e.nombre or ''}</td><td>{e.grado or ''}</td><td>{e.codigo or ''}</td><td><b>{p:.2f}</b></td></tr>"
    per_opts = "".join(
        f'<option {"selected" if periodo==f"Periodo {i}" else ""}>Periodo {i}</option>' for i in (1, 2, 3, 4)
    )
    inner = f"""
    <h2>Mejores estudiantes — {periodo}</h2>
    <form class="cr-filters" method="GET">
      <select name="periodo">{per_opts}</select>
      <select name="grado"><option value="">Todos los grados</option>
        {''.join(f'<option value="{g}" {"selected" if grado==g else ""}>{g}</option>' for g in (grados_disponibles() if "grados_disponibles" in dir() else []))}
      </select>
      <button type="submit">Mostrar</button>
    </form>
    <table class="cr-table">
      <tr><th>#</th><th>Estudiante</th><th>Grado</th><th>Código</th><th>Promedio</th></tr>
      {filas or "<tr><td colspan='5'>Sin notas en este periodo</td></tr>"}
    </table>
    """
    return page("Mejores estudiantes", _shell_coord_reportes("Mejores Estudiantes", inner, "mejores"))


