@app.route("/coordinacion/reportes/salones")
def coord_reportes_salones():
    if not _rol_coord_reportes_ok():
        return redirect("/login")
    iid = _iid_sesion()
    periodo = (request.args.get("periodo") or "Periodo 1").strip()
    q = Estudiante.query
    if iid:
        q = q.filter_by(institucion_id=iid)
    grupos = {}
    for e in q.limit(2000).all():
        key = f"{e.grado or '—'} / {getattr(e,'grupo',None) or 'A'}"
        grupos.setdefault(key, []).append(e)
    filas = ""
    for salon, lista in sorted(grupos.items()):
        proms = []
        for e in lista:
            p = _nota_final_estudiante(e.id, iid, periodo)
            if p is not None:
                proms.append(p)
        prom = sum(proms) / len(proms) if proms else None
        filas += f"<tr><td class='left'>{salon}</td><td>{len(lista)}</td><td>{len(proms)}</td><td><b>{prom:.2f}</b></td></tr>" if prom is not None else f"<tr><td class='left'>{salon}</td><td>{len(lista)}</td><td>0</td><td>—</td></tr>"
    inner = f"""
    <h2>Rendimiento académico por salones — {periodo}</h2>
    <form class="cr-filters" method="GET">
      <select name="periodo">{''.join(f'<option {"selected" if periodo==f"Periodo {i}" else ""}>Periodo {i}</option>' for i in (1,2,3,4))}</select>
      <button type="submit">Mostrar</button>
    </form>
    <table class="cr-table">
      <tr><th>Salón</th><th>Alumnos</th><th>Con notas</th><th>Promedio salón</th></tr>
      {filas or "<tr><td colspan='4'>Sin datos</td></tr>"}
    </table>
    """
    return page("Rendimiento salones", _shell_coord_reportes("Rendimiento por Salones", inner, "salones"))


