@app.route("/coordinacion/reportes/asignatura-salon")
@app.route("/coordinacion/reportes/asignatura-grado")
@app.route("/coordinacion/reportes/areas")
def coord_reportes_areas():
    if not _rol_coord_reportes_ok():
        return redirect("/login")
    iid = _iid_sesion()
    periodo = (request.args.get("periodo") or "Periodo 1").strip()
    q = NotaRegistro.query
    if iid:
        q = q.filter_by(institucion_id=iid)
    q = q.filter(NotaRegistro.periodo.ilike(f"%{periodo.replace('Periodo ','')}%"))
    by_a = {}
    for r in q.limit(8000).all():
        a = (r.asignatura or "—").strip()
        if r.valor is not None and a.lower() != "general":
            by_a.setdefault(a, []).append(float(r.valor))
    filas = ""
    for a, vs in sorted(by_a.items()):
        perd = sum(1 for v in vs if v < 3.0)
        filas += f"<tr><td class='left'>{a}</td><td>{len(vs)}</td><td>{sum(vs)/len(vs):.2f}</td><td>{perd}</td><td>{round(perd*100/len(vs))}%</td></tr>"
    inner = f"""
    <h2>Rendimiento por áreas / asignaturas — {periodo}</h2>
    <form class="cr-filters" method="GET">
      <select name="periodo">{''.join(f'<option {"selected" if periodo==f"Periodo {i}" else ""}>Periodo {i}</option>' for i in (1,2,3,4))}</select>
      <button type="submit">Mostrar</button>
    </form>
    <table class="cr-table">
      <tr><th>Área / Asignatura</th><th>Notas</th><th>Promedio</th><th># &lt; 3.0</th><th>% reprobación</th></tr>
      {filas or "<tr><td colspan='5'>Sin datos</td></tr>"}
    </table>
    """
    return page("Rendimiento áreas", _shell_coord_reportes("Rendimiento por Áreas", inner, "areas"))


