def _support_fmt(texto):
    """Escapa el texto y convierte **negrita** en <strong>. Seguro: primero escapa, luego marca."""
    seguro = _esc(texto or "")
    return re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", seguro, flags=re.S)


